(window.GIM_TS=window.GIM_TS||{})["Yevamot.1"]={"from":24,"a":[["\u0003מי סברת\u0004 \u0005[האם סבור אתה]\u0006 ש\u0003עשו בית שמאי כדבריהם\u0004 עצמם בפועל? \u0003לא עשו בית שמאי כדבריהם,\u0004 ולא נחלקו אלא בסברה. \u0003ור' יוחנן אמר: עשו ועשו.\u0004 ומעירים: \u0003ו\u0004דבר זה שנוי \u0003בפלוגתא\u0004 \u0005[במחלוקת]\u0006 של \u0003רב ושמואל\u0004 גם כן. ש\u0003רב אומר: לא עשו בית שמאי כדבריהם, ושמואל אמר: עשו ועשו.\u0004","ומבררים: \u0003אימת\u0004 \u0005[מתי]\u0006 מדובר כאן? \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 \u0003קודם\u0004 שיצאה \u0003בת קול\u0004 ואמרה כי הלכה כבית הלל — \u0003מאי טעמא דמאן דאמר\u0004 \u0005[מה הטעם של מי שאומר]\u0006 ש\u0003לא עשו,\u0004 ומדוע לא יעשו בית שמאי כדבריהם? \u0003ואלא לאחר\u0004 שיצאה \u0003בת קול\u0004 — \u0003מאי טעמא דמאן דאמר\u0004 \u0005[מה הטעם\u0006 אם כן \u0005של מי שאומר]\u0006 ש\u0003עשו?\u0004 הלא נפסקה הלכה על ידי בת קול!","ומשיבים: בשני המקרים אין קושי, שכן \u0003אי בעית אימא\u0004 \u0005[אם תרצה אמור]\u0006 שהיה זה \u0003קודם בת קול, ואי בעית אימא\u0004 \u0005[ואם תרצה אמור]\u0006 שהיה זה \u0003לאחר בת קול.\u0004 ומפרשים: \u0003אי בעית אימא\u0004 \u0005[אם תרצה אמור]\u0006 שהיה זה \u0003קודם בת קול, וכגון\u0004 שהמצב היה כך: ש\u0003בית הלל\u0004 היו \u0003רובא\u0004 \u0005[הרוב]\u0006 במספר החכמים, ועל כן, \u0003למאן דאמר\u0004 \u0005[ל\u0006דעת \u0005מי שאומר]\u0006 ש\u0003לא עשו — דהא\u0004 \u0005[שהרי]\u0006 \u0003בית הלל\u0004 הם \u0003רובא\u0004 \u0005[הרוב]\u0006 ויש איפוא לנהוג כדעת הרוב, וכך אכן נהגו.","\u0003ומאן דאמר\u0004 \u0005[ו\u0006לדעת \u0005מי שאומר]\u0006 ש\u0003עשו —\u0004 סברו בית שמאי: \u0003כי אזלינן בתר רובא\u0004 \u0005[כאשר הולכים אנו אחר הרוב]\u0006 — הרי זה רק \u0003היכא דכי הדדי נינהו\u0004 \u0005[במקום ש\u0006החולקים שווים \u0005זה לזה\u0006 בחכמתם\u0005],\u0006 אבל \u0003הכא\u0004 \u0005[כאן],\u0006 \u0003בית שמאי מחדדי טפי\u0004 \u0005[מחודדים יותר]\u0006 בחכמתם מבית הלל ולכן נהגו כדבריהם, אף שהיו מיעוט.","\u0003ואי בעית אימא\u0004 \u0005[ואם תרצה אמור]\u0006 שהיה הדבר \u0003לאחר\u0004 שיצאה \u0003בת קול, מאן דאמר\u0004 \u0005[מי שאומר]\u0006 ש\u0003לא עשו\u0004 בית שמאי כדבריהם — \u0003דהא נפקא\u0004 \u0005[שהרי יצאה]\u0006 \u0003בת קול, ומאן דאמר\u0004 \u0005[ומי שאומר]\u0006 ש\u0003עשו\u0004 — שיטת \u0003ר' יהושע היא,\u0004 ש\u0003אמר\u0004 במקום אחר: \u0003אין משגיחין בבת קול\u0004 לפסוק הלכה על פיה.","וחוזרת השאלה: \u0003ומאן דאמר\u0004 \u0005[ו\u0006לדעת \u0005מי שאומר]\u0006 ש\u0003עשו,\u0004 הרי \u0003קרינן\u0004 \u0005[אנו\u0006 יכולים \u0005לקרוא]\u0006 ולדון ש\u0003כאן\u0004 יש איסור \u0003\"לא תתגדדו\",\u0004 במובן — \u0003לא תעשו אגודות אגודות! אמר אביי: כי אמרינן\u0004 \u0005[כאשר אנו אומרים]\u0006 איסור \u0003\"לא תתגדדו\" —\u0004 הרי זה \u0003כגון שתי בתי דינין\u0004 הנמצאים \u0003בעיר אחת, הללו מורים כדברי בית שמאי, והללו מורים כדברי בית הלל, אבל שתי בתי דינים בשתי עיירות — לית לן\u0004 \u0005[אין לנו]\u0006 \u0003בה\u0004 איסור.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבא: והא\u0004 \u0005[והרי]\u0006 \u0003בית שמאי ובית הלל כשתי בתי דינים בעיר אחת דמי\u0004 \u0005[\u0006הם \u0005נחשבים],\u0006 שהרי מחלוקתם לא היתה במקום מסויים, ובית שמאי ובית הלל היו בכל מקום! \u0003אלא אמר רבא: כי אמרינן\u0004 \u0005[כאשר אומרים אנו]\u0006 איסור \u0003\"לא תתגדדו\" —\u0004 הרי זה \u0003כגון בית דין בעיר אחת,\u0004 ש\u0003פלג\u0004 (חלק) ממנו \u0003מורין כדברי בית שמאי, ופלג מורין כדברי בית הלל. אבל שתי בתי דינין\u0004 נפרדים \u0003בעיר אחת — לית לן בה\u0004 \u0005[אין לנו]\u0006 איסור.","ומנסים להביא ראיות לענין זה שאמרנו, \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ראיה ממה ששנינו: \u0003במקומו של ר' אליעזר היו כורתים עצים לעשות\u0004 מהם \u0003פחמים בשבת,\u0004 כדי \u0003לעשות\u0004 ולתקן באמצעותם \u0003ברזל\u0004 שישמש כסכין של מילה למול בו ביום. שלדעת ר' אליעזר לא רק מצות המילה עצמה דוחה שבת, אלא גם הכנתם ועשייתם של כל המכשירים הצריכים לה, אף הם דוחים את השבת. ועוד: \u0003במקומו של ר' יוסי הגלילי היו אוכלים בשר עוף בחלב,\u0004 שלדעתו אין איסור אלא בבשר בהמה בחלב, ולא בעוף.","ונדקדק: \u0003במקומו של ר' אליעזר — אין\u0004 \u0005[כן],\u0006 אולם \u0003במקומו של ר' עקיבא\u0004 למשל — \u0003לא. דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005],\u0006 \u0003כלל אמר ר' עקיבא: כל מלאכה שאפשר\u0004 היה \u0003לעשותה מערב שבת — אין דוחה את השבת\u0004, גם אם יש בה מצוה. ואין השבת נדחית מפני מצוה שזמנה בשבת אלא כאשר אי אפשר להכינה קודם לכן (כגון המילה עצמה, שאי אפשר להקדימה).","ושואלים: \u0003והאי מאי תיובתא\u0004 \u0005[וזו מה קושיה\u0006 היא\u0005]\u0006 הלא כבר אמרנו כי אם שינוי המנהגים הוא ב\u0003מקומות מקומות\u0004 הרי זה \u0003שאני\u0004 \u0005[שונה]\u0006 ואין בכך משום \"לא תתגודדו\", ובפירוש נאמר כאן שנעשה הדבר במקומו של ר' אליעזר ואין בכך איפוא משום אגודות אגודות! ותוהים: ובאמת, \u0003ודקארי לה מאי קארי לה\u0004 \u0005[ו\u0006מי \u0005שהקשה אותה מה הקשה אותה],\u0006 מה הוקשה לו? שהרי נאמר במפורש שהדבר נעשה במקומו של ר' אליעזר?!","ומשיבים: \u0003סלקא דעתך אמינא\u0004 \u0005[יעלה על דעתך לומר]\u0006 כי \u0003משום חומרא\u0004 \u0005[החומרה]\u0006 שב\u0003שבת — כמקום אחד דמי\u0004 \u0005[נחשב],\u0006 שההיתר של שוני מנהגים במקומות שונים הוא באיסורים אחרים, אבל איסור שבת החמור אין ראוי לנהוג בו מנהגים שונים אף במקומות נבדלים כדי שלא יבואו לזלזל בו, על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 שגם בזה אפשר לנהוג בדרכים שונות במקומות שונים.","ומנסים להביא ראיה אחרת מענין שבת, \u0003תא שמע\u0004 \u0005[בא\u0006 ו\u0005שמע],\u0006 ש\u0003ר' אבהו, כי איקלע לאתריה\u0004 \u0005[כאשר\u0006 היה \u0005מזדמן למקומו]\u0006 של \u0003ר' יהושע בן לוי הוה\u0004 \u0005[היה]\u0006 ר' אבהו \u0003מטלטל\u0004 בשבת \u0003שרגא\u0004 \u0005[מנורה]\u0006 לאחר שכבתה האש שהיתה דולקת בה באותה שבת, שר' יהושע בן לוי פסק כדעת האומר שמותר לטלטל מוקצה כזה. \u0003וכי איקלע לאתריה\u0004 \u0005[וכאשר\u0006 היה \u0005מזדמן למקומו]\u0006 של \u0003ר' יוחנן\u0004 שאסר טלטול מוקצה כזה בשבת, \u0003לא הוה\u0004 \u0005[היה]\u0006 \u0003מטלטל שרגא\u0004 \u0005[מנורה].\u0006","ושוב תוהים: \u0003והאי מאי קושיא\u0004 \u0005[ו\u0006אף \u0005זו מה קושיה\u0006 היא\u0005]\u0006 \u0003ו\u0004כי \u0003לא אמרינן\u0004 \u0005[אומרים אנו]\u0006 כי נוהג שונה ב\u0003מקומות\u0004 שונים \u0003שאני\u0004 \u0005[שונה]?\u0006 ושינוי המנהגים כאן היה הלא בשני מקומות נבדלים! ומסבירים: \u0003אנן, הכי קאמרינן\u0004 \u0005[אנחנו, כך אומרים אנו],\u0006 זו היתה השאלה: \u0003ר' אבהו\u0004 עצמו, \u0003היכי עביד הכא הכי והיכי עביד הכא הכי\u0004 \u0005[איך עשה כאן כך ואיך עשה כאן כך]?\u0006","ומשיבים: לאמיתו של דבר \u0003ר' אבהו כר' יהושע בן לוי סבירא ליה\u0004 \u0005[סבור הוא]\u0006 ולשיטתו מותר טלטול מוקצה זה. \u0003וכי מקלע לאתריה\u0004 \u0005[וכאשר\u0006 היה \u0005מזדמן למקומו]\u0006 של \u0003ר' יוחנן לא הוה\u0004 \u0005[היה]\u0006 \u0003מטלטל משום כבודו\u0004 של \u0003ר' יוחנן,\u0004 שלא רצה להראות שאינו סבור כדברי החכם הגדול הזה, כשהוא מצוי במקומו. ושואלים: \u0003והאיכא שמעא\u0004 \u0005[והרי יש השמש]\u0006 שהיה מלווה את ר' אבהו והיה רואה אותו נוהג לטלטל מוקצה כזה ולא חשש שהשמש יטלטל גם במקומו של ר' יוחנן! ומשיבים: \u0003דמודע ליה לשמעא\u0004 \u0005[שהיה מודיע לו לשמש]\u0006 ומסביר לו מדוע הוא משנה מנהגיו.","ומנסים להציע פתרון אחר לשאלה, \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ראיה לדבר ממה ששנינו במשנתנו: \u0003אף על פי שאלו אוסרים ואלו מתירים — לא נמנעו בית שמאי מלישא נשים מבית הלל, ולא בית הלל מבית שמאי.\u0004 ומעתה, \u0003אי אמרת בשלמא\u0004 \u0005[נניח אם אתה אומר]\u0006 כי \u0003לא עשו\u0004 בית שמאי כדבריהם, \u0003משום הכי\u0004 \u0005[כך]\u0006 \u0003לא נמנעו. אלא אי אמרת\u0004 \u0005[אם אומר אתה]\u0006 ש\u0003עשו\u0004 כדבריהם, \u0003אמאי\u0004 \u0005[מדוע]\u0006 אם כן \u0003לא נמנעו\u0004 מלשאת נשים אלה מאלה?","\u0003בשלמא\u0004 \u0005[נניח]\u0006 ש\u0003בית שמאי מבית הלל לא נמנעו,\u0004 שכן אף שלדעת בית שמאי הצרה היתה צריכה להתייבם או לחלוץ, אולם נישאה לאחר בלא חליצה, הרי גם כשנולדו ילדים מנישואין כאלה ש\u0003בני חייבי לאוין\u0004 בלבד \u0003נינהו\u0004 \u0005[הם]\u0006 (לאו של \"לא תהיה אשת המת החוצה\") ואין בכך איסור כרת, ואין הילדים ממזרים.","\u0003אלא בית הלל מבית שמאי אמאי\u0004 \u0005[מדוע]\u0006 \u0003לא נמנעו\u0004 מלשאת? הלא לדעתם בני הצרות הללו שהתייבמו \u0003בני חייבי כריתות\u0004 (שלא בטל מהן איסור אשת אח) וילדים כאלה \u0003ממזרים נינהו\u0004 \u0005[הם],\u0006 וכיצד יכלו לשאת נשים משם?","\u0003וכי תימא\u0004 \u0005[ואם תאמר]\u0006 כי \u0003קסברי\u0004 \u0005[סבורים]\u0006 \u0003בית הלל\u0004 ש\u0003אין ממזר מחייבי כריתות\u0004 (אלא מחייבי מיתת בית דין בלבד) — \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003ר' אלעזר: אף על פי שנחלקו בית שמאי ובית הלל בצרות, מודים שאין ממזר אלא ממי שאיסורו איסור ערוה וענוש כרת,\u0004 הרי שבני צרות שהם חייבי כרת, ממזרים הם לבית הלל! \u0003אלא לאו שמע מינה\u0004 \u0005[האם לא תלמד ממנה]\u0006 \u0003שלא עשו\u0004 בית שמאי כדבריהם!","ודוחים: \u0003לא, לעולם\u0004 תאמר ש\u0003עשו,\u0004 אלא \u0003דמודעי להו ופרשי\u0004 \u0005[שהיו מודיעים להם\u0006 לבית הלל \u0005והיו פורשים]\u0006, שכאשר היו באים הנוהגים כבית הלל לשאת נשים מן הנוהגים כבית שמאי, היו מודיעים להם שילדים מסויימים הם בני צרות, ומכיון שלפי שיטת בית הלל ילדים אלה הם ממזרים ואסור לשאת אותם, לכך פרשו ולא נשאום.","\u0003ו\u0004מעירים: \u0003הכי נמי מסתברא\u0004 \u0005[כך גם כן מסתבר]\u0006 לומר שהיו מודיעים, \u0003דקתני סיפא\u0004 \u0005[ש\u0006כן \u0005שנה\u0006 ב\u0005סופה\u0006 של משנתנו\u0005]:\u0006 \u0003כל הטהרות וכל הטמאות, שהיו אלו מטהרין ואלו מטמאין — לא נמנעו\u0004 מלהיות \u0003עושים טהרות אלו על גבי\u0004 (על ידי, בעזרת) \u0003אלו,\u0004"],["\u0003אי אמרת בשלמא דמודעי להו\u0004 \u0005[נניח אם אומר אתה ש\u0006היו \u0005מודיעים להם] —\u0006 \u0003משום הכי\u0004 \u0005[כך]\u0006 \u0003לא נמנעו, אלא אי אמרת\u0004 \u0005[אם אומר אתה]\u0006 ש\u0003לא מודעי להו\u0004 \u0005[\u0006היו \u0005מודיעים להם],\u0006 \u0003בשלמא\u0004 \u0005[נניח]\u0006 ש\u0003בית שמאי מבית הלל לא נמנעו\u0004 — משום שכל הנחשבות כ\u0003טמאות\u0004 לשיטת \u0003בית הלל — ל\u0004שיטת \u0003בית שמאי טהרות נינהו\u0004 \u0005[הן],\u0006 ומשום כך לא היו צריכים להקפיד בכך.","\u0003אלא בית הלל מבית שמאי למה לא נמנעו?\u0004 הלא \u0003טהרות\u0004 לשיטת \u0003בית שמאי — ל\u0004שיטת \u0003בית הלל טמאות נינהו\u0004 \u0005[הן]!\u0006 \u0003אלא לאו\u0004 \u0005[האם לא]\u0006 מדובר \u0003דמודעי להו\u0004 \u0005[ש\u0006היו בית שמאי \u0005מודיעים להם]\u0006 שדברים אלה הם טהורים רק לדעתם, והיו בית הלל פורשים מהם. ומסכמים: אכן \u0003שמע מינה\u0004 \u0005[למד מכאן]\u0006 שכן הוא.","ושואלים על הוכחה זו: \u0003ומאי אולמיה דהך מהך\u0004 \u0005[ומה תוקפו של זה מזה]?\u0006 כלומר, מדוע ההוכחה מענין טומאות וטהרות טובה יותר מאשר ההוכחה מענין נישואין? שהרי ענין ההודעה לא נאמר בטומאות במפורש, והוצאנו אותו רק מסברה, ובאותה סברה אפשר היה להשתמש גם לענין נישואין! ומשיבים: \u0003מהו דתימא\u0004 \u0005[שתאמר]\u0006 \u0003צרה\u0004 שנישאת \u0003— קלא אית\u0004 \u0005[קול\u0006 פירסום \u0005יש]\u0006 \u0003לה,\u0004 שכיון שדבר זה אינו רגיל, הריהו מתפרסם ברבים, ולכן לכאורה אין צורך להודיע עליו, על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 שבכל זאת היו מודיעים להם.","כיון שהזכרנו את דברי ר' אלעזר דנים לגופם של דברים. \u0003גופא, אמר ר' אלעזר: אף על פי שנחלקו בית שמאי ובית הלל בצרות, מודים שאין ממזר אלא ממי שאיסורו איסור ערוה וענוש כרת.\u0004 ותוהים: \u0003מאן\u0004 \u0005[מי]\u0006 הם ה\u0003מודים? אילימא\u0004 \u0005[אם תאמר]\u0006 ש\u0003בית שמאי\u0004 הם שמודים \u0003לבית הלל\u0004 — \u0003פשיטא\u0004 \u0005[פשוט,\u0006 מובן הדבר מאליו\u0005]!\u0006 שהרי אם עשו כדברי עצמם הרי אלה צרות שנישאו לאחר בלא חליצה — \u0003בני חייבי לאוין\u0004 בלבד הם, ואם כן \u0003כשרים נינהו\u0004 \u0005[הם]\u0006 שהרי בני חייבי לאווים אינם נחשבים כממזרים!","\u0003אלא\u0004 תאמר שמודים \u0003בית הלל לבית שמאי\u0004 — הלא \u0003היא גופא\u0004 \u0005[עצמה],\u0006 צרת ערוה הנישאת לאחד מן האחים, לדעת בית הלל \u0003חייבי כריתות היא,\u0004 והוולד ממזר!","ומשיבים: \u0003לעולם\u0004 תאמר ש\u0003בית שמאי\u0004 הודו \u0003לבית הלל\u0004 בזה, ואין החידוש בדברים לענין מחלוקת זו, אלא \u0003ולאפוקי\u0004 \u0005[ולהוציא,\u0006 למעט\u0005]\u0006 \u0003מ\u0004שיטת \u0003ר' עקיבא,\u0004 ש\u0003אמר: יש ממזר\u0004 גם \u0003מחייבי לאוין,\u0004 ולהוציא מדבריו \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 \u0003דאין ממזר מחייבי לאוין\u0004 שבזה הכל מודים שממזר הוא מחייבי כריתות בלבד.","ושוב מנסים להביא הוכחה לשאלה שעסקנו בה בראשונה, אם עשו בית שמאי כדבריהם, ומציעים: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע],\u0006 ראיה ממה ששנינו: \u0003אף על פי שנחלקו בית שמאי ובית הלל בצרות, ו\u0004נחלקו \u0003באחיות\u0004 — שאם נפלו שתי אחיות כאחת לייבום (שהיו נשואות לשני אחים) לפני שני אחים — לדעת בית הלל אסורות שתיהן להתייבם, ואם עברו ונשאו אותן — יגרשו, ובית שמאי מתירים.","וכן נחלקו \u0003בגט ישן\u0004 — גט שנכתב ולא ניתן, ואחרי זמן כתיבתו חיו יחד הבעל והאשה, שלדעת בית שמאי עדיין אפשר להשתמש בו לשם גירושין לאחר זמן. \u0003ו\u0004כן \u0003בספק אשת איש,\u0004 אם קטנה נשואה (ולא רק ארוסה) יכולה למאן, \u0003ו\u0004כן \u0003במגרש את אשתו ולנה עמו\u0004 לאחר מכן \u0003בפונדק,\u0004 האם חושבים את לינתם יחד בפונדק כהוכחה שנישאו מחדש, או לא,","וכן בשאלה של קדושין \u0003בכסף ובשוה כסף, בפרוטה ובשוה פרוטה,\u0004 שלדעת בית שמאי אין קידושי כסף תופסים אלא בדינר ובשוה דינר, ולדעת בית הלל אף בפרוטה ובשוה פרוטה.","ולמרות שכתוצאה ממחלוקות אלה יש הבדל גדול לגבי מעמדן ההלכתי של נשים שונות, אם נשואות הן או אינן נשואות, ואם בניהן כשרים, \u0003לא נמנעו בית שמאי מלישא נשים מבית הלל, ולא בית הלל מבית שמאי. ללמדך ש\u0004יחסי \u0003חיבה וריעות\u0004 היו \u0003נוהגים זה בזה, לקיים מה שנאמר: \"\u0004ו\u0003האמת והשלום אהבו\"\u0004 (זכריה ח, יט). \u0003ר' שמעון אומר: נמנעו הן מן הודאי, ולא נמנעו מן הספק,\u0004 שלא היו חוששים לאשה מבית שמאי שיש בה אחד מן הספקות הללו.","ולענייננו, \u0003אי אמרת בשלמא\u0004 \u0005[נניח אם אתה אומר]\u0006 ש\u0003עשו\u0004 בית שמאי כדבריהם — \u0003משום הכי\u0004 \u0005[כך]\u0006 \u0003נמנעו. אלא אי אמרת\u0004 \u0005[אם אומר אתה]\u0006 ש\u0003לא עשו, אמאי\u0004 \u0005[מדוע]\u0006 \u0003נמנעו?\u0004 ודוחים: \u0003ותסברא\u0004 \u0005[ו\u0006כי יכול אתה \u0005לסבור\u0006 כך\u0005]\u0006 שמדובר במקרה שעשו כדבריהם? \u0003נהי נמי\u0004 \u0005[אם אמנם גם כן]\u0006 נאמר ש\u0003עשו\u0004 בית שמאי כדבריהם, \u0003בשלמא\u0004 \u0005[נניח]\u0006 \u0003בית הלל נמנעו מבית שמאי\u0004 משום ש\u0003חייבי כריתות נינהו\u0004 \u0005[הם]\u0006 בני הצרות שהתייבמו \u0003וממזרים הם ל\u0004שיטת \u0003בית הלל.\u0004","\u0003אלא בית שמאי אמאי\u0004 \u0005[מדוע]\u0006 \u0003נמנעו\u0004 מלשאת בני צרות שנישאו לשוק כדעת \u0003בית הלל?\u0004 הלא \u0003בני חייבי לאוין נינהו\u0004 \u0005[הם]\u0006 \u0003וכשרים נינהו\u0004 \u0005[הם]!\u0006 ומשיבים: \u0003כ\u0004פי ש\u0003אמר רב נחמן בר יצחק,\u0004 בענין אחר: \u0003לא נצרכה\u0004 הלכה זו, \u0003אלא לצרה עצמה\u0004 ולא לבניה, \u0003הכא נמי\u0004 \u0005[כאן גם כן]\u0006 \u0003לא נצרכה אלא לצרה עצמה,\u0004 שלא שנו את ההלכה שנמנעו ביחס לבני הצרות, אלא ביחס לצרות עצמן איך היו נוהגים.","ושואלים עוד: \u0003ומאי שנא\u0004 \u0005[ומה שונה]\u0006 שהיו פורשים \u0003מן הודאי\u0004 כגון איסור צרות שהן ודאי אסורות לבית הלל — \u0003דאיסורא\u0004 \u0005[שאיסור]\u0006 \u0003הוא\u0004 לדעתם, הלא גם באותם דינים שנחלקו בהם שהם בגלל \u0003ספק,\u0004 כגון: המגרש אשתו ולנה עמו בפונדק, \u0003נמי איסורא\u0004 \u0005[גם כן איסור]\u0006 \u0003הוא\u0004 שגם אם טעמם של בית הלל הוא מפני הספק, מכל מקום לדעתם יש בכך משום איסור!","ומשיבים: \u0003לא תימא\u0004 \u0005[אל תאמר,\u0006 אל תפרש\u0005]\u0006 שלא היו נמנעים \u0003מן ה\u0004נשים שיש לגביהן \u0003ספק\u0004 איסור (כגון נתגרש ולנה עמו בפונדקי שזהו רק ספק אם בא עליה), במובן שמקור ההלכה הוא מטעם של ספק, \u0003אלא אימא\u0004 \u0005[אמור]\u0006 ופרש במובן של \u0003מן הסתם.\u0004 כלומר, שלא היו נמנעים מאשה סתם של בית הלל, שבמקרה שלא ידעו בבירור שהיה ספק קידושין בבני משפחה זו היו נושאים מהם נשים, אבל לא בספק גמור, ומדוע — \u0003דמודעי להו\u0004 \u0005[ש\u0006היו \u0005מודיעים להם]\u0006 שדבר זה אסור לשיטתם \u0003ופרשי\u0004 \u0005[ו\u0006היו \u0005פורשים],\u0006 ואם לא הודיעו להם — סימן שאין כאן ספק.","ושואלים: אם כן, \u0003ומאי קא משמע לן\u0004 \u0005[ומה השמיע לנו]\u0006 בזה — ש\u0003אהבה וריעות\u0004 היו \u0003נוהגים\u0004 בית שמאי ובית הלל \u0003זה בזה\u0004 ולכן סמכו על בני מחלוקתם שלא יבואו להכשילם בדבר שבעיניהם הוא אסור — הלא \u0003היינו רישא\u0004 \u0005[הרי זה\u0006 מה שכבר נאמר ב\u0005התחלה]\u0006 ומה חידש אם כן ר' שמעון? ומשיבים: \u0003הא קא משמע לן\u0004 \u0005[זה השמיע לנו]\u0006 שברייתא זו \u0003כולה\u0004 כדעת \u0003ר' שמעון היא\u0004 ואין כאן מחלוקת בין שני חכמים, אלא ביאור לדברים שנאמרו קודם.","ומציעים הצעה אחרת לפתור את השאלה: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ממה ש\u0003אמר ר' יוחנן בן נורי: היאך הלכה זו\u0004 בענין צרות \u0003רווחת בישראל,\u0004 כיצד ננהג בה? אם \u0003נעשה כדברי בית שמאי\u0004 ונתיר הצרות לייבום — הלא \u0003הולד ממזר לדברי בית הלל,\u0004 ואם \u0003נעשה כדברי בית הלל\u0004 ונפטור את הצרות לגמרי — הרי \u0003הולד\u0004 על כל פנים \u0003פגום לדברי בית שמאי,\u0004 שהוא בן של אשה שיש בה איסור לאו ואף שאיננו ממזר — פגום הוא. אלא \u0003בואו ונתקן להן\u0004 תקנה כללית \u0003לצרות,\u0004"],["\u0003שיהו חולצות ולא מתייבמות\u0004 ויינשאו לאחרים. ועל ידי כך תיפתר השאלה לכל הדעות. \u0003לא הספיקו לגמור את הדבר\u0004 כהצעתו של ר' יוחנן בן נורי \u0003עד שנטרפה השעה,\u0004 שפרצה מלחמה, ולא יכלו להימנות ולקבוע הלכה.","לאחר זמן, כאשר שבו לדון באותו נושא \u0003אמר להם רבן שמעון בן גמליאל: מה נעשה להם לצרות הראשונות מעתה?\u0004 שהרי בינתיים כבר היו צרות שהתייבמו ואם נקבע עתה כתקנה זו שאין מתייבמות, יוכרזו איפוא בניהן של אלה כממזרים — ולכן מוטב שלא נקבענה.","ולענייננו, \u0003אי אמרת בשלמא\u0004 \u0005[נניח אם אומר אתה]\u0006 ש\u0003עשו\u0004 בית שמאי כדבריהם — \u0003היינו דקאמר\u0004 \u0005[זהו שאמר]\u0006 רבן שמעון בן גמליאל \u0003מה נעשה,\u0004 שהרי כבר נעשה מעשה וצרות אלה נישאו ליבמים ואין אנחנו יכולים לתקן את בני הצרות שנתייבמו בעבר. \u0003אלא אי אמרת\u0004 \u0005[אם אומר אתה]\u0006 ש\u0003לא עשו, מאי\u0004 \u0005[מה]\u0006 אם כן פירוש דבריו שאמר \u0003מה נעשה?\u0004 הרי למעשה לא התירו בית שמאי אף פעם לייבם את הצרות!","\u0003אמר רב נחמן בר יצחק: לא נצרכה\u0004 תקנה לבני הצרות, משום שלא עשו בית שמאי כדבריהם, \u0003אלא לצרה עצמה,\u0004 כלומר, כיצד נוכל לתקן להבא את הצרות עצמן שנישאו לאחרים, שלדעת בית שמאי היה פסול בנישואיהן. וכך צריך לפרש: \u0003\"ומה נעשה\" — הכי קאמר\u0004 \u0005[כך אמר],\u0006 כך התכוון לומר: \u0003הנך\u0004 \u0005[אותן]\u0006 \u0003צרות\u0004 שלפי \u0003בית הלל\u0004 פטורות לגמרי, \u0003ל\u0004שיטת \u0003בית שמאי היכי נעביד להו\u0004 \u0005[איך נעשה להן],\u0006 כיון שאותן צרות נהגו כבר כבית הלל ונישאו לאחרים בלא חליצה?","אם תאמר \u0003ליחלצו\u0004 \u0005[שיחלצו] —\u0006 \u0003מימאסי אגברייהו\u0004 \u0005[ימאסו על בעליהן],\u0006 שייראה לבעל שאשתו שהוא חי איתה זה מכבר צריכה עכשיו היתר לנישואין. \u0003וכי תימא לימאסן\u0004 \u0005[ואם תאמר שימאסו]\u0006 ולא איכפת לנו — הלא נאמר על התורה: \u0003\"דרכיה דרכי נעם וכל נתיבתיה שלום\"\u0004 (משלי ג, יז).","ועוד מציעים, \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ראיה ממקור אחר, ש\u0003אמר ר' טרפון\u0004 (שהיה מתלמידי בית שמאי): \u0003תאבני\u0004 (משתוקק אני), \u0003מתי תבא צרת הבת לידי ואשאנה,\u0004 כלומר, אנהג בה כמנהג בית שמאי ואייבם אותה. משמע שהנוהגים כבית שמאי נהגו כשיטתם הלכה למעשה! ומתקנים: \u0003אימא\u0004 \u0005[אמור]\u0006 \u0003ואשיאנה.\u0004 כלומר, אנהג בה כמנהג בית הלל, ואשיאנה לאחרים.","שואלים: \u0003והא\u0004 \u0005[והרי]\u0006 \u0003תאבני\u0004 (משתוקק אני) \u0003קאמר\u0004 \u0005[אמר],\u0006 ואם כלל לא נהגו כדעת בית שמאי, מה חידש איפוא ר' טרפון במה שרצה לעשות מעשה כשיטת בית הלל, הלא הכל נוהגים כך! ומשיבים: \u0003לאפוקי\u0004 \u0005[להוציא]\u0006 \u0003מ\u0004דברי \u0003ר' יוחנן בן נורי,\u0004 שהציע שכל הצרות יחלצו, רצה ר' טרפון שתהיה לו הזדמנות שיוכל להראות שאין הלכה למעשה כדבריו.","ומציעים עוד, \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ממה ששנינו: \u0003מעשה בבתו של רבן גמליאל שהיתה נשואה לאבא אחיו, ומת\u0004 אותו אח \u0003בלא בנים, וייבם רבן גמליאל את צרתה.\u0004 והרי מכאן הוכחה גמורה שמייבמים את צרת הבת הלכה למעשה! ותוהים: \u0003ותסברא\u0004 \u0005[ו\u0006כי \u0005סבור אתה]\u0006 שאפשר לומר כך, ש\u0003רבן גמליאל מתלמידי בית שמאי הוא?\u0004 הלא רבן גמליאל היה מבני בניו של הלל, ובודאי החזיק בשיטת בית הלל בכל תוקפה!","\u0003אלא שאני\u0004 \u0005[שונה]\u0006 \u0003בתו של רבן גמליאל,\u0004 ש\u0003אילונית הואי\u0004 \u0005[היתה],\u0006 וכיון שהיתה אילונית ממילא לא חל איסור על צרתה, כמפורש במשנתנו. ושואלים: \u0003הא מדקתני סיפא\u0004 \u0005[הרי מ\u0006מה \u0005ששנויה\u0006 ב\u0005סופה]\u0006 של אותה ברייתא, \u0003אחרים אומרים: בתו של רבן גמליאל אילונית היתה, מכלל\u0004 הדברים אתה למד כי ה\u0003תנא קמא\u0004 \u0005[הראשון]\u0006 \u0003סבר\u0004 כי \u0003לאו\u0004 \u0005[לא]\u0006 \u0003אילונית היתה!\u0004 ומשיבים: המחלוקת ביניהם לא היתה לגבי עצם העובדה, שודאי היתה אילונית.","אלא השאלה היתה האם הוא \u0003הכיר בה\u0004 בשעת נישואין שהיא אילונית ונשא אותה על דעת כן, והיו שאמרו (לפני כן) שאם הכיר בה צרתה אסורה, או ש\u0003לא הכיר בה\u0004 בשעת הנישואין שהיא אילונית וצרתה מותרת, ובנושא זה \u0003איכא בינייהו\u0004 \u0005[יש ביניהם]\u0006 מחלוקת, שלשיטת התנא הראשון רק אם לא הכיר בה מלכתחילה — הרי זה מקח טעות, אבל אם הכיר בה ומכל מקום נשאה — צרתה אסורה, ואילו לשיטת אחרים, גם אם הכיר בה צרתה מותרת.","\u0003ואיבעית אימא\u0004 \u0005[ואם תרצה אמור]\u0006 ההבדל בין אחרים לתנא הראשון, בענין \u0003כנס\u0004 (נשא) את השניה \u0003ולבסוף גירש\u0004 את בת אחיו ורק לאחר מכן מת \u0003איכא בינייהו\u0004 \u0005[יש ביניהם]\u0006 מחלוקת, שהרי כבר דנו בשאלה האם אשה נחשבת כצרת ערוה מעצם הנישואין לאותו אדם ואף שגירש את הראשונה שהיא ערוה לאחיו, אין בכך כדי להתיר את צרתה כיון שלזמן מסויים היו הן צרות זו לזו, או שדנים לפי הזמן שבו חלה חובת הייבום (עם מותו של האח), ומכיון שבשעת מותו כבר לא היתה ערות אחיו נשואה לו, הרי שצרתה מותרת. ובכך נחלקו, שלדעת התנא הראשון כיון שגרש את בת אחיו ובשעת מותו לא היו הן צרות — הריהי מותרת, ולדעת אחרים, מאחר והיו הן צרות לזמן מסויים, אף שגירש את בת אחיו טרם מותו, הרי הצרה אסורה ולכך אמרו שטעם ההיתר של רבן גמליאל היה בכך שהיתה בתו אילונית.","\u0003איבעית אימא\u0004 \u0005[אם תרצה אמור]\u0006 שבשאלה אם \u0003יש תנאי בביאה איכא בינייהו\u0004 \u0005[יש ביניהם]\u0006 מחלוקת, שיש אומרים שהיתה בענין זה סיבה אחרת לביטול הנישואין, שלדעת התנא הראשון נשואה היתה בתו של רבן גמליאל בתנאי מסויים, והתנאי לא נתקיים וממילא נתבטלו הנישואין וצרתה אם כן מותרת לכתחילה. אבל לדעת אחרים, גם אם היה תנאי קודם בנישואין, ולא נתקיים התנאי, בכל זאת כיון שבא אותו איש על אשתו הרי עם הביאה כאילו ביטל את התנאי. ולכן לדעת אחרים יכול היה רבן גמליאל לייבם את צרת הבת, לא משום התנאי, אלא משום שהיתה בתו אילונית. ולענייננו אין איפוא מכאן כל הוכחה.","\u0003מתיב\u0004 \u0005[מקשה]\u0006 \u0003רב משרשיא\u0004 על האומרים שלא עשו בית שמאי כדבריהם, ממה ששנינו במשנה: \u0003מעשה בר' עקיבא שליקט\u0004 (קטף) \u0003אתרוג באחד בשבט\u0004 בשנה השניה משנות השמיטה הנכנסת לשלישית, \u0003ונהג בו שני עשורין.\u0004 כלומר, הפריש ממנו שני מעשרות, כאילו היה שייך לשתי שנות מעשר (מעשר שני ומעשר עני, שכל אחד מהם מפרישים בשנה אחרת).","מעשר \u0003אחד\u0004 נהג \u0003כדברי בית שמאי\u0004 שלדעתם ראש השנה לאילנות הוא באחד בשבט, ואם כן לשיטה זו צריך האתרוג להתעשר מעשר עני כדין השנה החדשה, \u0003ואחד כדברי בית הלל\u0004 שלדעתם ראש השנה לאילנות הוא בחמישה עשר בשבט והריהו צריך להתעשר מעשר שני כדין השנה הקודמת. על כל פנים \u0003שמע מינה\u0004 \u0005[למד מכאן]\u0006 ש\u0003עשו\u0004 בית שמאי כדבריהם, שהרי ר' עקיבא שחשש לשיטת בית שמאי נהג הלכה למעשה כשיטה זו!","ומשיבים: \u0003ר' עקיבא גמריה אסתפק ליה\u0004 \u0005[לימודו,\u0006 מסורתו, היתה \u0005מסופקת לו]\u0006 \u0003ו\u0004אף שרצונו היה לנהוג כשיטת בית הלל ולא כבית שמאי, \u0003לא ידע אי\u0004 \u0005[אם]\u0006 \u0003בית הלל באחד בשבט אמור\u0004 \u0005[אמרו]\u0006 שהוא ראש השנה, \u0003או בחמשה עשר בשבט אמרו\u0004 \u0005[אמרו]\u0006 שהוא ראש השנה, שלא זכר במדוייק מהי שיטת בית הלל בזה.","ועוד: \u0003מתיב\u0004 \u0005[מקשה]\u0006 \u0003מר זוטרא\u0004 לענין זה ממקור אחר: \u0003מעשה וילדה כלתו של שמאי הזקן\u0004 בן, ולדעת שמאי אפילו תינוק שנולד חייב מיד בסוכה, \u0003ופיחת\u0004 (הסיר) שמאי \u0003את המעזיבה\u0004 (כיסוי הטיט שעל תקרת הבית) שבו דרה הכלה היולדת, \u0003וסיכך על גבי\u0004 ה\u0003מטה בשביל\u0004 ה\u0003קטן.\u0004 אם כן \u0003שמע מינה\u0004 \u0005[למד מכאן]\u0006 ש\u0003עשו\u0004 בית שמאי כדבריהם! ומשיבים: משם אין הוכחה, כי \u0003התם\u0004 \u0005[שם]\u0006 אין לחשוש לכלום, שכן \u0003הרואה\u0004 שעושה כן ודאי \u0003אומר\u0004 לעצמו כי \u0003לאפושי\u0004 \u0005[להוסיף]\u0006 \u0003אויר קעביד\u0004 \u0005[הוא\u0006 ש\u0005עושה]\u0006 כן, שהסרת המעזיבה היתה לא כדי לנהוג כשיטתו, אלא כדי להוסיף איוורור לבית, ובכגון זה מותר היה לנהוג כשיטתו, שהרי אין בכך משום עשיית אגודות אגודות.","ועוד \u0003מתיב\u0004 \u0005[מקשה]\u0006 \u0003מר זוטרא: מעשה בשוקת יהוא\u0004 (שוקת מים שהיתה נקראת כך) \u0003שהיתה בירושלים, והיתה נקובה\u0004 ומחוברת על ידי הנקב \u0003למקוה, וכל טהרות שהיו בירושלים נעשים על גבה,\u0004 שהיו טובלים כלים בתוך שוקת זו. \u0003ושלחו בית שמאי והרחיבוה\u0004 את הפירצה שבשוקת, משום שלדעת בית שמאי לא די בנקב כדי שייחשב כחיבור למקוה, לבית קיבול המים הסמוך לו, \u0003ש\u0004היו \u0003בית שמאי אומרים: עד שתיפחת ברובה\u0004 שיהיה רוב החלל פתוח בין המקוה לבית השוקת הסמוכה,","\u0003ותנן\u0004 \u0005[ושנינו\u0006 במשנה\u0005]\u0006 כמו כן שלדעת בית הלל, \u0003עירוב מקואות,\u0004 שמקואות נחשבים מעורבים זה עם זה, כל שיש חור גדול \u0003כ\u0004מו \u0003שפופרת הנוד\u0004 (שפופרת ששמים בפי הנוד כדי לשפוך מתוכו ואליו) \u0003בעובייה ובחללה\u0004 של שפופרת זו, והוא השיעור של \u0003כשתי אצבעות חוזרות למקומן,\u0004 כלומר, אם אפשר להכניס באותו חור שתי אצבעות שתוכלנה להסתובב בו מכל צד — זהו השיעור. ואילו לדעת בית שמאי צריך שיהיה חור ברוב הדופן. ואם כן, \u0003שמע מינה\u0004 \u0005[למד מכאן]\u0006 ש\u0003עשו\u0004 בית שמאי כדבריהם! ודוחים: \u0003התם\u0004 \u0005[שם]\u0006"],["\u0003הרואה\u0004 את הרחבת החור, \u0003אומר: לאפושי מיא\u0004 \u0005[להרבות מים]\u0006 \u0003הוא דקא עביד\u0004 \u0005[שעשה]\u0006 ולא שהתכוונו לשנות את ההלכה, אלא סברו שלא נכנסו המים במידה מספיקה לשוקת, והרחיבו לשם כך את השוקת, ואין איפוא להוכיח מדבר זה לענייננו.","ושוב מנסים להביא ראיה אחרת, \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]:\u0006 ש\u0003אמר ר' אלעזר בר צדוק: כשהייתי לומד תורה אצל ר' יוחנן החורני\u0004 שהיה מבית שמאי, \u0003ראיתי שהיה אוכל פת חריבה\u0004 (יבשה) \u0003במלח,\u0004 וזה היה \u0003בשני בצורת. באתי והודעתי את אבא\u0004 על אכילתו הדלה, \u0003אמר לי: הולך לו זיתים, והולכתי לו. ראה אותן\u0004 ר' יוחנן, את הזיתים הללו, \u0003שהן לחין,\u0004 משום הנוזל (\"מוהל\") היוצא מן הזית וכיון שהם לחים הרי הוכשרו לקבל טומאה, וחשש שמא בינתיים נטמאו, ולכך \u0003אמר לי: אין אני אוכל זיתים.\u0004 שלא רצה לומר שהוא חושש משום הטומאה, אלא אמר בלשון מנומסת שאין הוא אוכל זיתים בכלל.","\u0003באתי והודעתי את אבא. אמר לי: לך ואמור לו: חבית\u0004 שבה היו הזיתים \u0003נקובה היתה אלא שסתמוה שמרים\u0004 שבשמן וכתוצאה מכך נשארה רטיבות מסויימת בפנים, אולם מתוך שנקבו את החבית אין הזיתים שבתוכה נעשים מוכשרים לטומאה, שאין הכשר לטומאה אלא מרצון, ובכך שנקב את החבית בכוונה להוציא את המשקה, גילה את דעתו שאינו מעוניין בהכשרתם. \u0003ותנן\u0004 \u0005[ו\u0006כן \u0005שנינו\u0006 במשנה\u0005]:\u0006 \u0003חבית של זיתים מגולגלים\u0004 (כבושים), \u0003בית שמאי אומרים: אין צריכה לנקב\u0004 (להינקב), שלדעתם המשקה היוצא מן הזיתים הללו איננו מן המשקים המכשירים לקבל טומאה ואף שהזיתים נרטבים בו, אין בכך כדי להכשירם.","\u0003ובית הלל אומרים: צריכה לנקב,\u0004 משום שלדעתם המשקה היוצא מן הזיתים נחשב כשמן, והוא מכשיר לקבל טומאה, וכיון שאין משקה מכשיר לקבל טומאה אלא אם כן היה שם מרצון, הרי מאחר שעשה נקב בחבית גילה דעתו שאיננו מעונין במשקה זה, ולכן אין הזיתים נעשים מוכשרים לקבל טומאה על ידי מגעם במיץ הזה. \u0003ומודים\u0004 בית הלל \u0003שאם ניקבה\u0004 החבית ברצון בעליה \u0003וסתמוה שמרים — שהיא טהורה,\u0004 שלא הוכשרו הזיתים שבתוכה לקבל טומאה למרות שהם לחים. שהרי בנקיבת החבית גילה כבר דעתו שאיננו רוצה במשקה היוצא מן הזיתים.","ומעירים: \u0003ואף על פי ש\u0004ר' יוחנן החורני \u0003תלמיד שמאי היה\u0004 — \u0003כל מעשיו לא עשה אלא כדברי בית הלל.\u0004 ולענייננו \u0003אי אמרת בשלמא עשו\u0004 \u0005[נניח אם אתה אומר ש\u0006עשו\u0005]\u0006 בית שמאי כדבריהם — \u0003היינו רבותיה\u0004 \u0005[זו גדולתו],\u0006 שבכל זאת נהג כבית הלל. \u0003אלא אי אמרת\u0004 \u0005[אם אומר אתה]\u0006 \u0003לא עשו — מאי רבותיה\u0004 \u0005[מה גדולתו]\u0006 וייחודו, הלא נהג כמנהג העולם?! ומכאן שכרגיל עשו בית שמאי כדבריהם.","ומוסיפים: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ראיה ממה ששנינו ש\u0003שאלו את ר' יהושע: צרת הבת מהו? אמר להם: מחלוקת בית שמאי ובית הלל\u0004 היא. הוסיפו ושאלו אותו: \u0003והלכה כדברי מי? אמר להם: מפני מה אתם מכניסין ראשי בין שני הרים גדולים,\u0004 כלומר, \u0003בין שתי מחלוקות גדולות, בין בית שמאי ובין בית הלל, מתיירא אני שמא ירוצו\u0004 (ירוצצו, ישברו) \u0003גלגלתי\u0004 בהתנגשות בין שני \"הרים\" אלה.","\u0003אבל אני מעיד לכם על שתי משפחות גדולות שהיו בירושלים, משפחת בית צבועים\u0004 שבאו \u0003מבן עכמאי, ומשפחת בית קופאי מבן מקושש, שהם בני צרות\u0004 שנישאו לאחרים כבית הלל, \u0003ומהם כהנים גדולים, ושמשו על גבי המזבח.\u0004 ובזה יכול אני להעיד שכך נהגו הלכה למעשה במשך הדורות.","ומעתה, \u0003אי אמרת בשלמא\u0004 \u0005[נניח אם אתה אומר]\u0006 ש\u0003עשו\u0004 בית שמאי כדבריהם — \u0003היינו דקאמר\u0004 \u0005[הוא שאמר]\u0006 \u0003מתיירא אני,\u0004 שהרי אם יפסוק הלכה, הרי הוא קובע בזה שילדים מסויימים הם ממזרים, ושמא יבואו בני המשפחות הללו להינקם בו. \u0003אלא אי אמרת\u0004 \u0005[אם אומר אתה]\u0006 ש\u0003לא עשו, אמאי קאמר\u0004 \u0005[מדוע אמר]\u0006 \u0003מתיירא אני?\u0004 ושואלים: \u0003ונהי נמי\u0004 \u0005[ואם גם כן]\u0006 נאמר ש\u0003עשו, מאי\u0004 \u0005[מה]\u0006 טעם לאמור \u0003מתיירא אני\u0004 יש כאן?","\u0003הא\u0004 \u0005[הרי]\u0006 \u0003אמר ר' יהושע\u0004 לשיטתו: \u0003אין ממזר אלא מחייבי מיתות בית דין,\u0004 ולא מחייבי כריתות, ואם כן בני הצרות שהתייבמו שהם מחייבי כריתות לא ייתכן שיהיו ממזרים לדעת ר' יהושע, ולשיטתו לא אמר דבר רע כל כך! ומשיבים: אף על פי כן היה לו מקום להתיירא, \u0003נהי נמי\u0004 \u0005[\u0006אם \u0005אמנם גם כן]\u0006 שבן הצרה \u0003ממזר לא הוי\u0004 \u0005[אינו],\u0006 מכל מקום \u0003פגום מיהו הוי\u0004 \u0005[\u0006הרי \u0005הוא על כל פנים]\u0006 לענין כהונה.","ודבר זה למדים \u0003מקל וחומר מאלמנה: מה אלמנה,\u0004 לכהן גדול \u0003שאין איסורה נוהג בכל,\u0004 שהרי איסור זה של אלמנה הוא רק לכהן הגדול, ולא לכל אדם אחר, ובכל זאת \u0003בנה פגום\u0004 לכהונה, \u0003זו,\u0004 הצרה \u0003שאיסורה שוה בכל,\u0004 וחל גם על ישראלים, כל שכן שבנה פגום לכהונה.","אגב אותו ענין מעירים: הרי \u0003קבעו מיניה\u0004 \u0005[שאלו אותו]\u0006 בענין \u0003צרות, וקפשיט ליה\u0004 \u0005[וענה לו]\u0006 בענין של \u0003בני צרות,\u0004 ועל הצרות עצמן לא ענה כלל! ומסבירים: \u0003תרתי קא בעו מיניה\u0004 \u0005[שני\u0006 דברים \u0005שאלו ממנו]:\u0006 \u0003צרות מאי\u0004 \u0005[מה]\u0006 דינן? \u0003ואם תמצי לומר\u0004 \u0005[ואם תמצא לומר]\u0006 ותסכם שלענין \u0003צרות\u0004 הלכה \u0003כבית הלל\u0004 שהן פטורות, \u0003בני צרות\u0004 של \u0003בית הלל,\u0004 כלומר, שיצאו בלא חליצה ונישאו לאחים — \u0003ל\u0004דעת \u0003בית שמאי מהו,\u0004 מה דינן?","ושואלים: אם כך, \u0003למאי נפקא מינה\u0004 \u0005[למה,\u0006 לאיזה חידוש דין \u0005יוצא ממנה],\u0006 שכיון שהוא פוסק הלכה כבית הלל, מדוע צריך היה לעסוק בשאלה מה דעת בית שמאי על מנהג בית הלל? ומסבירים: על ידי תשובתו אפשר \u0003למיפשט\u0004 \u0005[לפתור]\u0006 בעיה אחרת: מה דינו של \u0003ולד מחזיר גרושתו לבית הלל,\u0004 כלומר, מי שהחזיר את גרושתו אחרי שנישאה לאחר, האם הילד שנולד מנישואין אלה כשר או פסול לכהונה?","\u0003מי קאמרינן\u0004 \u0005[האם אנו אומרים]\u0006 כך: \u0003קל וחומר, ומה אלמנה לכהן גדול שאין איסורה שוה בכל,\u0004 שהרי היא אסורה לכהן גדול בלבד — \u0003בנה פגום\u0004 לכהונה. \u0003זו,\u0004 הגרושה שנישאה לאחר \u0003שאיסורה\u0004 לחזור ולהינשא לראשון \u0003שוה בכל,\u0004 שהרי האיסור הזה חל על כל אדם — \u0003אינו דין שבנה\u0004 מנישואין אלו \u0003פגום?\u0004","\u0003או דלמא איכא למיפרך\u0004 \u0005[או שמא יש לשבור]\u0006 את ההשוואה הזו, ולומר: \u0003מה לאלמנה שהיא עצמה מתחללת,\u0004 שאם הכהן הגדול בא על אלמנה, היא נעשית \"חללה\", והיא עצמה נפסלת ואסורה גם לכהן הדיוט, מה שאין כן בגרושה שהוחזרה, שאיננה חללה. \u0003ואמר להו\u0004 \u0005[להם]:\u0006 לגבי \u0003צרות מתיירא אני\u0004 לפסוק הלכה, משום שהדבר יביא לסכסוכים,"],["\u0003בני צרות אני מעיד לכם\u0004 שאינם פגומים, שהרי כפי שאמר — מבני בניהם היו כהנים גדולים.","\u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ראיה אחרת שעשו בית שמאי כדבריהם ממה ששנינו: \u0003בימי ר' דוסא בן הרכינס הותרה צרת הבת לאחין.\u0004 שהתירה אחיו של ר' דוסא, שהיה מתלמידי בית שמאי. \u0003שמע מינה\u0004 \u0005[למד מכאן]\u0006 כי \u0003עשו\u0004 בית שמאי כדבריהם. ומסכמים על סמך הוכחות אלה: אכן, \u0003שמע מינה\u0004 \u0005[למד מכאן].\u0006","קטע אחרון זה היה חלק ממעשה ארוך יותר, ומעתה מביאים את כל הענין לגופו. \u0003גופא, בימי ר' דוסא בן הרכינס התירו צרת הבת לאחין.\u0004 כלומר, נודע שר' דוסא התיר את צרת הבת לאחים \u0003והיה הדבר קשה לחכמים, מפני שחכם גדול היה\u0004 והכרעתו כבית שמאי היתה הכרעה בעלת משקל רב. ולא יכלו לשאול אותו מיד כיון שהיה זקן מאוד \u0003ועיניו קמו\u0004 (כהו) עד כדי כך שנמנע \u0003מלבא לבית המדרש.\u0004","\u0003אמרו: מי ילך ויודיעו\u0004 ויברר את הענין עמו? \u0003אמר להן ר' יהושע: אני אלך.\u0004 ושאלו: \u0003ואחריו מי\u0004 ילך? — \u0003ר' אלעזר בן עזריה\u0004 שהיה אמנם צעיר, אבל מגדולי חכמי הדור. ושוב שאלו: \u0003ואחריו מי?\u0004 — \u0003ר' עקיבא. הלכו\u0004 שלושת החכמים \u0003ועמדו על פתח ביתו. נכנסה שפחתו, אמרה לו: רבי, חכמי ישראל באין אצלך, אמר לה: יכנסו, ונכנסו.\u0004","\u0003תפסו\u0004 ר' דוסא \u0003לר' יהושע,\u0004 שאותו הכיר מכבר, \u0003והושיבהו על מטה של זהב,\u0004 לפי שר' דוסא היה עשיר מופלג. \u0003אמר לו\u0004 ר' יהושע: \u0003רבי, אמור לתלמידך אחר וישב.\u0004 כלומר, לתלמיד חכם אחר שנמצא כאן. שבלשון כבוד נוהגים שכאשר פונים לחכם גדול קוראים לכל אדם אחר תלמידו. \u0003אמר לו: מי הוא?\u0004 אמר לו ר' יהושע: \u0003ר' אלעזר בן עזריה. אמר\u0004 ר' דוסא: \u0003ויש לו בן לעזריה חבירנו?\u0004 שמחמת זקנתו המופלגת לא היה זמן מרובה בבית המדרש, ולא שמע עליו.","\u0003קרא עליו המקרא הזה: \"נער הייתי גם זקנתי ולא ראיתי צדיק נעזב וזרעו מבקש לחם\"\u0004 (תהלים לז, כה), כלומר, שבנו של תלמיד חכם זוכה גם הוא עצמו להיות תלמיד חכם. \u0003תפסו והושיבו על מטה של זהב. אמר לו\u0004 ר' יהושע: \u0003רבי, אמור לתלמידך אחר וישב. אמר לו: ומי הוא?\u0004 אמר לו: \u0003עקיבא בן יוסף. אמר לו\u0004 ר' דוסא: \u0003אתה הוא עקיבא בן יוסף ששמך הולך מסוף העולם עד סופו?!\u0004 שאת שמעו של ר' עקיבא כאדם גדול שמע גם ר' דוסא. \u0003שב בני, שב, כמותך ירבו בישראל.\u0004","מפני הנימוס לא רצו לגשת מיד לנושא ו\u0003התחילו מסבבים אותו בהלכות,\u0004 ועסקו בהלכות שונות \u0003עד שהגיעו לצרת הבת. אמרו ליה\u0004 \u0005[לו]:\u0006 \u0003צרת הבת מהו\u0004 דינה, האם מותרת להתייבם? \u0003אמר להן: מחלוקת בית שמאי ובית הלל\u0004 היא. שאלו אותו: \u0003הלכה כדברי מי? אמר להן: הלכה כ\u0004דברי \u0003בית הלל. אמרו ליה\u0004 \u0005[לו]:\u0006 \u0003והלא משמך אמרו\u0004 ש\u0003הלכה כ\u0004דברי \u0003בית שמאי!\u0004","\u0003אמר להם:\u0004 האם שמעתם ש\u0003דוסא\u0004 בן הרכינס התיר, \u0003או\u0004 ש\u0003בן הרכינס\u0004 התיר, \u0003שמעתם? אמרו ליה\u0004 \u0005[לו]:\u0006 \u0003חיי רבי, סתם שמענו.\u0004 כלומר, בן הרכינס. \u0003אמר להם:\u0004 אם כך אין זה תמוה, כי \u0003אח קטן יש לי, בכור שטן הוא\u0004 כלומר, חריף מאוד ואמיץ בדעתו כשד, \u0003ויונתן שמו, והוא מתלמידי שמאי,\u0004 והוא זה שהתיר.","ונוסף לכך אמר: \u0003והזהרו שלא יקפח\u0004 (יכה) \u0003אתכם בהלכות\u0004 בענין זה. \u0003לפי שיש עמו שלש מאות תשובות\u0004 (הוכחות) \u0003בצרת הבת שהיא מותרת. אבל\u0004 אין אתם צריכים לחשוש לעצם הענין, כי \u0003מעיד אני עלי שמים וארץ, שעל מדוכה זו,\u0004 שהיתה בתוך ביתו מדוכה, שנשמרה בגלל הזכרון שהיה כרוך בה, ואשר עליה \u0003ישב חגי הנביא, ו\u0004מקובל אני כי \u0003אמר שלשה דברים\u0004 בהלכה: אחד — ש\u0003צרת הבת אסורה,\u0004","שני — ש\u0003עמון ומואב,\u0004 כלומר שטחי עבר הירדן שהיו פעם שייכים לעמון ומואב, שיש להם דין מעין ארץ ישראל ולא כמוה לגמרי, שהם, \u0003מעשרין מעשר עני ב\u0004שנת ה\u0003שביעית.\u0004 שאין השמיטה נוהגת בהם כיון שאינם מארץ ישראל, אבל מביאים מהם מעשר עני לעניי ארץ ישראל, שכן שנת השמיטה בארץ ישראל היא שנה ללא מעשרות בכלל ואף אין בשנה זו לקט שכחה ופאה ואין איפוא לעניים שבה מה לאכול בשנה זו. ועוד העיד: \u0003ומקבלים גרים מן הקרדויין ומן התרמודים\u0004 ואין אנחנו חוששים לתערובת של ישראלים שהיו שם שנטמעו ביניהם, ואין חוששים שמא ממזרים הם ואסורים לבא בקהל.","\u0003תנא\u0004 \u0005[שנה]\u0006 החכם: \u0003כשנכנסו\u0004 ר' יהושע, ר' אלעזר בן עזריה ור' עקיבא — \u0003נכנסו\u0004 כולם \u0003בפתח אחד,\u0004 אולם \u0003כשיצאו, יצאו בשלשה פתחים\u0004 כדי לנסות לפגוש את אחיו של ר' דוסא. \u0003פגע\u0004 (פגש) \u0003בו בר' עקיבא. אקשי ליה\u0004 \u0005[הקשה לו]\u0006 יונתן בן הרכינס כל אותן קושיות שיש לו על שיטת בית הלל, \u0003ואוקמיה\u0004 \u0005[והעמיד אותו],\u0006 כלומר, השיב עליהם.","הקפיד יונתן בן הרכינס, \u0003אמר לו: אתה הוא עקיבא ששמך הולך מסוף העולם ועד סופו? אשריך שזכית לשם\u0004 גדול, למרות ש\u0003עדיין לא הגעת\u0004 אפילו \u0003ל\u0004מדרגה של \u0003רועי בקר.\u0004 שרועי בקר הם אנשים פשוטים מאוד, ובדרך כלל הם עמי הארץ ואינם בקיאים אף בהליכות העולם, ובודאי לא בהלכה. \u0003אמר לו ר' עקיבא\u0004 בצניעות: \u0003ואפילו ל\u0004מדרגה של \u0003רועי צאן,\u0004 שהם גרועים מרועי בקר — לפי שהם נחשבים כפסולים לעדות — עדיין לא הגעתי.","כיון שהזכירו הלכות אלה בשם חגי הנביא, דנים אף בהן כאן, הוא אמר ש\u0003עמון ומואב מעשרין מעשר עני בשביעית.\u0004 ש\u0003אמר מר\u0004 \u0005[החכם]:\u0006 \u0003הרבה כרכים כבשו עולי מצרים ולא כבשו עולי בבל\u0004 כשעלו בפעם השניה מבבל, \u0003וקדושה ראשונה\u0004 של ארץ ישראל שנתקדשה על ידי עולי מצרים \u0003קדשה\u0004 רק \u0003לשעתה ולא קדשה לעתיד לבא,\u0004 והיא תלויה בכיבושה של הארץ מחדש על ידי ישראל.","\u0003והניחום\u0004 עולי בבל את כל המקומות הללו ולא החשיבו אותם כארץ ישראל גם אחרי שהתיישבו יהודים במקומות הללו, וחורשים וזורעים וקוצרים בהם בשנת השמיטה כחוץ לארץ, ומכל מקום מעשרים מעשר עני כבארץ ישראל \u0003כדי שיסמכו עליהן עניים בשביעית,\u0004 שהעניים שבארץ ישראל שאין להם בשנה זו לקט שכחה ופאה ומעשר עני מפירות ארץ ישראל, ייעזרו במעשר זה.","עוד אמר: \u0003ומקבלים גרים מן הקרדויים והתרמודים.\u0004 ושואלים: \u0003איני\u0004 \u0005[האם כן הוא]\u0006 \u0003והא תני\u0004 \u0005[והרי שנה]\u0006 \u0003רמי בר יחזקאל\u0004 ברייתא: \u0003אין מקבלים גרים מן הקרדויים! אמר רב אשי: קרתויים אתמר\u0004 \u0005[נאמר],\u0006 כלומר, רמי בר יחזקאל אמר שאין מקבלים גרים מן הקרתויים. \u0003כדאמרי אינשי\u0004 \u0005[כפי שאומרים אנשים]\u0006 בכלל בפתגם: \u0003קרתויים פסולים.\u0004","\u0003ואיכא דאמרי\u0004 \u0005[ויש שאומרים]\u0006 זאת בסגנון קצת שונה: \u0003תני\u0004 \u0005[שנה]\u0006 \u0003רמי בר יחזקאל: אין מקבלים גרים מן הקרתויים. מאי לאו\u0004 \u0005[האם לא]\u0006 \u0003היינו\u0004 \u0005[הם־הם]\u0006 ה\u0003קרתויים היינו\u0004 \u0005[\u0006ו\u0005הם־הם]\u0006 ה\u0003קרדויים\u0004 ואם כן יש סתירה בין ברייתא זו לדברי ר' דוסא בן הרכינס! \u0003אמר רב אשי: לא, קרתויי\u0004 \u0005[קרתויים]\u0006 \u0003לחוד וקרדויי\u0004 \u0005[וקרדויים]\u0006 \u0003לחוד\u0004 ו\u0003כדאמרי אינשי\u0004 \u0005[\u0006ו\u0005כפי שאומרים אנשים]:\u0006 \u0003קרתויי פסילי\u0004 \u0005[קרתויים פסולים].\u0006","ואילו \u0003ר' יוחנן וסביא\u0004 \u0005[והזקנים]\u0006 עמו \u0003דאמרי תרוייהו\u0004 \u0005[שאמרו שניהם],\u0006 כלומר, הסכימו כולם: \u0003אין מקבלים גרים מן התרמודים.\u0004 ושואלים: \u0003ומי\u0004 \u0005[והאם]\u0006 \u0003אמר ר' יוחנן הכי\u0004 \u0005[כך]\u0006 שאין מקבלים מהם גרים. משום שיש שם חשש של תערובת יהודים וממילא של ממזרות? \u0003והתנן\u0004 \u0005[והרי שנינו\u0006 במשנה\u0005]:\u0006 \u0003כל הכתמים\u0004 כלומר בגדים מוכתמים בדם, שיש לחשוש שהוא דם נידה, \u0003הבאים מן הרקם\u0004 מעיר זו שבגבול ארץ ישראל — \u0003טהורים,\u0004 משום שהם בודאי שייכים לגויים, ודם נידה של גויים אינו מטמא.","\u0003ור' יהודה מטמא, מפני שהם\u0004 באותו מקום \u0003גרים וטועים.\u0004 כלומר, חלק מהם, לאחר שנתגיירו, חזרו והתבוללו בין הגויים, ואף שאינם שומרים עוד את דיני התורה, נחשבים הם כישראלים גמורים, וצריך לחשוש לכתמים שלהם שהם של דם נידה. אבל כתמים הבאים \u0003מבין הגוים טהורים. והוינן\u0004 \u0005[והיינו עוסקים]\u0006 \u0003בה,\u0004 בבעיה זו:"],["\u0003קפסיק ותני\u0004 \u0005[פסק ושנה]:\u0006 \u0003מבין הגוים\u0004 הכתמים טהורים, \u0003ואפילו מן תרמוד.\u0004 שהרי נקבעה הלכה כללית, שכל מקום שיש בו גויים — אין חוששים לכתמים. \u0003ואמר ר' יוחנן: זאת אומרת מקבלים גרים מתרמוד,\u0004 ואין חוששים שמא הם ממזרים מזרע ישראל.","\u0003וכי תימא\u0004 \u0005[ואם תאמר]\u0006 שכוונתו היתה \u0003\"זאת\u0004 אומרת \u0003\"\u0004— \u0003ולא סבירא ליה\u0004 \u0005[ו\u0006הוא עצמו \u0005אינו סבור\u0006 כן\u0005]\u0006 אלא רק אמר מה המסקנה היוצאת ממשנה זו — \u0003והא\u0004 \u0005[והרי]\u0006 \u0003אמר ר' יוחנן\u0004 עצמו כלל גדול: \u0003הלכה כסתם משנה,\u0004 וזו, סתם משנה היא! ומשיבים: מחלוקת \u0003אמוראי נינהו\u0004 \u0005[אמוראים]\u0006 היא \u0003ואליבא\u0004 \u0005[ובשיטת]\u0006 \u0003ר' יוחנן,\u0004 שיש שאמרו בשמו שהתרמודיים פסולים, ויש שאמרו בשמו שהם כשרים.","ושואלים: \u0003מתרמוד מאי טעמא\u0004 \u0005[מה טעם]\u0006 \u0003לא\u0004 יקבלו גרים? — \u0003פליגי בה\u0004 \u0005[נחלקו בכך]\u0006 \u0003ר' יוחנן וסביא\u0004 \u0005[והזקנים],\u0006 שאף שהסכימו שאין מקבלים גרים משם, נחלקו בטעם הדבר; \u0003חד\u0004 \u0005[אחד\u0006 מהם\u0005]\u0006 \u0003אמר: משום עבדי שלמה.\u0004 ששלמה בנה עיר בתרמוד (מלכים א' ט, יח) ועבדיו הגוים של שלמה, בשל כבודם ותוקפם, נשאו שלא כדין נשים יהודיות, ויש לחשוש שבני תרמוד הם וצאצאיהם ממזרים. \u0003וחד\u0004 \u0005[ואחד\u0006 מהם\u0005]\u0006 \u0003אמר: משום בנות ירושלים\u0004 שנלקחו בשבי הגוים ונאנסו על ידיהם וילדו להם ילדים.","ומעירים: \u0003בשלמא למאן דאמר\u0004 \u0005[נניח ל\u0006שיטת \u0005מי שאומר]\u0006 שאין מקבלים מהם גרים \u0003משום עבדי שלמה\u0004 אפשר להסביר זאת כי \u0003קסבר\u0004 \u0005[סבור\u0006 הוא\u0005]\u0006 ש\u0003גוי ועבד הבא על בת ישראל הולד ממזר.\u0004 וכיון שהיו אלה עבדים (עבדי שלמה) שבאו על בנות ישראל — צאצאיהם ממזרים. \u0003אלא למאן דאמר\u0004 \u0005[ל\u0006דעת \u0005מי שאומר]\u0006 \u0003משום בנות ירושלים, מאי\u0004 \u0005[מה]\u0006 \u0003היא\u0004 הסיבה שיש לחשוש לבני תרמוד דווקא ולא לבני מדינות אחרות? — \u0003פליגי בה\u0004 \u0005[נחלקו בכך]\u0006 \u0003רב יוסף ורבנן\u0004 \u0005[וחכמים],\u0006 \u0003ותרוייהו משמיה\u0004 \u0005[ושניהם משמו]\u0006 של \u0003רבה בר בר חנה,\u0004","\u0003חד\u0004 \u0005[אחד\u0006 מהם\u0005]\u0006 \u0003אמר: תריסר אלפי גברי ושיתא אלפי קשתויי\u0004 \u0005[שנים עשר אלף איש וששת אלפים קשתים],\u0006 \u0003וחד\u0004 \u0005[ואחד\u0006 מהם\u0005]\u0006 \u0003אמר: תריסר אלפי גברי ומנייהו שיתא אלפי קשתויי\u0004 \u0005[שנים עשר אלף איש ומהם ששת אלפים קשתים]\u0006 באו מתרמוד, ו\u0003בשעה שנכנסו גוים להיכל\u0004 כשנכבשה ירושלים, \u0003הכל נפנו על כסף וזהב\u0004 שהיה שם לשדוד, \u0003והם נפנו על בנות ירושלים\u0004 לאונסם, \u0003שנאמר: \"נשים בציון ענו בתלת בערי יהודה\"\u0004 (איכה ה, יא) והבנות הללו ילדו מהם ילדים, ולפי השיטה שבני גויים ממזרים הם — הרי כל הילדים שנולדו לתרמודיים, ממזרים הם.","כיון שהזכרנו את הפסוק שאמר ר' דוסא בן הרכינס על ר' אליעזר, מביאים עוד מה ש\u0003אמר\u0004 על פסוק זה \u0003ר' שמואל בר נחמני אמר ר' יונתן: פסוק זה שר העולם אמרו.\u0004 כלומר, המלאך הממונה על העולם — הוא שאמר אותו, והוא הפסוק: \u0003\"נער הייתי גם זקנתי\u0004 ולא ראיתי צדיק נעזב וזרעו מבקש לחם\u0003\"\u0004 (תהלים לז, כה). כי, \u0003מאן אמריה\u0004 \u0005[מי אמר אותו]?\u0006 \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 כי \u0003קודשא בריך הוא\u0004 \u0005[הקדוש ברוך הוא]\u0006 הוא שאמרו — \u0003מי איכא\u0004 \u0005[האם יש]\u0006 \u0003זקנה קמיה\u0004 \u0005[לפניו],\u0006 והייתכן שיאמר \"נער הייתי גם זקנתי\"? \u0003ואלא\u0004 תאמר כי \u0003דוד\u0004 עצמו \u0003אמריה\u0004 \u0005[אמרו]\u0006 מתוך נסיונו שלו — \u0003מי קשיש כולי האי\u0004 \u0005[האם\u0006 היה \u0005זקן כל כך]?\u0006 והלא מת בן שבעים שנה. \u0003אלא שמע מינה\u0004 \u0005[למד ממנה,\u0006 מכאן\u0005]\u0006 ש\u0003שר העולם אמרו,\u0004 שביחס אליו שייכים המושגים נערות וזקנה, והוא הוא שיכול היה לומר שכך וכך ראה.","\u0003ו\u0004עוד \u0003אמר ר' שמואל בר נחמני אמר ר' יונתן, מאי דכתיב\u0004 \u0005[מהו שנאמר]:\u0006 \u0003\"ידו פרש צר על כל מחמדיה\u0004 כי ראתה גוים באו מקדשה אשר צויתה לא יבאו בקהל לך\u0003\"\u0004 (איכה א, י) — \u0003זה עמון ומואב.\u0004 כיצד? \u0003בשעה שנכנסו גוים להיכל, הכל נפנו על כסף וזהב\u0004 שבו לשדוד אותם, \u0003והם נפנו על ספרי תורה\u0004 (של כנסת ישראל) לחבל בהם. \u0003אמרו: זה\u0004 הספר \u0003שכתוב בו \"לא יבא עמוני ומואבי בקהל ה'\"\u0004 (דברים כג, ד) — \u0003ישרף באש!\u0004","ואגב הזכרת העמונים מביאים: על מה שנאמר \u0003\"צוה ה' ליעקב סביביו צריו\"\u0004 (איכה א, יז), \u0003אמר רב: כגון\u0004 המקום \u0003הומניא ל\u0004עיר \u0003פום נהרא\u0004 שיש בהומניא צאצאי העמונים, והם מציקים ליהודים שבפום נהרא.","\u0003אמר רב יהודה אמר רב אסי: גוי שקידש בזמן הזה\u0004 בת ישראל — \u0003חוששין לקדושין,\u0004 אף על פי שקידושי גוי אינם כלום, \u0003שמא מעשרת השבטים\u0004 שנתערבו בין הגויים \u0003הוא,\u0004 וקידושיו קדושין. ומקשים: \u0003והא\u0004 \u0005[והרי]\u0006 יש כלל גדול בהלכה: \u0003כל דפריש\u0004 \u0005[\u0006מי \u0005שפורש] —\u0006 \u0003מרובא פריש\u0004 \u0005[מן הרוב\u0006 הוא \u0005פורש],\u0006 שאנו מניחים כי זה שפרש הוא חלק מן הרוב ולא ממיעוט, ואדם שבא מבין הגוים, מן הסתם שייך לרובם של הגוים, שאין להם כל קשר עם ישראל!","ומשיבים: הלכה זו אכן לא נאמרה אלא \u0003בדוכתא דקביעי\u0004 \u0005[במקום ש\u0006בו \u0005קבועים]\u0006 בני עשרת השבטים, ולגבי אלה הבאים משם יש לחשוש. ש\u0003אמר ר' אבא בר כהנא,\u0004 נאמר על גולי שומרון: \u0003\"וינחם בחלח ובחבור נהר גוזן וערי מדי\"\u0004 (מלכים ב' יח, יא) והוא זיהה את המקומות \u0003חלח — זה\u0004 המקום הקרוי \u0003חלזון, וחבור —\u0004"],["\u0003זו חדייב, נהר גוזן — זו גינזק, וערי מדי — זו\u0004 העיר \u0003חמדן וחברותיה. ואמרי לה\u0004 \u0005[ויש אומרים]:\u0006 \u0003זו ניהר וחברותיה.\u0004 ושואלים: \u0003חברותיה מאן\u0004 \u0005[מי\u0006 הן\u0005]?\u0006 \u0003אמר שמואל: כרך, מושכי, חידקי ודומקיא,\u0004 אלה הם המקומות שהם \"חברותיה\" של חמדן. \u0003אמר ר' יוחנן: וכולן,\u0004 כל המקומות הללו שמנינו, נאמרו \u0003ל\u0004ענין שיש בהם צד \u0003פסול.\u0004 שאם בא אדם ממקומות אלה להתגייר אנו חוששים שמא מזרע ישראל הוא ושמא ממזר הוא, ולכן כולם פסולים.","והוסיף וסיפר רב יהודה: \u0003כי אמריתה קמיה\u0004 \u0005[כאשר אמרתי אותה,\u0006 את ההלכה הזו \u0005לפני]\u0006 \u0003שמואל\u0004 שחוששים לקידושין של גוי בזמן הזה, \u0003אמר לי:\u0004 אין לחשוש לכך, כי \u0003בנך הבא מן ישראלית — קרוי בנך,\u0004 ומתייחס אחריך, \u0003ואין בנך הבא מן הגויה קרוי בנך אלא בנה.\u0004 ולכן כל הילדים שנולדו לבני ישראל מן הגויות אינם נחשבים עוד כיהודים, משום שהם נחשבים אחר אמותיהם הגויות.","ושואלים: \u0003והאיכא\u0004 \u0005[והרי יש]\u0006 \u0003בנות\u0004 מעם ישראל שנשבו, וילדו ילדים מן הגוים, וצאצאיהם נחשבים איפוא כישראלים, \u0003ואמר רבינא: שמע מינה\u0004 \u0005[למד מכאן],\u0006 ממדרש ההלכה, מי הוא הקרוי ומתייחס כבן, ש\u0003בן בתך הבא מן הגוי — קרוי בנך!\u0004 ומשיבים: אין מקום לחשש זה, כי \u0003גמירי דבנתא דההוא דרא איצטרויי אצטרו\u0004 \u0005[למודים אנו\u0006 במסורת \u0005שהבנות של אותו דור\u0006 מעשרת השבטים \u0005נעשו עקרות]\u0006 ולא ילדו בנים, וכל הנשים שנשאו הגולים מעשרת השבטים היו נשים גויות וממילא הילדים המצויים שם גוים הם.","\u0003איכא דאמרי\u0004 \u0005[יש שאומרים]\u0006 שכך היה הדבר, שסיפר רב יהודה: \u0003כי אמריתה קמיה\u0004 \u0005[כאשר אמרתי\u0006 את דברי רב אסי \u0005לפני]\u0006 \u0003שמואל, אמר לי: לא זזו משם,\u0004 כלומר לא זזו מן הדיון באותו נושא, \u0003עד שעשאום\u0004 את כל אלה, וגם את בני התערובת של עשרת השבטים במקומות שונים, כ\u0003גויים גמורים,\u0004 ואין חוששים לקידושיהם, \u0003שנאמר: \"בה' בגדו כי בנים זרים ילדו\"\u0004 (הושע ה, ז).","מסופר: \u0003יתיב\u0004 \u0005[ישב]\u0006 \u0003רב יוסף אחוריה\u0004 \u0005[אחרי]\u0006 \u0003רב כהנא ויתיב\u0004 \u0005[וישב]\u0006 \u0003רב כהנא קמיה\u0004 \u0005[לפני]\u0006 \u0003רב יהודה ויתיב וקאמר\u0004 \u0005[וישב ואמר]\u0006 לפני רב יהודה הלכה זו שקיבל: \u0003עתידין ישראל דעבדי יומא טבא כי חרבי\u0004 \u0005[לעשות יום טוב כאשר תיחרב]\u0006 \u0003תרמוד.\u0004 ושואלים: \u0003והא חריב\u0004 \u0005[והרי חרבה]!\u0006 ומשיבים: \u0003ההיא\u0004 אותו מקום שחרב \u0003תמוד הואי\u0004 \u0005[היה]\u0006 ולא תרמוד. \u0003רב אשי אמר: היינו\u0004 \u0005[זו היא]\u0006 \u0003תרמוד היינו\u0004 \u0005[זו היא]\u0006 \u0003תמוד,\u0004 ועיר אחת היא, אלא \u0003אכפולי הוא דמכפל\u0004 \u0005[כפולה היא\u0006 העיר הזאת\u0005]\u0006 שכאשר \u0003חריב מהאי גיסא\u0004 \u0005[\u0006היא \u0005נחרבת מצד זה] —\u0006 \u0003אותיב מהאי גיסא\u0004 \u0005[\u0006היא \u0005מתיישבת מצד זה],\u0006 \u0003ואי חריב מהאי גיסא\u0004 \u0005[ואם\u0006 היא \u0005נחרבת מצד זה]\u0006 — \u0003אותיב מהאי גיסא\u0004 \u0005[\u0006הריהי \u0005מתיישבת מצד זה]\u0006 ועדיין לא חרבה כליל. מסופר: \u0003יתיב\u0004 \u0005[ישב]\u0006 \u0003רב המנונא קמיה\u0004 \u0005[לפני]\u0006 \u0003עולא וקא הוי בשמעתא\u0004 \u0005[והיה עוסק בהלכה],\u0006 \u0003אמר\u0004 עולא עליו: \u0003מה גברא ומה גברא\u0004 \u0005[איזה אדם, ואיזה אדם]!\u0006 כלומר, כמה גדול הוא רב המנונא, \u0003אי לאו\u0004 \u0005[אם לא]\u0006 שהיתה \u0003הרפניא מאתיה\u0004 \u0005[עירו]!\u0006 שבני מקום זה לא היו מיוחסים, ופגם ייחוס פוגם בו. \u0003אכסיף\u0004 \u0005[התבייש]\u0006 רב המנונא, \u0003אמר ליה\u0004 \u0005[לו]\u0006 עולא: \u0003כסף גלגלתא\u0004 \u0005[הגולגולת],\u0006 את המיסים, \u0003להיכא יהבת\u0004 \u0005[להיכן אתה נותן,\u0006 משלם\u0005]?\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003ל\u0004עיר \u0003פום נהרא\u0004 אני משלם, שמקומי כפוף לשם מבחינת המסים. \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003אם כן, מפום נהרא את\u0004 \u0005[אתה]\u0006 ולא מהרפניא, ואין פגם בייחוסך.","","ושואלים: \u0003מאי\u0004 \u0005[מה]\u0006 משמעות השם \u0003הרפניא? אמר ר' זירא: הר שהכל פונין בו,\u0004 כלומר, שזהו מקום כזה שכל הנידחים שאינם מוצאים להם אשה במקום אחר הולכים לשם, וממילא רוב אנשיה פגומים מבחינת יחוסם. \u0003במתניתא תנא\u0004 \u0005[בברייתא שנה]:\u0006 \u0003כל שאין מכיר משפחתו ושבטו — נפנה לשם. אמר רבא: והיא,\u0004 הרעה שיש בפגם כזה, \u0003עמוקה משאול\u0004 (מהגיהנם), \u0003שנאמר: \"מיד שאול אפדם ממות אגאלם\"\u0004 (שם יג, יד), הרי שיש גאולה ויציאה משאול, \u0003ואילו\u0004 ה\u0003פסול דידהו\u0004 \u0005[שלהם]\u0006 \u0003לית להו תקנתא\u0004 \u0005[אין להם תקנה]\u0006 ממנו.","ומעירים: \u0003פסולי\u0004 \u0005[פסולם]\u0006 של אנשי \u0003הרפניא, משום פסולי\u0004 \u0005[\u0006ה\u0005פסול]\u0006 של תושבי \u0003מישון\u0004 הקרובה להם, שהיו פסולים, והם נתערבו באנשי הרפניא. \u0003ופסולי\u0004 העיר \u0003מישון משום פסולי\u0004 \u0005[\u0006ה\u0005פסול]\u0006 של תושבי \u0003תרמוד.\u0004 ו\u0003פסולי\u0004 העיר \u0003תרמוד משום עבדי שלמה\u0004 שהיו כאמור גוים ובאו על בנות ישראל וצאצאיהם פסולים.","ומעירים: \u0003והיינו דאמרי אינשי\u0004 \u0005[וזהו שאומרים אנשים]\u0006 בפתגם העממי באותו ענין: \u0003קבא רבא וקבא זוטא\u0004 \u0005[איפה גדולה ואיפה קטנה],\u0006 ששתיהן מידות פסולות, \u0003מיגנדר ואזיל\u0004 \u0005[מתגלגלת והולכת]\u0006 \u0003לשאול ומשאול לתרמוד ומתרמוד למישן, וממישן להרפניא.\u0004 ומשמע שהשאול (שהוא הגיהנם) הוא הגבוה מכולם וממנו ניתן עדיין לצאת וממנו יורדים לתרמוד ומתרמוד למישן וכן הלאה, ומהפגם המאפיין מקומות אלה אין אפשרות לצאת. והרי שאותם הדברים עצמם שאמרו החכמים בהסברת פסול היוחסין היו ידועים ומקובלים בפי העם בלשון משל.","","כל הנשים הפוטרות צרותיהן, שנמנו בפרק הראשון, נאסרו משום קירבת משפחה (ערוה), חוץ מאחת, ואותה מבארת משנה זו. \u0003כיצד\u0004 הוא המקרה של \u0003אשת אחיו שלא היה בעולמו?\u0004 — דוגמא לדבר: \u0003שני אחים, ומת אחד מהן\u0004 בלי בנים, \u0003ונולד להן אח ואחר כך ייבם השני,\u0004 האח הגדול, \u0003את אשת אחיו\u0004 המת, \u0003ומת\u0004 גם הוא. ונשארו איפוא שתי נשים הזקוקות לייבום, אשתו של האח הראשון שנתייבמה לאח השני, ואשת האח השני מכבר, שהיא צרתה של זו. \u0003הראשונה\u0004 אשת האח שמת תחילה — \u0003יוצאה\u0004 ואיננה חייבת בייבום על ידי האח הקטן שנולד אחר כך \u0003משום\u0004 שהיא \u0003אשת אחיו שלא היה בעולמו,\u0004 שהאח הראשון שמת לא היה מצוי בעולמו, באותו תחום חיים, עם האח החי הנולד. \u0003והשניה,\u0004 אשת האח השני, יוצאת ונפטרת \u0003משום צרתה.\u0004 והוא הביאור למה שלמדנו במשנה ראשונה.","ומוסיפים מקרה נוסף: אם \u0003עשה בה\u0004 האח השני רק \u0003מאמר,\u0004 שקידש אותה ולא בא עליה עדיין, שלא תפסו בה הקידושין אלא מדברי חכמים, \u0003ומת,\u0004 ונפלו לפני האח שנולד אחר מות אחיו הראשון גם אשת המת שנתקדשה במאמר לאח השני וגם אשתו מכבר של האח השני — הראשונה יוצאת בלא חליצה ובלא ייבום, משום שהיא עבור הנולד אשת אחיו שלא היה בעולמו, אבל ה\u0003שניה\u0004 שלא נעשתה בפועל צרתה של אשת האח הראשון, שהרי עשה בה רק מאמר ולא נישואין גמורים — \u0003חולצת ולא מתייבמת,\u0004 שאינה נחשבת כצרת ערוה אלא מדברי חכמים.","\u0003אמר רב נחמן: מאן דתני\u0004 \u0005[מי ששונה]\u0006 וגורס כאן \"ה \u0003ראשונה\u0004 יוצאה\" — \u0003לא משתבש\u0004 \u0005[איננו טועה]\u0006 בגרסתו, וכן \u0003מאן דתני\u0004 \u0005[מי ששונה]\u0006 וגורס כאן \"ה \u0003שניה\u0004 יוצאה\" — גם כן \u0003לא משתבש\u0004 \u0005[איננו טועה],\u0006 שגם גירסה זו יש לה הסבר, והכוונה בשתי הגירסות היא לאותה אשה עצמה, אשת האח הראשון. ומסבירים, \u0003מאן דתני\u0004 \u0005[מי ששונה]\u0006"],["\u0003\"ראשונה\" לא משתבש\u0004 \u0005[איננו טועה],\u0006 כי \u0003מאי\u0004 \u0005[מה]\u0006 פירוש \u0003\"ראשונה\" — ראשונה לנפילה,\u0004 שהרי זו נפלה ראשונה להתייבם. \u0003ומאן דתני\u0004 \u0005[ומי ששונה]\u0006 וקורא לה \u0003\"שניה\"\u0004 גם הוא \u0003לא משתבש\u0004 \u0005[איננו טועה],\u0006 כי \u0003מאי\u0004 \u0005[מה]\u0006 פירוש \u0003\"שניה\"\u0004 — כוונתו \u0003שניה לנשואין.\u0004 שהרי האח השני שמת היה כבר נשוי לאשה אחת, וזו, היבמה שייבם אותה, היא אשתו השניה. ותוהים: וכי סדר זה הוא הכרחי? \u0003מי לא עסקינן\u0004 \u0005[האם אין אנו עוסקים]\u0006 אפילו במקרה ש\u0003יבם\u0004 האח השני את אשתו של האח הראשון, \u0003ואחר כך כנס\u0004 (נשא) אשה אחרת, ואף אז אין הבדל בדין וממילא באופן כזה היבמה היא גם הראשונה. \u0003אלא,\u0004 כך יש להסביר: \u0003מאי\u0004 \u0005[מה]\u0006 פירוש \u0003\"שניה\"\u0004 שכך מכנים את אשתו של האח הראשון — הכוונה היא \u0003שניה בנשואין\u0004 שהרי כבר נישאה פעמיים לעומת אשת האח השני, שהיתה נשואה רק פעם אחת.","עד כאן לבירור לשון המשנה, ומעתה לגופם של דברים. \u0003אשת אחיו שלא היה בעולמו היכא כתיבא\u0004 \u0005[היכן\u0006 היא \u0005כתובה]\u0006 שבזו אין מצות ייבום? \u0003אמר רב יהודה אמר רב: אמר קרא\u0004 \u0005[הכתוב]\u0006 בתחילת הפרשה העוסקת בענין ייבום: \u0003\"כי ישבו אחים יחדו\"\u0004 (דברים כה, ה), משמע \u0003שהיתה להם ישיבה אחת\u0004 (\"יחדיו\") \u0003בעולם, פרט לאשת אחיו שלא היה בעולמו.\u0004 ועוד אנחנו למדים: \u0003\"יחדו\"\u0004 — משמעו ש\u0003מיוחדים בנחלה,\u0004 שיש להם צד של ייחוד וצירוף, משום שהם יורשים אותה נחלה, ומשמע שלענין ייבום מדובר באחים מן האב דווקא — \u0003פרט לאחיו מן האם\u0004 שאינם \"יחדיו\" לענין נחלה, לפי שכל אחד מהאחים מהאב יורש את אביו, ואלה אינם יורשים את האם.","\u0003רבה אמר:\u0004 ענין זה שייבום הוא רק ב\u0003אחין מן האב יליף\u0004 \u0005[נלמד]\u0006 בגזירה שווה של \u0003\"אחוה\" \"אחוה\" מבני יעקב,\u0004 שבייבום נאמר: \"כי יישבו אחים\", ובבני יעקב נאמר: \"שנים עשר אנחנו אחים בני אבינו\" (בראשית מב, לב), \u0003מה להלן\u0004 בבני יעקב הם כולם אחים \u0003מן האב ולא מן האם\u0004 שהרי הם מארבע אמהות, \u0003אף כאן\u0004 לגבי ייבום — דווקא אחים \u0003מן האב ולא מן האם.\u0004","ומקשים: מדוע למדים מבני יעקב? \u0003ולילף\u0004 \u0005[ושילמד]\u0006 \u0003\"אחוה\" \"אחוה\" מעריות,\u0004 שנאמר בפרשת עריות: \"ערות אשת אחיך לא תגלה ערות אחיך היא\" (ויקרא יח, טז), ובדיני עריות קירבת האחוה בין אחים (כגון לאיסור אשת אח) היא בין מן האב ובין מן האם! ומשיבים: יש להעדיף את הגזירה השווה הראשונה, כי \u0003דנין\u0004 ולמדים \u0003\"אחים\" מ\"אחים\",\u0004 שגם בבני יעקב וגם בדין ייבום נאמר \"אחים\", \u0003ואין דנין \"אחים\"\u0004 שנאמר בייבום \u0003מ\u0004מה שנאמר בעריות \u0003\"אחיך\".\u0004","ומקשים: \u0003מאי נפקא מינה\u0004 \u0005[מה יוצא מזה],\u0006 כלומר, מה ההבדל לענין גזירה שווה, גם אם יש שינוי מסויים בלשון, \u0003הא תנא דבי\u0004 \u0005[הרי שנה\u0006 החכם \u0005מבית\u0006 מדרשו\u0005]\u0006 של \u0003ר' ישמעאל\u0004 על מה שנאמר בפסוק אחד \u0003\"ושב הכהן\"\u0004 (ויקרא יד, לט) ונאמר בפסוק אחר \u0003\"ובא הכהן\"\u0004 (שם מד), דורשים: \u0003זו היא שיבה זו היא ביאה,\u0004 ולמדים גזירה שווה מזה על זה, למרות שהמילים \"ושב\" \"ובא\" אינן דומות זו לזו, וזאת מכיון שיש להן משמעות אחת — אפשר ללמוד מהן גזירה שווה, ועל כל פנים רואים אנו שגזירה שווה נלמדת אף בשתי מילים שונות לחלוטין בצורתן — כל שכן שהבדל קטן בגיזרת המלה איננו מעכב! ומשיבים: \u0003הני מילי היכא דליכא מידי דדמי ליה\u0004 \u0005[דברים אלה\u0006 אמורים \u0005היכן שאין דבר\u0006 אחר, מלה אחרת, \u0005שדומה לו\u0006 יותר\u0005]\u0006 \u0003אבל היכא דאיכא מידי דדמי ליה\u0004 \u0005[היכן שיש דבר\u0006 אחר \u0005שדומה לו] —\u0006 \u0003מדדמי ליה ילפינן\u0004 \u0005[מ\u0006זה \u0005שדומה לו\u0006 יותר \u0005אנחנו למדים]\u0006 וככל שהדמיון בין המילים גדול יותר, עדיף ללמוד מזה.","ומקשים מצד אחר: \u0003ולילף\u0004 \u0005[ושילמד]\u0006 \u0003\"אחוה\" \"אחוה\" מלוט, דכתיב\u0004 \u0005[שנאמר]\u0006 שאמר אברהם ללוט: \u0003\"כי אנשים אחים אנחנו\"\u0004 (בראשית יג, ח). ומכאן אפשר היה להסיק כי \"אחים\" מובנו קרובים, ולאו דווקא אחים! ודוחים: \u0003מסתברא\u0004 \u0005[מסתבר]\u0006 ש\u0003מבני יעקב הוה ליה למילף\u0004 \u0005[היה לו ללמוד],\u0006 \u0003משום דמפני\u0004 \u0005[ש\u0006הוא \u0005מופנה,\u0006 מיותר\u0005]\u0006 שהמלה \"אחים\" בבני יעקב מיותרת בעניינה, ובאה ללמדנו גזירה שווה: \u0003מדהוה ליה למכתב\u0004 \u0005[מ\u0006תוך \u0005שהיה לו לכתוב]\u0006 \u0003\"שנים עשר עבדיך בני אבינו\"\u0004 (בראשית מב, יג) \u0003וכתיב\u0004 \u0005[וכתוב]\u0006 בכל זאת \u0003\"אחים\u0004 בני אבינו \u0003\"\u0004— \u0003שמע מינה לאפנויי\u0004 \u0005[למד ממנה,\u0006 מכאן, שבא הדבר \u0005להפנות,\u0006 לייתר את המלה\u0005],\u0006 ללמדנו לענין אחר מהו הקרוי אחים.","ומעירים: \u0003ו\u0004אף שרב יהודה ורבה למדו אותו דין משני מקראות שונים, \u0003איצטריך\u0004 \u0005[צריך\u0006 היה\u0005]\u0006 גם לפי זה וגם לפי זה \u0003למכתב\u0004 \u0005[לכתוב]\u0006 \u0003\"אחים\" ואיצטריך למכתב\u0004 \u0005[[וצריך\u0006 היה \u0005לכתוב]\u0006 \u0003\"יחדו\". דאי כתב רחמנא\u0004 \u0005[שאם\u0006 היתה \u0005התורה כותבת]\u0006 \u0003\"אחים\"\u0004 בלבד, \u0003הוה אמינא\u0004 \u0005[הייתי אומר]:\u0006 \u0003לילף\u0004 \u0005[שנלמד]\u0006 \u0003\"אחוה\" \"אחוה\" מלוט, וכי תימא\u0004 \u0005[ואם תאמר]\u0006 ש\u0003לא מפני\u0004 \u0005[מופנה,\u0006 מיותר\u0005]\u0006 הוא כמו \"אחים\" בבני יעקב — \u0003לאי\u0004 \u0005[לא כן],\u0006 וודאי \u0003אפנויי מפני\u0004 \u0005[מופנה,\u0006 מיותר\u0005]\u0006 הוא, שהרי \u0003מדהוה ליה למכתב\u0004 \u0005[מ\u0006מה \u0005שהיה לו לכתוב]\u0006 אצל לוט \u0003\"רעים\",\u0004 שהרי באמת לא היו אחים ממש אלא רק קרובים, \u0003וכתיב\u0004 \u0005[ונאמר\u0006 בכל זאת\u0005]\u0006 \u0003\"אחים\" — שמע מינה\u0004 \u0005[למד ממנה,\u0006 מכאן\u0005]\u0006 לכאורה שבא הדבר \u0003לאפנויי\u0004 \u0005[להפנות,\u0006 לייתר את המלה\u0005]\u0006 וללמדנו שקרובים כאלה קרויים \"אחים\" אף לגבי ייבום, על כן \u0003כתב רחמנא\u0004 \u0005[כתבה התורה]\u0006 \u0003\"יחדו\"\u0004 ללמדנו: דווקא אחים \u0003המיוחדים בנחלה.\u0004","\u0003ואי כתב רחמנא\u0004 \u0005[ואילו כתבה התורה]\u0006 \u0003\"יחדו\"\u0004 בלבד ולא כתבה \"אחים\" — \u0003הוה אמינא דמייחדי באבא ובאמא\u0004 \u0005[הייתי אומר ש\u0006הם צריכים להיות \u0005מיוחדים באב ובאם],\u0006 ואם אינם אחים מאב ומאם אין מצות ייבום חלה עליהם — על כן נאמר \"אחים\" כמו אצל בני יעקב, שהם אחים רק מאב ולא מאם, ומשום כך איפוא \u0003צריכא\u0004 \u0005[צריך]\u0006 שייכתבו שניהם.","על סברה אחרונה זו, שהיה עולה על הדעת שבייבום צריך שיהיו אחים מאב ומאם, שואלים: \u0003והא מהיכא תיתי\u0004 \u0005[וזו מהיכן\u0006 היא \u0005באה],\u0006 מדוע נעלה על הדעת שיש חשיבות באחווה גם מצד האם בענין זה? הלא \u0003יבום בנחלה תלא רחמנא\u0004 \u0005[תלתה התורה],\u0006 שנאמר בתורה שהיבם יקום על שם אחיו המת, כלומר, שהוא יורש אותו, \u0003ונחלה מן האב ולא מן האם היא\u0004 באה! ומשיבים: אף על פי כן \u0003איצטריך\u0004 \u0005[נצרך]\u0006 הדבר, כי \u0003סלקא דעתך אמינא\u0004 \u0005[יעלה על דעתך לומר]:\u0006 \u0003הואיל וחידוש הוא\u0004 דין זה של ייבום \u0003דקמשתרי\u0004 \u0005[שמותרת]\u0006 אשה האסורה משום \u0003ערוה גביה\u0004 \u0005[אצלו,\u0006 אצל היבם\u0005],\u0006 שהרי אשת אח בכלל ערוה היא, ואם כן \u0003אימא\u0004 \u0005[אמור]\u0006 שנגביל את ההיתר הזה \u0003עד דמייחדי באבא ובאמא\u0004 \u0005[עד שיהיו מיוחדים\u0006 גם \u0005באב ו\u0006גם \u0005באם],\u0006 על כן \u0003צריכא\u0004 \u0005[נצרכה]\u0006 הגזירה שווה של \"אחים\" מבני יעקב להיאמר.","\u0003אמר רב הונא אמר רב: שומרת יבם\u0004 (אשה שמת בעלה וממתינה ליבם שייבם או יחלוץ לה) \u0003שמתה\u0004 לפני שייבמו אותה — \u0003מותר\u0004 אותו יבם \u0003באמה.\u0004 שאין עצם חובת הייבום יוצרת קירבה ביניהם. \u0003אלמא קסבר\u0004 \u0005[מכאן\u0006 שהוא, רב הונא בשם רב, \u0005סבור]\u0006 ש\u0003אין זיקה.\u0004 כלומר, שה\"זיקה\" — היות היבמה זקוקה ליבם — איננה יוצרת קשר הלכתי ביניהם. ושואלים: \u0003ולימא\u0004 \u0005[ושיאמר]\u0006 במפורש: \u0003הלכה כדברי האומר אין זיקה,\u0004 שבעיה זו שנויה במחלוקת תנאים, ומדוע לא פסק בפשטות הלכה כדעת התנא האומר שאין זיקה!","ומשיבים: \u0003אי הוה אמר הכי, הוה אמינא\u0004 \u0005[אם היה אומר כך, הייתי אומר]:\u0006 \u0003הני מילי בתרי\u0004 \u0005[דברים אלה\u0006 אמורים דווקא \u0005בשניים]\u0006 אם היו שני יבמים, וכל אחד מהם יכול לייבם, הייתי אומר שרק אז אין זיקה, כיון שהקשר בין כל אחד מן האחים ליבמה איננו קשר מוחלט, שהרי יתכן שאחיו הוא שישאנה, \u0003אבל בחד\u0004 \u0005[ב\u0006אח \u0005אחד] —\u0006 \u0003יש זיקה,\u0004 שהרי יבמה זו זקוקה רק לו, ויש איפוא ביניהם קשר, ולכך שינה בלשונו, לומר שאין הזיקה יוצרת קשר הלכתי ביניהם אפילו באחד.","ושואלים: \u0003ולימא\u0004 \u0005[ושיאמר]:\u0006 \u0003הלכה כדברי האומר אין זיקה אפילו בחד\u0004 \u0005[ב\u0006אח \u0005אחד]!\u0006 ומשיבים: \u0003אי אמר הכי, הוה אמינא\u0004 \u0005[אם\u0006 היה \u0005אומר כך, הייתי אומר]:\u0006 \u0003אפילו מחיים,\u0004 שאף כאשר יבמתו חיה וזקוקה לו לייבום, מותר לו לשאת את אמה — על כן \u0003קמשמע לן\u0004 \u0005[השמיע לנו]\u0006 ש\u0003לאחר מיתה — אין\u0004 \u0005[כן]\u0006 מותר באמה, אבל \u0003מחיים\u0004 — \u0003לא.\u0004 ומדוע — \u0003משום\u0004 ש\u0003אסור לבטל מצות יבמין.\u0004 שהרי אם הוא נושא את אמה, אינו יכול עוד לייבם את הבת, שבת אשתו אסורה עליו, ונמצא שעל ידי נישואין אלה ביטל את מצות הייבום שחלה עליו.","ומקשים על רב הונא: \u0003תנן\u0004 \u0005[שנינו\u0006 במשנה\u0005]:\u0006 \u0003יבמתו שמתה — מותר באחותה.\u0004 ונדייק: \u0003באחותה — אין\u0004 \u0005[כן],\u0006 שהרי גם אם היתה זו אשתו שמתה — היה מותר באחותה. אבל \u0003באמה — לא,\u0004","ודוחים: מכאן אין ראיה, כי אפשר לומר: \u0003הוא הדין\u0004 ש\u0003אפילו באמה\u0004 מותר, \u0003ואיידי דתנא רישא\u0004 \u0005[ומתוך ששנה\u0006 ב\u0005ראשה]\u0006 של משנה זו: \u0003אשתו שמתה מותר באחותה,\u0004 ששם הלשון מדוקדקת: \u0003באחותה — אין\u0004 \u0005[כן],\u0006 \u0003אבל באמה — לא, דהויא לה איסורא דאורייתא\u0004 \u0005[שהרי\u0006 היא \u0005לו איסור תורה],\u0006 שאסור לאדם לשאת אשה ובתה אף כשמתה אחת מהן — \u0003תנא נמי סיפא\u0004 \u0005[שנה גם כן\u0006 ב\u0005סופה]\u0006 של אותה משנה \u0003מותר באחותה,\u0004 ואין לדקדק בלשון, ובאמת מותר בכל קרובותיה. עד כאן שיטת רב הונא.","\u0003ורב יהודה אמר: שומרת יבם שמתה — אסור באמה.\u0004 ומעירים: \u0003אלמא קסבר\u0004 \u0005[מכאן\u0006 ש\u0005הוא\u0006 \u0005סבור]\u0006 ש\u0003יש זיקה,\u0004 ושקשר הזיקה בין היבמה ליבם דומה לקשר נישואין, ומשום כך אסור בקרובותיה. ויש לשאול: מדוע הוא אומר זאת בצורה זו? \u0003ולימא\u0004 \u0005[ושיאמר]\u0006 במפורש: \u0003הלכה כדברי האומר יש זיקה!\u0004","ומשיבים: \u0003אי הוה אמר הכי, הוה אמינא\u0004 \u0005[אם היה אומר כך, הייתי אומר]:\u0006 \u0003הני מילי\u0004 \u0005[דברים אלה]\u0006 שיש זיקה, אמורים \u0003בחד\u0004 \u0005[ב\u0006אח \u0005אחד],\u0006 שהרי היבמה זקוקה רק לו, \u0003אבל בתרי\u0004 \u0005[בשנים],\u0006 אם היו שני יבמים, שיתכן וייבם אותה אחיו, ולכך \u0003אין זיקה\u0004, לכן שינה בלשונו, לומר שאפילו בשני אחים אין אחד מהם יכול לשאת את אמה. ומקשים: \u0003והא כי פליגי\u0004 \u0005[והרי כאשר נחלקו]\u0006 תנאים בענין זה — \u0003בתרי פליגי\u0004 \u0005[בשני\u0006 אחים \u0005נחלקו]\u0006 וכיצד אפשר היה לחשוב שפסק שיש זיקה רק באחד? \u0003אלא,\u0004 כך יש לומר: \u0003אי אמר הכי\u0004 \u0005[אם\u0006 היה \u0005אומר כך]\u0006 כפסק הלכה: יש זיקה,"],["\u0003הוה אמינא\u0004 \u0005[הייתי אומר]\u0006 כי \u0003מחיים\u0004 כל עוד היבמה חיה — יש זיקה \u0003אבל לאחר מיתה — פקעה לה\u0004 ה\u0003זיקה,\u0004 שכיון שמתה היבמה, פקע כל קשר הקירבה ביניהם, על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 ש\u0003זיקה בכדי\u0004 \u0005[לריק,\u0006 לחינם\u0005],\u0006 \u0003לא פקעה\u0004 \u0005[איננה פוקעת],\u0006 ואין הזיקה בטלה אלא על ידי מעשה, חליצה או ייבום, וכל עוד לא נעשה המעשה נשאר הקשר במקומו. ומציעים: \u0003לימא מסייע ליה\u0004 \u0005[\u0006האם \u0005נאמר\u0006 שאפשר \u0005לסייע לו]\u0006 לרב יהודה, ממה ששנינו: \u0003יבמתו שמתה\u0004 — \u0003מותר באחותה.\u0004 ונדייק: \u0003באחותה — אין\u0004 \u0005[כן],\u0006 \u0003באמה — לא,\u0004 וכדברי רב יהודה!","ודוחים: מכאן אין ראיה, כי \u0003הוא הדין\u0004 ש\u0003אפילו באמה\u0004 מותר, \u0003ואיידי דתנא רישא\u0004 \u0005[ומכיון ששנה\u0006 ב\u0005ראשה]\u0006 של הברייתא \u0003אשתו שמתה מותר באחותה,\u0004 ששם ההיתר הוא \u0003דוקא באחותה, אבל באמה לא,\u0004 משום \u0003דהויא לה איסורא דאורייתא\u0004 \u0005[שהרי היא איסור תורה]\u0006 לשאת את אם אשתו גם אחר מותה — \u0003תנא נמי סיפא\u0004 \u0005[שנה גם כן\u0006 ב\u0005סופה]\u0006 \u0003מותר באחותה,\u0004 ולא דקדק.","\u0003מתיב\u0004 \u0005[מקשה]\u0006 על כך \u0003רב הונא בר חייא\u0004 ממה ששנינו במשנתנו: אם מת אחד האחים ולאחר מותו נולד לו אח ולאחר מכן \u0003עשה\u0004 האח הגדול \u0003בה\u0004 (באשת המת) \u0003מאמר ומת\u0004 — הראשונה פטורה מחליצה ומייבום מדין אשת אח שלא היה בעולמו, שהרי כשמת בעלה הראשון עדיין לא נולד היבם, וה\u0003שניה חולצת ולא מתייבמת.\u0004 ונדייק: \u0003טעמא\u0004 \u0005[הטעם,\u0006 דווקא\u0005]\u0006 \u0003דעבד\u0004 \u0005[שעשה]\u0006 \u0003בה מאמר, הא\u0004 \u0005[הרי]\u0006 אם \u0003לא עבד\u0004 \u0005[עשה]\u0006 \u0003בה מאמר — ה\u0004\u0003שניה נמי\u0004 \u0005[גם כן]\u0006 \u0003יבומי מייבמה\u0004 \u0005[מתייבמת],\u0006 \u0003ואי אמרת\u0004 \u0005[ואם אומר אתה]\u0006 \u0003יש זיקה,\u0004 אם כן \u0003הויא לה\u0004 \u0005[הרי היא]\u0006 \u0003צרת אשת אחיו שלא היה בעולמו בזיקה,\u0004 שהרי על ידי הזיקה היא נחשבת כצרת אשת אחיו!","\u0003אמר רבה:\u0004 אין לדקדק, \u0003הוא הדין דאף על גב\u0004 \u0005[שאף על פי]\u0006 ש\u0003לא עבד\u0004 \u0005[עשה]\u0006 \u0003בה מאמר — ה\u0004\u0003שניה מחלץ חלצה\u0004 \u0005[חולצת]\u0006 אבל \u0003יבומי לא מייבמה\u0004 \u0005[להתייבם, אינה מתייבמת],\u0006 משום שעל ידי הזיקה היא כצרת אשת אחיו שלא היה בעולמו.","\u0003והא דקתני\u0004 \u0005[וזה ששנה]\u0006 \u0003מאמר\u0004 דווקא, הרי בא הדבר \u0003לאפוקי\u0004 \u0005[להוציא,\u0006 לחלוק\u0005]\u0006 על \u0003בית שמאי דאמרי\u0004 \u0005[שאומרים]\u0006 ש\u0003מאמר קונה קנין גמור\u0004 ביבמה, כדרך שהקידושין קונים קנין גמור באשה, ולכן אפילו חליצה אינה צריכה, כדין צרת ערוה — על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 שגם אם עשה בה מאמר, אינה נחשבת כצרת ערוה ממש, ואין איסורה אלא מדברי סופרים, ולכן צריכה חליצה.","\u0003איתיביה\u0004 \u0005[הקשה לו]\u0006 \u0003אביי\u0004 ממה ששנינו: \u0003שני אחין בעולם אחד,\u0004 כלומר, שהיו קיימים זה בחיי זה, \u0003ומת אחד מהן בלא ולד, ועמד השני הזה לעשות מאמר ביבמתו, ולא הספיק לעשות בה מאמר עד שנולד לו אח, ומת\u0004 האח השני, וגם לו אשה, ונפלו שתיהן לייבום לפני האח הנולד, הרי \u0003הראשונה יוצאה\u0004 ונפטרת \u0003משום\u0004 שהיא \u0003אשת אחיו שלא היה בעולמו\u0004 של הנולד, \u0003ושניה\u0004 (אשת האח השני) — \u0003או חולצת או מתייבמת. ואי אמרת\u0004 \u0005[ואם אומר אתה]\u0006 ש\u0003יש זיקה,\u0004 הרי \u0003הויא לה\u0004 \u0005[הרי היא],\u0006 אותה אשת השני, \u0003צרת אשת אחיו שלא היה בעולמו\u0004 על ידי \u0003זיקה!\u0004","ודוחים: \u0003הא מני\u0004 \u0005[\u0006ברייתא \u0005זו\u0006 כשיטת \u0005מי היא] —\u0006 כשיטת \u0003ר' מאיר היא,\u0004 ש\u0003אמר: אין זיקה.\u0004 ושואלים: \u0003ומי סבירא ליה\u0004 \u0005[והאם סבור]\u0006 \u0003ר' מאיר אין זיקה? והתנן\u0004 \u0005[והרי שנינו\u0006 במשנה\u0005]\u0006 וסתם משנה כר' מאיר היא: \u0003ארבעה אחים, שנים מהן נשואים שתי אחיות, ומתו הנשואין האחיות,\u0004 ונפלו שתי האחיות לייבום לפני האחים — \u0003הרי אלו,\u0004 שתי האחיות, \u0003חולצות ולא מתייבמות.\u0004 ולכאורה הטעם הוא משום שעל ידי הזיקה נעשו כשתי אחיות הזקוקות, שתיהן יחד, לכל אחד מן האחים.","\u0003ואי סלקא דעתך\u0004 \u0005[ואם עולה על דעתך]\u0006 לומר ש\u0003סבר ר' מאיר אין זיקה,\u0004 הלא \u0003הני מתרי בתי קאתיין\u0004 \u0005[\u0006שתי אחיות \u0005אלה משני בתים הן באות]\u0006 שכל אחת היתה אשת אח אחר, ואם כן, \u0003האי לייבם חדא והאי לייבם חדא\u0004 \u0005[\u0006שאח \u0005זה ייבם אחת ו\u0006אח \u0005זה ייבם אחת]!\u0006","ומשיבים: \u0003לעולם\u0004 תאמר שדעת ר' מאיר ש\u0003אין זיקה.\u0004 ומה שנאמר במשנה שחולצות ולא מתייבמות, זה \u0003משום דקסבר\u0004 \u0005[שהוא\u0006 \u0005סבור]\u0006 \u0003אסור לבטל מצות יבמין.\u0004 כלומר, אסור לגרום מצב שיבוא לביטול מצות הייבום. ואף במקרה שלפנינו — \u0003דדלמא אדמייבם חד מיית אידך\u0004 \u0005[ששמא עד שייבם אחד, ימות\u0006 האח ה\u0005אחר,\u0006 השני\u0005]\u0006 לפני שייבם לשניה, \u0003וקא בטלת\u0004 \u0005[והתבטלה]\u0006 על ידי כך \u0003מצות יבמין,\u0004 שהרי אז תיפול לפני האח הנותר אחות זקוקתו, שאסורה להתייבם.","ומקשים: \u0003ואי\u0004 \u0005[ואם]\u0006 \u0003אין זיקה — תיבטל\u0004 מצות יבמים! שאם אין חושבים את הזיקה כקשר הלכתי מחייב — נמצא שמצוה זו עדיין לא חלה בפועל! \u0003דהא\u0004 \u0005[שהרי]\u0006 \u0003רבן גמליאל אמר: אין זיקה, ו\u0004הוא אמר גם ש\u0003מותר לבטל מצות יבמין.\u0004","\u0003דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005]:\u0006 אם היו שני אחים נשואים לשתי אחיות, אחת גדולה (בוגרת) שהיו נישואיה נישואין גמורים, ואחת קטנה שאין נישואיה אלא מדברי סופרים, ומת האח הנשוי לגדולה, ונפלה לייבום לפני האח הנשוי לקטנה. הציעו חכמים ליעץ לקטנה שתמאן בנישואי בעלה, ועל ידי כך יוכל ליבם את אשת אחיו, שאם לא כן לא יוכל ליבמה משום שהיא אחות אשתו הקטנה, ותיפטר לגמרי מחובת הייבום, ומן הדין זיקת הגדולה שהיתה נשואה לאח המת בנישואין גמורים, חזקה מנישואי הקטנה ליבם. \u0003רבן גמליאל אומר: אם\u0004 בינתים \u0003מאנה\u0004 הקטנה מעצמה — \u0003מאנה, ואם לא מאנה — תמתין עד שתגדיל\u0004 \u0005[שתגדל],\u0006 \u0003ו\u0004אז \u0003תצא הלזו\u0004 (האחרת), הגדולה, \u0003משום אחות אשה.\u0004 ונמצא שרבן גמליאל אינו חושש לביטול מצות יבמים מאחת מהן!","\u0003אמר ליה\u0004 \u0005[לו]:\u0006 מדבריו של \u0003רבן גמליאל\u0004 על דבריו של \u0003ר' מאיר קרמית\u0004 \u0005[אתה מטיל,\u0006 מראה סתירה\u0005]?!\u0006 הרי כל אחד מהם יש לו שיטה לעצמו! ומשיבים: \u0003לא, הכי קאמרינן\u0004 \u0005[כך אנחנו אומרים],\u0006 כך היתה כוונתנו לומר: כיצד יתכן לומר כי \u0003ר' מאיר חייש\u0004 \u0005[חושש]\u0006 \u0003אפילו לספיקא\u0004 \u0005[לספק]\u0006 של ביטול מצות ייבום, כפי שהסברנו שחושש שמא ימות אח אחד ותיבטל מצות יבמים, ואילו \u0003רבן גמליאל אפילו לודאי\u0004 ביטול מצוה זו \u0003לא חייש\u0004 \u0005[אינו חושש]!\u0006 ותמוה שיהא הבדל גדול כל כך בין שיטותיהם ומשיבים: \u0003דלמא מאן דלא חייש\u0004 \u0005[שמא מי שאיננו חושש]\u0006 לביטול מצות ייבום — \u0003אפילו לודאי\u0004 ביטולה \u0003לא חייש\u0004 \u0005[אינו חושש],\u0006 \u0003ומאן דחייש\u0004 \u0005[ומי שחושש] —\u0006 \u0003אפילו לספיקא חייש\u0004 \u0005[לספק\u0006 ביטולה \u0005חושש\u0006 הוא\u0005].\u0006","לעצם מחלוקת רב הונא ורב יהודה \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי לרב יוסף: הא\u0004 \u0005[\u0006הלכה \u0005זו]\u0006 של \u0003רב יהודה\u0004 ששומרת יבם שמתה אסור באמה — כשיטת רבו \u0003שמואל היא,\u0004 ולא קיבל אותה מרב, שגם הוא היה רבו. וראיה לדבר ממה \u0003דתנן\u0004 \u0005[ששנינו\u0006 במשנה\u0005]:\u0006"],["\u0003שומרת יבם\u0004 שמצפה לאחד האחים שייבם או יחלוץ לה, \u0003שקדש אחיו\u0004 של אותו יבם \u0003את אחותה, משום ר' יהודה בן בתירה אמרו: אומרים לו\u0004 לאח שקידש: \u0003המתן,\u0004 ואל תישא את ארוסתך \u0003עד שיעשה אחיך מעשה\u0004 — שיחלוץ או שייבם. כי עד אז חלה עדיין זיקת ייבום גם עליך, והאשה שקידשת היא אחות זקוקתך ואסורה עליך. \u0003ואמר שמואל: הלכה כר' יהודה בן בתירה.\u0004 משמע ששמואל הוא הסבור שיש זיקה.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 רב יוסף: \u0003דאי דרב מאי\u0004 \u0005[ואם של רב\u0006 היא \u0005מה]\u0006 ההבדל? \u0003אמר ליה\u0004 \u0005[לו]\u0006 אביי: אם כן \u0003קשיא\u0004 \u0005[קשה]\u0006 מדברי \u0003רב\u0004 על דברי \u0003רב\u0004 עצמו, שהרי רב הונא שאמר את ההלכה ששומרת יבם שמתה מותר באמה, אמר זאת משמו של רב, ומשמע אם כן מדברי רב עצמו שאין זיקה. אמר לו: \u0003דלמא אמוראי נינהו\u0004 \u0005[\u0006ו\u0005שמא\u0006 מחלוקת \u0005אמוראים\u0006 היא\u0005]\u0006 רב הונא ורב יהודה \u0003ואליבא\u0004 \u0005[ועל פי\u0006 \u0005שיטתו]\u0006 של \u0003רב?\u0004 ומשיבים: \u0003כיון דאיתמר משמיה\u0004 \u0005[שנאמר משמו]\u0006 של \u0003שמואל בהדיא\u0004 \u0005[במפורש],\u0006 \u0003ומשמיה\u0004 \u0005[משמו]\u0006 של \u0003רב\u0004 אפשר לפרש אותה רק \u0003כאמוראי\u0004 \u0005[כ\u0006מחלוקת \u0005אמוראים]\u0006 — \u0003לא שבקינן\u0004 \u0005[אין אנו עוזבים]\u0006 דבר האמור \u0003משמיה\u0004 \u0005[משמו]\u0006 של \u0003שמואל בהדיא\u0004 \u0005[במפורש]\u0006 \u0003ומוקמינן כאמוראי\u0004 \u0005[ומעמידים,\u0006 מפרשים, אותו \u0005כ\u0006מחלוקת \u0005אמוראים]\u0006 \u0003ואליבא\u0004 \u0005[ועל פי שיטתו]\u0006 של \u0003רב.\u0004","\u0003אמר רב כהנא: אמריתה לשמעתא קמיה\u0004 \u0005[אמרתי את השמועה,\u0006 הסוגיה הזו, \u0005לפני]\u0006 \u0003רב זביד מנהרדעא,\u0004 ומששמע זאת רב זביד, \u0003אמר: אתון, הכי מתניתו לה\u0004 \u0005[אתם, כך שונים אתם אותה]\u0006 ויש לכם ספקות! ואולם \u0003אנן, בהדיא מתנינן\u0004 \u0005[אנחנו, במפורש שונים]:\u0006 \u0003אמר רב יהודה אמר שמואל: שומרת יבם שמתה\u0004 — \u0003אסור באמה. אלמא קסבר\u0004 \u0005[מכאן\u0006 ש\u0005סבור]\u0006 שמואל כי \u0003יש זיקה. ואזדא\u0004 \u0005[והולך]\u0006 \u0003שמואל לטעמיה\u0004 \u0005[לטעמו,\u0006 לשיטתו\u0005].\u0006 ש\u0003אמר שמואל: הלכה כר' יהודה בן בתירה.\u0004","ומעירים: \u0003וצריכי\u0004 \u0005[ונצרכו]\u0006 שני הדברים שנאמרו בשם שמואל בשני הנושאים, ואינם חזרה על אותו רעיון. \u0003דאי אשמעינן\u0004 \u0005[שאם היה השמיע לנו]\u0006 את הכלל \u0003יש זיקה, הוה אמינא\u0004 \u0005[הייתי אומר]\u0006 כי \u0003הני מילי בחד\u0004 \u0005[דברים אלה\u0006 אמורים \u0005ב\u0006מקרה שיש רק אח \u0005אחד]\u0006 ששתיהן זקוקות רק לו, \u0003אבל בתרי\u0004 \u0005[בשניים]\u0006 שאין הזיקה של השניה לו חזקה אז כל כך, שהרי יתכן וייבמה אחיו, \u0003לא,\u0004 על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 שאפילו בשניים יש זיקה, ולכן פסק כר' יהודה בן בתירה. \u0003ואי אשמעינן\u0004 \u0005[ואם היה השמיע לנו]\u0006 רק ש\u0003הלכה כר' יהודה בן בתירה, הוה אמינא\u0004 \u0005[הייתי אומר]:\u0006 כי \u0003הני מילי\u0004 \u0005[דברים אלה\u0006 אמורים\u0005]\u0006 דווקא \u0003מחיים,\u0004 כאשר שומרת היבם חיה, \u0003אבל לאחר מיתה — פקעה לה זיקה\u0004 ומותר בקרובותיה, על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 ש\u0003זיקה בכדי\u0004 \u0005[\u0006בחינם, \u0005לריק]\u0006 \u0003לא פקעה,\u0004 אלא צריך שייעשה בה מעשה (ייבום או חליצה) כדי לפוטרה.","\u0003שני אחים, ומת אחד מהם ויבם השני\u0004 שהיה נשוי מכבר לאשה אחרת \u0003את אשת אחיו, ואחר כך נולד להן אח\u0004 שלישי, \u0003ומת\u0004 האח השני ונפלו שתי נשיו לפני האח השלישי — \u0003הראשונה,\u0004 אשת האח הראשון, \u0003יוצאה\u0004 ונישאת לאחרים בלא ייבום או חליצה \u0003משום אשת אחיו שלא היה בעולמו\u0004 של האח השלישי, \u0003והשניה,\u0004 שהיתה לפני כן אשת האח השני, יוצאת \u0003משום צרתה.\u0004 אם \u0003עשה בה\u0004 האח השני רק \u0003מאמר,\u0004 ולא כנס אותה בנישואין, \u0003ומת\u0004 — \u0003השניה חולצת ולא מתייבמת,\u0004 שאין כוחו של המאמר תקף כנישואין לעשות אותה כצרת ערוה גמורה.","\u0003ר' שמעון אומר:\u0004 האח, השלישי הנולד, \u0003מייבם לאיזו מהן שירצה, או חולץ לאיזו מהן שירצה.\u0004 כיון שנולד האח השלישי לאחר שייבם אחיו את האשה, הרי בימי חייו לא היתה זו עוד אשתו של האח הראשון ואינה נחשבת אשת אחיו שלא היה בעולמו, ולכן יכול הוא לייבם אותה, משום שהיא \"אשת אחיו שהיה בעולמו\".","\u0003אמר רב אושעיא: חלוק היה ר' שמעון אף בראשונה.\u0004 כלומר, ר' שמעון חלק לא רק במקרה המפורש במשנה שלנו כאשר האח הנולד מצא כבר את אשת אחיו הראשון נשואה לאחיו השני אלא גם לגבי המשנה הראשונה של פרק זה, כאשר האח השלישי נולד עוד לפני שייבם האח השני את האלמנה, ולדעתו, אם רצה יכול הוא לייבמה. \u0003ממאי\u0004 \u0005[ממה]\u0006 מניין אנו יודעים זאת — \u0003מדקתני\u0004 \u0005[מ\u0006כיון \u0005ששנה]\u0006 \u0003משנה יתירה,\u0004 מזה למד רב אושעיא.","וכיצד, \u0003בבא דרישא\u0004 \u0005[השער,\u0006 הקטע, \u0005ש\u0006ב\u0005ראש]\u0006 המשנה הקודמת, \u0003למאן קתני לה\u0004 \u0005[ל\u0006שיטתו של \u0005מי,\u0006 לצורך איזו שיטה \u0005שנה אותה]?\u0006 \u0003אילימא לרבנן\u0004 \u0005[אם תאמר ל\u0006שיטת \u0005חכמים]\u0006 שאוסרים אשת אחיו שלא היה בעולמו בכל מקרה, \u0003השתא\u0004 \u0005[עכשיו,\u0006 הרי\u0005]\u0006 במקרה שלנו, כאשר \u0003יבם\u0004 האח השני \u0003ולבסוף נולד\u0004 אח שלישי, \u0003דכי אשכחה\u0004 \u0005[שכאשר מצא אותה]\u0006 האח הנולד — \u0003בהתירא אשכחה\u0004 \u0005[בהיתר מצא אותה]\u0006 אצל השני, שהרי בחייו לא היתה אשת האח שמת, אלא אשתו של האח החי, ובכל זאת \u0003אסרי רבנן\u0004 \u0005[אוסרים חכמים]\u0006 — \u0003נולד\u0004 האח השלישי \u0003ואחר כך יבם\u0004 השני את אשת הראשון שמת, כמבואר במשנה הראשונה, \u0003מיבעיא\u0004 \u0005[נצרכה\u0006 לומר\u0005]?\u0006 ולשיטה זו די היה במשנתנו זו. \u0003אלא לאו\u0004 \u0005[האם לא]\u0006 \u0003ל\u0004שיטת \u0003ר' שמעון איצטריך\u0004 \u0005[הוצרך]\u0006 לכפול את הדברים,","\u0003ו\u0004כך יש להבין: \u0003תנא רישא\u0004 \u0005[שנה\u0006 את ההלכה המובאת במשנה ה\u0005ראשונה]\u0006 \u0003להודיעך כחו\u0004 של \u0003ר' שמעון,\u0004 כלומר, להודיע את תוקף שיטתו של ר' שמעון שמתיר גם במקרה המבואר במשנה הראשונה, \u0003ותנא סיפא\u0004 \u0005[ושנה\u0006 את \u0005סופה],\u0006 את ההלכה האמורה במשנה הזו \u0003להודיעך כחן דרבנן\u0004 \u0005[של חכמים],\u0006 שאף בייבם ולבסוף נולד הם אוסרים. \u0003ובדין הוא,\u0004 ראוי היה, \u0003דנפלוג\u0004 \u0005[\u0006שהיה צריך \u0005שיחלוק]\u0006 \u0003ר' שמעון\u0004 גם \u0003ברישא\u0004 \u0005[בראשונה],\u0006 ולומר שהוא מתיר גם בזו, \u0003אלא נטר להו לרבנן עד דמסיימי למילתייהו, והדר פליג עלייהו\u0004 \u0005[\u0006ש\u0005שמר,\u0006 המתין, \u0005להם לחכמים עד שסיימו את דבריהם, וחזר\u0006 ו\u0005חלק עליהם].\u0006","ושואלים: \u0003אלא\u0004 אם כן \u0003אשת אחיו שלא היה בעולמו לר' שמעון היכי משכחת לה\u0004 \u0005[כיצד אתה מוצא אותה]?\u0006 כיצד מתקיימת הלכה זו, לפי שיטתו? ומשיבים: \u0003בחד אחא ומית\u0004 \u0005[ב\u0006מקרה שהיה רק \u0005אח אחד, ומת]\u0006 \u0003ונולד לו אח.\u0004 אז אלמנת האח היא אשת אחיו שלא היה בעולמו, ואסורה להתייבם לו. \u0003אי נמי\u0004 \u0005[או גם כן]\u0006 \u0003בתרי\u0004 \u0005[בשני\u0006 אחים\u0005]\u0006 \u0003ולא יבם\u0004 אף אחד מהם מן האחים הנותרים את אשת האח \u0003ולא מית\u0004 \u0005[מת]\u0006 אחד מהם ובינתיים נולד אח שלישי. שכיון שזיקתה לייבום היא מכוח האח שמת, שהוא נחשב לגבי הנולד כאחיו שלא היה בעולמו, אסורה להתייבם לו.","ומעתה באים לברר את שיטת ר' שמעון: \u0003בשלמא\u0004 \u0005[נניח]\u0006 במקרה שהיו שני אחים ומת אחד מהם ו\u0003יבם\u0004 אחיו את אשתו \u0003ואחר כך נולד\u0004 אח שלישי, אפשר להסביר זאת: \u0003כי אשכחה\u0004 \u0005[כאשר מצא אותה]\u0006 האח השלישי, הנולד, את האשה הזו — \u0003בהתירא אשכחה\u0004 \u0005[בהיתר מצא אותה],\u0006 שהרי בחייו היא עבורו אשת האח החי שהיה בעולמו. \u0003אלא\u0004 כאשר בתחילה \u0003נולד\u0004 האח השלישי \u0003ואחר כך יבם\u0004 השני את אשת המת \u0003מאי טעמא\u0004 \u0005[מה טעם]\u0006 מתיר ר' שמעון? הלא אין להחשיבה בכגון זה כ\"אשת אחיו שהיה בעולמו\", שהרי עדיין לא נתייבמה! ומשיבים: צריך לומר כי \u0003קסבר\u0004 \u0005[סבור]\u0006 ר' שמעון ש\u0003יש זיקה,\u0004 והזיקה עצמה יוצרת קשר קירבה, ויתר על כן: \u0003ו\u0004אשה הקשורה ב\u0003זיקה ככנוסה\u0004 (נשואה) \u0003דמיא\u0004 \u0005[\u0006היא \u0005נחשבת],\u0006 וכיון שיש קשר זיקה בין היבמה לבין האח החי — הרי זה כאילו היתה כבר נשואה לו. וכיון שכך, הריהי נחשבת לגבי האח הנולד כאשת אחיו שהיה בעולמו.","\u0003מתקיף לה\u0004 \u0005[מקשה על כך]\u0006 \u0003רב יוסף: השתא\u0004 \u0005[עכשיו,\u0006 הרי\u0005],\u0006 כשקיימת \u0003זיקה ו\u0004נעשה \u0003מאמר,\u0004 בשניהם גם יחד \u0003מספקא ליה\u0004 \u0005[מסופק לו]\u0006 \u0003לר' שמעון אי\u0004 \u0005[אם]\u0006 \u0003ככנוסה דמיא\u0004 \u0005[\u0006היא \u0005נחשבת]\u0006 \u0003אי לאו\u0004 \u0005[אם לא]\u0006 \u0003ככנוסה דמיא\u0004 \u0005[\u0006היא \u0005נחשבת]\u0006 — כשאין אלא \u0003זיקה לחודה\u0004 \u0005[לעצמה],\u0006 \u0003מיבעיא\u0004 \u0005[נצרכה]\u0006 לומר שאינה ככנוסה?","ו\u0003מאי\u0004 \u0005[\u0006ו\u0005מה]\u0006 \u0003היא\u0004 ההוכחה שזו שיטת ר' שמעון — \u0003דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005]:\u0006 \u0003שלשה אחין\u0004 שהיו \u0003נשואין שלש נשים נכריות\u0004 (זרות זו לזו), \u0003ומת אחד מהם, ועשה בה\u0004 האח ה\u0003שני מאמר, ומת\u0004 — \u0003הרי אלו,\u0004 גם אשתו הראשונה של האח השני, וגם יבמתו שעשה בה מאמר, \u0003חולצות ולא מתייבמות.\u0004","ומה טעם אין מייבמים את אשת האח הראשון, \u0003שנאמר: \"ומת אחד מהם... יבמה יבא עליה\"\u0004 (דברים כה, ה), ומכאן נלמד: \u0003מי שעליה זיקת יבם אחד\u0004 היא שמתייבמת, \u0003ולא\u0004 מי \u0003שעליה זיקת שני יבמין,\u0004 שהרי האשה הזו היא מצד אחד יבמה מאשת האח הראשון שמת, ומצד שני (בגלל המאמר) היא יבמה גם מצד האח השני שמת.","ואילו \u0003ר' שמעון אומר: מייבם לאיזהו מהן שירצה,\u0004 שאינו מקבל דרשה זו שיש איסור ב\"זיקת שני יבמים\" \u0003וחולץ לשניה.\u0004 ומסבירים את שיטתו: \u0003יבומי תרוייהו\u0004 \u0005[לייבם\u0006 את \u0005שתיהן]\u0006 \u0003לא\u0004 מתיר ר' שמעון, ומדוע? — \u0003דדלמא\u0004 \u0005[ששמא]\u0006 \u0003יש זיקה,\u0004 ובשל הזיקה לאח השני, מחשיבים את האשה הזו כאילו כבר היתה נשואה לאח השני, \u0003והוו\u0004 \u0005[והרי הוא],\u0006 שתי הנשים הללו, \u0003שתי יבמות הבאות\u0004"],["\u0003מבית אחד\u0004 ולכל הדעות מותר לייבם רק אשה אחת כפי שנאמר: \"לבנות את בית אחיו\", ומשמעות הכתוב: בית אחד, ולא שני בתים. \u0003יבומי חדא ואיפטור אידך\u0004 \u0005[ליבם אחת ולפטור\u0006 על ידי כך את \u0005האחרת]\u0006 — \u0003לא, דדלמא\u0004 \u0005[ששמא]\u0006 \u0003אין זיקה\u0004 נחשבת לעשות את הזקוקה \u0003ככנוסה\u0004 (נשואה) ואז האשה הזאת שמת בעלה תחילה היא לגמרי אשתו של האח הראשון, והשניה היא לגמרי אשתו של האח השני, וכיון שיש פה שני ייבומים נבדלים, אינו יכול לפטור אחת על ידי ייבומה של האחרת, \u0003והוו להו\u0004 \u0005[והרי הן]\u0006 \u0003שתי יבמות הבאות משני בתים. אלמא\u0004 \u0005[\u0006משמע \u0005מכאן]\u0006 כי \u0003מספקא ליה\u0004 \u0005[מסופק לו]\u0006 לר' שמעון אם יש זיקה או אין זיקה, אפילו כשהיה שם מאמר!","\u0003וכי תימא\u0004 \u0005[ואם תאמר]:\u0006 \u0003מדאורייתא הכי נמי דמייבמא חדא ומפטרא חדא\u0004 \u0005[מ\u0006דברי \u0005תורה כך הוא גם כן שמתייבמת אחת ונפטרת אחת],\u0006 ולפי השיטה שזיקה ככנוסה, אלא \u0003ומדרבנן\u0004 \u0005[ומ\u0006דברי \u0005סופרים]\u0006 \u0003הוא\u0004 ש\u0003אסור\u0004 הדבר, \u0003גזירה משום שמא יאמרו\u0004 אלה שאינם יודעים, שבכלל כל \u0003שתי יבמות הבאות משני בתים חדא מייבמא ואידך מיפטרא\u0004 \u0005[אחת מתייבמת ואחת נפטרת]\u0006 \u0003בלא כלום,\u0004 ולכן אמר ר' שמעון שיחלוץ לאחרת כדי שלא יבואו לטעות — אולם אי אפשר לומר כן, שכן","\u0003והא טעמא\u0004 \u0005[והרי טעם]\u0006 שיטת \u0003ר' שמעון\u0004 מפורש בברייתא שלא מטעם גזירה הוא, אלא \u0003משום\u0004 השאלה האם \u0003מאמר ולאו\u0004 \u0005[או לא]\u0006 \u0003מאמר הוא,\u0004 כלומר, מה מידת תוקפו של המאמר. \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]\u0006 \u0003אמר להם ר' שמעון לחכמים\u0004 להסביר מדוע יכול הוא לייבם אחת מהן, וטעמו: \u0003אם מאמרו של שני מאמר,\u0004 שאנחנו מחשיבים אותו כנישואין גמורים, אם כן \u0003אשת שני הוא בועל\u0004 כאשר הוא מייבם אותה, משום שאם נחשב מאמרו של השני כנישואין, הרי היא אשתו הגמורה של היבם, וכל קשריה הקודמים אינם נחשבים עוד.","\u0003ואם מאמרו של שני אינו מאמר\u0004 ואין מתחשבים בו כלל, אם כן לא היה ביניהם כל קשר הלכתי, ואם מייבם אותה — נמצא שאת \u0003אשת ראשון הוא בועל.\u0004 ומכאן שטעמו של ר' שמעון הוא משום שהוא מסופק לגבי תוקף המאמר והזיקה.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי:\u0004 מכאן אין להוכיח מהי שיטת ר' שמעון, \u0003ולא שני לך\u0004 \u0005[ו\u0006האם \u0005אין שונה לך,\u0006 בעיניך\u0005]\u0006 \u0003בין זיקת יבם אחד לזיקת שני יבמים?\u0004 ויש מקום לחלק, \u0003דלמא\u0004 \u0005[שמא]\u0006 \u0003כי\u0004 \u0005[כאשר]\u0006 \u0003אמר ר' שמעון\u0004 כי \u0003זיקה ככנוסה דמיא\u0004 \u0005[נחשבת]\u0006 כפי שהסברנו שיטתו לענין אשת אח שלא היה בעולמו — הרי זה \u0003ביבם אחד,\u0004 שכיון שחובת הייבום מוטלת רק עליו נחשבת היבמה כאשתו, והוא המקרה שדנו בו, שכאשר מת אח אחד היה רק יבם אחד, \u0003אבל בשני יבמין — לא,\u0004 שכיון שהזיקה היא לשניהם כאחד, אין לראותה ככנוסה לאחד מהם, ולכן כשהיו שני יבמים היה לו ספק ביחס לזיקה.","ושואלים: \u0003ומי שני ליה\u0004 \u0005[והאם שונה לו,\u0006 מבדיל\u0005]\u0006 \u0003ר' שמעון\u0004 לענין אשת אחיו שלא היה בעולמו בין יבם אחד לשני יבמים? \u0003והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]\u0006 לענין אשת אחיו שלא היה בעולמו, \u0003כלל אמר ר' שמעון: כל שהלידה\u0004 של האח השלישי \u0003קודמת לנשואין\u0004 של האח השני, ומת גם אח זה, ונפלה לפני השלישי — \u0003לא חולצת ולא מתייבמת,\u0004 שבמקרה כזה היא אשת אחיו שלא היה בעולמו. אבל אם היו ה\u0003נשואין\u0004 של השני \u0003קודם ללידה\u0004 של השלישי ומת השני ונפלה לפני השלישי — \u0003או חולצת או מתייבמת.\u0004","\u0003מאי לאו\u0004 \u0005[האם לא]\u0006 מדובר כאן \u0003ביבם אחד, וקתני\u0004 \u0005[ושנה]\u0006 בברייתא: \u0003לא חולצת ולא מתייבמת,\u0004 הרי אפילו כשיש רק יבם אחד אין זה נחשב כנישואין גמורים, והרי היא אסורה כאשת אחיו שלא היה בעולמו. ודוחים: \u0003לא,\u0004 מדובר כאן \u0003בשני יבמים,\u0004 שהיו מתחילה שלושה אחים, ומת אחד מהם, ונפלה לייבום לפני שני אחים, ואחר כך נולד אח רביעי, ולכן לא נעשתה הזקוקה כנשואה.","ושואלים: אם כן, \u0003אבל ביבם אחד מאי\u0004 \u0005[מה]\u0006 יהיה הדין — \u0003הכי נמי\u0004 \u0005[כך גם כן]\u0006 תאמר שהיא \u0003או חולצת או מתייבמת,\u0004 שהזקוקה נעשתה כאשת האח השני לגמרי — \u0003אי הכי, אדתני\u0004 \u0005[אם כך, עד ש\u0006הוא \u0005שונה]\u0006 את הפיסקה הבאה: \u0003נשואין קודמין ללידה — או חולצת או מתייבמת, ליפלוג וליתני בדידה\u0004 \u0005[שיחלק וישנה\u0006 פרטים נוספים \u0005ב\u0006תוך הלכה זו \u0005עצמה]\u0006 ויאמר כך: \u0003במה דברים אמורים — בשני יבמים, אבל ביבם אחד — או חולצת או מתייבמת.\u0004","ודוחים: לא, ברייתא זו \u0003כולה בשני יבמין קמיירי\u0004 \u0005[היא עוסקת],\u0006 להבדיל, במקרה של שני יבמים, בין לידה קדמה לבין נישואין קדמו. ושואלים: \u0003ואלא\u0004 אם כן \u0003מאי כללא\u0004 \u0005[מה הכלל]\u0006 שבדבר? שאם מדובר בשני יבמים (ולא ביבם אחד), אם כן אין כאן כלל קבוע בנושא זה, שהרי ביבם אחד משתנה הדין ואפילו בלידה קודמת לנישואין, הריהי מותרת, ואיך ניתן לומר בכללות שכל שהלידה קודמת לנישואין לא חולצת ולא מתייבמת?!","\u0003ועוד, מתיב\u0004 \u0005[מקשה]\u0006 \u0003רב אושעיא\u0004 ממה ששנינו: היו \u0003שלשה אחין, שנים מהן נשואין שתי אחיות, או\u0004 שהיו נשואים \u0003אשה ובתה, או אשה ובת בתה, או אשה ובת בנה,\u0004 כלומר, שתי נשים שאסור לאדם לשאת אותן כאחת, ומתו האחים שהיו נשואים לקרובות — \u0003הרי אלו\u0004 שתיהן \u0003חולצות ולא מתייבמות,\u0004 שכיון ששתיהן כאחת זקוקות לו, ואינו רשאי לשאת את שתיהן, הרי הן דוחות זו את זו מייבום. \u0003ור' שמעון פוטר\u0004 אותן אפילו מן החליצה.","\u0003ו\u0004מעתה, \u0003אי סלקא דעתך\u0004 \u0005[אם עולה על דעתך]\u0006 כי \u0003קסבר\u0004 \u0005[סבור]\u0006 \u0003ר' שמעון\u0004 ש\u0003זיקה ככנוסה דמיא\u0004 \u0005[\u0006היא \u0005נחשבת],\u0006 אם כן — \u0003לייבם לקמייתא\u0004 \u0005[שייבם את הראשונה]\u0006 זו שבעלה מת קודם, שהרי על ידי עצם הזיקה נעשתה ככנוסה, והיא נחשבת כאשתו, \u0003ו\u0004ממילא \u0003תיפטר אידך\u0004 \u0005[האחרת],\u0006 שהרי אינו יכול לשאת שתי קרובות!","\u0003אמר רב עמרם: מאי\u0004 \u0005[מה]\u0006 פירוש \u0003פוטר\u0004 שאמר ר' שמעון, \u0003נמי\u0004 \u0005[גם כן]\u0006 משמעותו \u0003פוטר בשניה.\u0004 ומקשים: \u0003והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]:\u0006 \u0003ר' שמעון פוטר בשתיהן!\u0004 ומכאן שלדעתו אין זיקה ככנוסה.","\u0003אמר רבא:\u0004 באותה ברייתא מדובר שהיו שלושה אחים ומתו שנים מהם, וכל אחד מן האחים שמתו היה נשוי לארבע נשים שהיו קרובות זו לזו בכמה דרכים, שאשה אחת של האח הראשון היתה אחותה של אשת השני, ואשה אחרת שלו היא אמה של אשת אחיו האחרת, והשלישית — בת בתה של אשה אחרת של אחיו, והרביעית — בת בנה של אשה אחרת. וכאשר מתו האחים נפלו כל הנשים הללו לייבום לפני האח הנותר, ומה שר' שמעון פוטר את שתיהן — כוונתו לפי זה \u0003שניה שבזוג זה והשניה שבזוג זה.\u0004 שהרי כיון שאחת מהן זקוקה לו נפטרת קרובתה משום ערוה והשניה שבזוג משום צרתה, וכן בכולן.","ומעירים: \u0003קא טעי\u0004 \u0005[טעה]\u0006 \u0003רבא בארבעה זוגי\u0004 \u0005[זוגות]\u0006 כי בטעות הבין שבברייתא מדובר באחים שנשאו ארבעה זוגות של קרובות, ומדוע אנחנו אומרים שטעה? \u0003חדא\u0004 \u0005[\u0006ראיה \u0005אחת] —\u0006 \u0003ד\"או\" \"או\" קתני\u0004 \u0005[שנה]\u0006 שהרי בברייתא נאמר \"או אשה ובתה\", משמע שאין מדובר כאן כשנפלו כל הזוגות לפני יבם אחד. \u0003ועוד: \"ר' שמעון פוטר בארבעתן\" מיבעי ליה\u0004 \u0005[צריך\u0006 היה \u0005לו\u0006 לומר\u0005],\u0006 שהרי יש כאן ארבעה זוגות נשים!","\u0003ועוד:\u0004 הלא \u0003תניא\u0004 \u0005[שנינו\u0006 בברייתא\u0005]\u0006 במפורש: \u0003ר' שמעון פוטר בשתיהן מן החליצה ומן הייבום, שנאמר: \"ואשה אל אחתה לא תקח לצרר\"\u0004 (ויקרא יח, יח), ולמד מכאן כי \u0003בשעה שנעשו צרות זו לזו,\u0004 כאשר שתי אחיות עומדות להיעשות צרות זו לזו, כלומר, בזמן שנופלות שתיהן לייבום — \u0003לא יהא לך ליקוחין\u0004 (\"לא תקח\"), כלומר, אין נישואין חלים, \u0003אפילו באחת מהן,\u0004 הרי משמע ששתיהן פטורות, ולא השניה בלבד!","\u0003אלא אמר רב אשי: אי דנפול בזה אחר זה הכי נמי\u0004 \u0005[אם שנפלו\u0006 לפניו היבמות \u0005בזו אחר זו כך הוא גם כן]\u0006 וזיקה של הראשונה עושה אותה ככנוסה ופוטרת את השניה (הקרובה שלה) לגמרי, אלא \u0003הכא במאי עסקינן\u0004 \u0005[כאן במה אנו עוסקים] —\u0006 \u0003דנפול\u0004 \u0005[שנפלו]\u0006 שתיהן לפניו \u0003בבת אחת,\u0004 שמתו שני האחים בבת אחת, \u0003ור' שמעון סבר לה\u0004 \u0005[סבור]\u0006 \u0003כר' יוסי הגלילי,\u0004 ש\u0003אמר: אפשר לצמצם.\u0004 כלומר, הוא סבור — בניגוד לדעת חכמים אחרים — שאפשר לדייק בקביעת הזמן. ולכן, שני דברים יכולים לקרות במדוייק בהחלט בזמן אחד. ואפשר איפוא לומר ששני האחים אכן מתו ברגע אחד.","עד כאן עסקנו בבירור שיטת רב אושעיא, שלדברי ר' שמעון גם בנולד השלישי ואחר כך ייבם השני את אשת האח שמת לפני שנולד השלישי ומת השני, שאינה נחשבת כאשת אחיו שלא היה בעולמו. אולם \u0003רב פפא אמר: בייבם\u0004 האח השני, \u0003ואחר כך נולד\u0004 האח השלישי — בזה \u0003פליג\u0004 \u0005[חולק]\u0006 \u0003ר' שמעון,\u0004 ואילו \u0003בנולד\u0004 האח השלישי לאחר מות הראשון \u0003ואחר כך ייבם\u0004 האח השני את אשת המת — \u0003לא פליג\u0004 \u0005[חולק]\u0006 ר' שמעון, והוא מודה שהיא אסורה לאח הנולד משום אשת אחיו שלא היה בעולמו.","ולשאלה שעמדה בפני רב אושעיא מדוע צריך היה לשנות דינים דומים גם במשנה הראשונה שבפרק וגם במשנתנו — ניתן להסביר כי \u0003ותרווייהו לרבנן איצטריך\u0004 \u0005[ושניהם הוצרכו ל\u0006דעת \u0005חכמים]\u0006 שאסרו אשת אחיו שלא היה בעולמו בכל מקרה. ואת הקושי: מדוע נצרכה המשנה הראשונה, כאשר בשניה מתברר הדין ביתר תוקף — צריך להסביר שבסגנון של \u0003\"לא זו אף זו\" קתני\u0004 \u0005[שנה],\u0006 כלומר, שפותח בענין הקל והפשוט ומסיים בדבר שיש בו חידוש גדול יותר. ולפי סגנון מקובל זה אין צורך להכניס פה מחלוקת נוספת עם ר' שמעון.","ומעירים: \u0003תניא כוותיה\u0004 \u0005[שנויה\u0006 הברייתא \u0005כשיטתו]\u0006 של \u0003רב פפא, ותיובתא\u0004 \u0005[ו\u0006היא \u0005קושיה\u0006 חמורה\u0005]\u0006 ל\u0003רב אושעיא.\u0004 ששנינו: \u0003שני אחים בעולם אחד,\u0004 כלומר, שהיו קיימים זה בחיי זה, \u0003ומת אחד מהם בלא ולד, ועמד השני הזה לעשות מאמר ביבמתו ולא הספיק לעשות בה מאמר, עד שנולד לו אח, ומת\u0004 האח השני — \u0003הראשונה יוצאה משום אשת אחיו שלא היה בעולמו, ושניה\u0004 (אשתו של האח השני) — \u0003או חולצת או מתייבמת,\u0004 שהרי היא לא היתה צרתה של הראשונה מעולם.","\u0003עשה בה\u0004 השני \u0003מאמר, ואחר כך נולד אח, או שנולד לו אח ואחר כך עשה בה מאמר, ומת — הראשונה יוצאה משום אשת אחיו שלא היה בעולמו, ושניה\u0004 — \u0003חולצת ולא מתייבמת\u0004 משום שהיא צרת אשת אחיו שלא היה בעולמו מדברי סופרים, בגלל המאמר שעשה."],["\u0003ר' שמעון אומר: ביאתה או חליצתה של אחת מהם פוטרת\u0004 את \u0003צרתה\u0004 והכוונה שיחלוץ או ייבם לאשת אחיו השני והראשונה נפטרת ממילא, אבל אם \u0003חלץ לבעלת מאמר — לא נפטרה\u0004 על ידי כך ה\u0003צרה,\u0004 זו שהיתה אשת האח השני, שמא אין כוח המאמר כנשואין. \u0003כנסה\u0004 האח השני את אשת אחיו המת, \u0003ומת\u0004 גם הוא, \u0003ואחר כך נולד לו אח, או שנולד לו אח ואחר כך כנסה, ומת — שתיהן פטורות מן החליצה ומן הייבום,\u0004 אחת משום אשת אחיו שלא היה בעולמו, והשניה משום צרתה.","\u0003כנסה\u0004 את יבמתו ואחר כך \u0003נולד לו אח, ואחר כך מת\u0004 — \u0003שתיהן,\u0004 גם אשת האח שמת תחילה וגם אשת המייבם, \u0003פטורות מן החליצה ומן הייבום,\u0004 אלו \u0003דברי ר' מאיר. ור' שמעון אומר: הואיל ובא\u0004 האח השלישי הזה \u0003ומצאה בהיתר, ולא עמדה עליו שעה אחת באיסור,\u0004 שהרי על האח השלישי לא היתה אשה זו אסורה מעולם, שכן כשנולד כבר היתה היא אשת האח השני החי, על כן — \u0003מייבם לאיזו מהן שירצה, או חולץ לאיזו מהן שירצה.\u0004","ונברר: \u0003הא בבא דסיפא למאן קתני לה\u0004 \u0005[את השער,\u0006 הקטע \u0005הזה שבסופה של\u0006 ברייתא זו בייבם ולבסוף נולד \u0005ל\u0006צורך דעתו של \u0005מי שנה אותה]?\u0006 \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 ש\u0003ל\u0004צורך \u0003ר' מאיר קתני לה\u0004 \u0005[שנה אותה] —\u0006 \u0003מכדי\u0004 \u0005[הרי]\u0006 \u0003לא שני ליה\u0004 \u0005[שונה לו]\u0006 \u0003לר' מאיר בין ייבם ואחר כך נולד\u0004 ו\u0003בין נולד ואחר כך ייבם,\u0004 שלשיטתו בשני המקרים הרי זו אשת אחיו שלא היה בעולמו ואסורה לו, ואם כן \u0003לערבינהו ולתנינהו\u0004 \u0005[שיערב אותם וישנה אותם\u0006 יחד\u0005],\u0006 באופן זה: כנסה ומת ואחר כך נולד לו אח, או שנולד לו אח ואחר כך כנסה ומת, או שכנסה ונולד לו אח ואחר כך מת — שתיהן פטורות?!","\u0003אלא לאו\u0004 \u0005[האם לא]\u0006 שהקטע האחרון נועד רק להבהיר את דעת \u0003ר' שמעון.\u0004 וכיון שבחלקים השונים בברייתא זו מנויות כל האפשרויות \u0003ובייבם ואחר כך נולד פליג\u0004 \u0005[חולק]\u0006 ר' שמעון, ואילו \u0003ב\u0004מקרה ש\u0003נולד\u0004 האח בזמן שאשת המת היתה עדיין זקוקה לייבום \u0003ואחר כך ייבם\u0004 החי \u0003לא פליג\u0004 \u0005[איננו חולק],\u0006 משמע שאף הוא מסכים להלכה זו. ומסכמים: אכן, \u0003שמע מינה\u0004 \u0005[למד מכאן]\u0006 שר' שמעון חולק רק בזו, וכדברי רב פפא.","כיון שהזכרנו ברייתא זו, באים לדון בה לגופה. \u0003אמר מר\u0004 \u0005[החכם]:\u0006 \u0003עמד השני לעשות מאמר\u0004 (קידושי כסף) \u0003ביבמתו ולא הספיק לעשות מאמר ביבמתו עד שנולד לו אח, ומת\u0004 השני ונפלו שתיהן, אשת האח הראשון ואשת השני, לפני השלישי, הנולד, לייבום — \u0003ראשונה יוצאה משום\u0004 שהיא \u0003אשת אחיו שלא היה בעולמו, ושניה — או חולצת או מתייבמת.\u0004 ושואלים: \u0003מאי\u0004 \u0005[ומה\u0006 פירוש\u0005]\u0006 \u0003\"עמד\", ומאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"לא הספיק\"\u0004 לעשות מאמר? שהרי מאמר הוא הקידושין, והשאלה איננה מה היתה כוונתו, כי אם מה קרה למעשה, \u0003אי עבד\u0004 \u0005[אם עשה]\u0006 — \u0003עבד\u0004 \u0005[עשה],\u0006 \u0003ואי\u0004 \u0005[ואם]\u0006 \u0003לא עבד\u0004 \u0005[עשה]\u0006 — \u0003לא עבד\u0004 \u0005[עשה]!\u0006","\u0003אלא\u0004 צריך לפרש כך: \u0003\"עמד\"\u0004 פירושו עמד לעשות מאמר \u0003מדעתה,\u0004 בהסכמתה, \u0003ו\"לא הספיק\"\u0004 — כוונתו שלא הספיק לעשות זאת \u0003מדעתה, אלא בעל כרחה,\u0004 ובאופן כזה אין המאמר מועיל לכלום וחולצת ולא מתייבמת. \u0003ו\u0004תהיה שיטת ברייתא זו מפורשת ש\u0003לא כ\u0004שיטתו של \u0003רבי. דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003העושה מאמר ביבמתו\u0004 (שמקדש אותה) \u0003שלא מדעתה,\u0004 שלא בהסכמתה, \u0003רבי אומר: קנה\u0004 מדברי סופרים, והקידושין הללו תופסים כמאמר של יבם מדעתה, \u0003וחכמים אומרים: לא קנה\u0004 כלל.","ומפרשים: \u0003מאי טעמא\u0004 \u0005[מה טעם]\u0006 שיטת \u0003רבי — גמר\u0004 \u0005[למד]\u0006 זאת \u0003מביאה ש\u0004בא היבם על ה\u0003יבמה,\u0004 באופן זה: \u0003מה ביאה\u0004 ב\u0003יבמה\u0004 — אפילו בא עליה \u0003בעל כרחה\u0004 קובעת שהיא נעשית אשתו, ואין הדבר תלוי בהסכמתה, \u0003אף קדושין\u0004 ב\u0003יבמה\u0004 יכולים שיהיו \u0003בעל כרחה. ורבנן גמרי\u0004 \u0005[וחכמים למדים]\u0006 \u0003מקדושין דעלמא\u0004 \u0005[בכלל]\u0006 באופן זה: \u0003מה קדושין דעלמא\u0004 \u0005[בכלל] —\u0006 אינם תופסים אלא אם כן נעשים \u0003מדעתה\u0004 של האשה, \u0003אף קדושין\u0004 ב\u0003יבמה\u0004 אינם מועילים אלא אם כן נעשים \u0003מדעתה.\u0004","ומסבירים: \u0003במאי קמיפלגי\u0004 \u0005[במה הם חלוקים],\u0006 כלומר, מהו העקרון המונח בביסוס מחלוקת זו? — \u0003מר סבר\u0004 \u0005[חכם\u0006 זה, רבי, \u0005סבור]\u0006 כי \u0003מילי\u0004 \u0005[דברים,\u0006 הלכות\u0005]\u0006 של \u0003יבמה ממילי\u0004 \u0005[מדברים,\u0006 מהלכות\u0005]\u0006 של \u0003יבמה הוה ליה למילף\u0004 \u0005[היה לו ללמוד]\u0006 ולא מתחום אחר, \u0003ומר סבר\u0004 \u0005[וחכם\u0006 זה, חכמים, \u0005סבור]:\u0006 \u0003מילי\u0004 \u0005[דברים,\u0006 הלכות\u0005]\u0006 של \u0003קדושין ממילי\u0004 \u0005[מדברים,\u0006 מהלכות\u0005]\u0006 של \u0003קדושין הוה ליה למילף\u0004 \u0005[היה לו ללמוד].\u0006","ומבררים קטע אחר בברייתא. שנינו בה: שני אחים ומת האחד ו\u0003עשה בה\u0004 השני \u0003מאמר ואחר כך נולד לו אח, או ש\u0004קודם \u0003נולד לו אח ואחר כך עשה בה,\u0004 באשת הראשון, \u0003מאמר, ומת\u0004 ונפלה לפני השלישי, הנולד, לייבום — \u0003ראשונה יוצאה משום\u0004 שהיא לו \u0003אשת אחיו שלא היה בעולמו, ושניה חולצת ולא מתייבמת. ר' שמעון אומר: ביאתה או חליצתה של אחת מהן פוטרת צרתה.\u0004","ושואלים: \u0003ר' שמעון אהייא קאי\u0004 \u0005[על איזה\u0006 מהם, מן המקרים, הוא \u0005עומד,\u0006 מתייחס\u0005]?\u0006 \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 כי למקרה של \u0003נולד לו אח ואחר כך עשה בה\u0004 השני \u0003מאמר\u0004 הוא מתייחס — \u0003הא אמרת\u0004 \u0005[הרי\u0006 כבר \u0005אמרת]\u0006 ש\u0003בנולד\u0004 השלישי \u0003ולבסוף,\u0004 לאחר שנולד, \u0003ייבם\u0004 השני את אשת הראשון \u0003לא פליג\u0004 \u0005[חולק]\u0006 \u0003ר' שמעון,\u0004 והריהי אסורה משום אשת אחיו שלא היה בעולמו. \u0003אלא\u0004 צריך לומר כי על המקרה בו \u0003עשה בה מאמר\u0004 השני \u0003ואחר כך נולד לו אח\u0004 חלק ר' שמעון ולדעתו חולץ או מייבם לשניה.","בהמשך הברייתא נאמר שאם \u0003חלץ\u0004 השלישי \u0003לבעלת מאמר לא נפטרה\u0004 ה\u0003צרה,\u0004 כלומר, אשת השני, ויכולה להינשא לאחרים. ומבררים: \u0003מאי טעמא\u0004 \u0005[מה הטעם] —\u0006 \u0003משום דהואי\u0004 \u0005[שהיא]\u0006 ה\u0003צרה,\u0004 אשת האח השני, היא חיוב \u0003ודאי,\u0004 שהרי היא אשת אחיו שהיה בעולמו, \u0003ובעלת\u0004 ה\u0003מאמר\u0004 אינה אלא \u0003ספק,\u0004 שלא ברור אם על ידי המאמר נעשתה לגמרי כאשת האח השני או לא, \u0003ו\u0004כלל הוא ש\u0003אין ספק מוציא מידי ודאי,\u0004 ולכן, אם יחלוץ לה היבם, כיון שחיובה אינו ברור — אף חליצתה איננה חליצת ודאי, כי שמא לא היתה צריכה לחליצה, ולפיכך לא הועילה החליצה לפטור את צרתה, ועל כן השמיע לנו שצריך לחלוץ או לייבם לודאית ואז תיפטר האחרת.","\u0003יתיב\u0004 \u0005[ישב]\u0006 \u0003רב מנשה בר זביד קמיה\u0004 \u0005[לפני]\u0006 \u0003רב הונא ויתיב וקאמר\u0004 \u0005[וישב ואמר]\u0006 דבר זה: \u0003מאי טעמא\u0004 \u0005[מה טעם]\u0006 שיטת \u0003ר' שמעון\u0004 שמתיר בייבם ולבסוף נולד אשת אח שלא היה בעולמו? ותוהים: \u0003מאי טעמא\u0004 \u0005[מה טעם]\u0006 שיטת \u0003ר' שמעון?!\u0004 — \u0003כדאמר טעמא\u0004 \u0005[כ\u0006פי \u0005שאמר\u0006 את \u0005הטעם]\u0006 באותה ברייתא: \u0003הואיל ובא ומצאה בהיתר, ולא עמדה עליו שעה אחת באיסור!\u0004","\u0003אלא\u0004 כך היתה השאלה: \u0003מאי טעמא דרבנן\u0004 \u0005[מה טעם\u0006 שיטת \u0005חכמים]\u0006 האוסרים בייבם ולבסוף נולד? שהרי ר' שמעון נתן טעם טוב לשיטתו. ומשיבים: \u0003אמר קרא\u0004 \u0005[הכתוב]:\u0006 \u0003\"ולקחה לו לאשה ויבמה\"\u0004 (דברים כה, ה), ומשמעו: \u0003עדיין יבומים הראשונים עליה,\u0004 שגם לאחר שלקחה לו לאשה, עדיין היא נחשבת ליבמה, ועל כן לא פקע ממנה האיסור שהיה עליה בעודה יבמה מבעלה הראשון. ותוהים: \u0003אלא הא דתנן\u0004 \u0005[זו ששנינו\u0006 במשנה\u0005]:\u0006 \u0003כנסה,\u0004 נשא את היבמה לאשה — \u0003הרי היא כאשתו לכל דבר. ואמר ר' יוסי בר חנינא:\u0004 דבר זה \u0003מלמד,\u0004"],["\u0003שמגרשה\u0004 את היבמה \u0003בגט\u0004 ואינה צריכה חליצה, \u0003ומחזירה,\u0004 שאם רוצה רשאי להחזירה לאחר גירושיה, ואין אומרים שלאחר שקיים בה את המצוה, שוב נאסרה עליו כאשת אח. ומדוע? \u0003התם נמי לימא\u0004 \u0005[שם גם כן נאמר]\u0006 \u0003\"ויבמה\"\u0004 כפי שפירשנו: \u0003עדיין יבומין הראשונים עליה, ותיבעי\u0004 \u0005[ותצטרך]\u0006 \u0003חליצה!\u0004","ומשיבים: \u0003שאני התם\u0004 \u0005[שונה שם]\u0006 ש\u0003אמר קרא\u0004 \u0005[הכתוב]\u0006 \u0003\"ולקחה לו לאשה\"\u0004 (דברים כה, ה), לומר לנו: \u0003כיון שלקחה — נעשית כאשתו לכל דבר.\u0004 ומקשים: \u0003אי הכי הכא נמי\u0004 \u0005[אם כך כאן גם כן]\u0006 נאמר כך מכיון שנעשתה אשתו לכל דבר שוב לא תיאסר על האח שנולד לאחר הייבום! ומשיבים: \u0003הא כתב רחמנא\u0004 \u0005[הרי כתבה התורה]\u0006 \u0003\"ויבמה\",\u0004 לומר שאף לאחר נישואיה עדיין נחשבת היא כיבמה ואסורה לו.","ושואלים: \u0003ומה ראית\u0004 לחלק ולומר שאחר נישואין בטל דין יבמה לגמרי, ואיסור אשת אחיו שלא היה בעולמו לא בטל אחר ייבום? ומשיבים: \u0003מסתברא, שדי היתירא אהיתירא ושדי איסורא אאיסורא\u0004 \u0005[מסתבר\u0006 לומר כך, כי \u0005הטל היתר על היתר והטל איסור על איסור],\u0006 כלומר, במקום שהותרה כבר האשה על ידי נישואין, נראה לומר שיהא היתר מוחלט, ובמקום שיש חשש איסור של אשת אחיו שלא בעולמו — מן הסתם בא הכתוב להחמיר ולצמצם.","ושואלים: \u0003ול\u0004שיטת \u0003ר' שמעון,\u0004 ש\u0003אמר\u0004 בטעם שיטתו, \u0003הואיל ובא ומצאה בהיתר ולא עמדה עליו שעה אחת באיסור, אלא מעתה,\u0004 אם היתה \u0003אחותו מאמו\u0004 שאיננה אחותו מאביו \u0003שנשאה אחיו מאביו\u0004 שאיננו אחיו מאמו, ונשא איפוא בהיתר גמור \u0003ואחר כך נולד\u0004 לו \u0003אח\u0004 מאב ואם, \u0003ומת\u0004 אותו שנשא את האשה, \u0003תתייבם\u0004 האחות לזה שנולד מאותו טעם: \u0003הואיל ובא ומצאה בהיתר,\u0004 שהרי כשנולד כבר היתה אשת אחיו!","על קושיה זו תוהים: איך אפשר לומר כך, שכן \u0003איסור אחותו להיכן אזל\u0004 \u0005[הלך]?!\u0006 הרי לגבי האח הנולד היא אחותו מאמו, ואסורה עליו! ומקשים: אם כן, \u0003הכא נמי\u0004 \u0005[כאן גם כן]\u0006 אפשר היה לומר: \u0003איסור אחיו שלא היה בעולם להיכן אזל\u0004 \u0005[הלך]\u0006 והרי אף כאן כבר חל איסור אשת אח על אשה זו מאחיו הראשון ולמה אומר ר' שמעון שבטל על ידי הנישואין? ודוחים: אין מקום להשוואה זו, כי \u0003האי איסורא דלית ליה היתירא\u0004 \u0005[זה, איסור\u0006 אחותו, הוא איסור \u0005שאין לו היתר]\u0006 בשום מקרה ולא בטל, ואילו \u0003האי איסורא דאית ליה היתירא\u0004 \u0005[זה איסור\u0006 אשת אח, הוא איסור \u0005שיש לו היתר]\u0006 כשיש מצות ייבום ולכן בטל.","\u0003כלל אמרו ביבמה: כל שהיא\u0004 אסורה \u0003איסור ערוה\u0004 על היבם — \u0003לא חולצת ולא מתייבמת\u0004 ונפטרת לגמרי. ואם היתה אסורה עליו רק \u0003איסור מצוה\u0004 או \u0003איסור קדושה\u0004 (כפי שיבואר להלן מה עניינם), כיון שלא בטל מיסודו חיוב הייבום — הרי זו \u0003חולצת\u0004 כדי להשתחרר מן הזיקה, \u0003ו\u0004אולם \u0003לא מתייבמת\u0004 בגלל האיסור.","ועוד כלל אמרו: מי שנפלו לפניו לייבום שתי אחיות שהיו נשואות לשני אחיו שמתו, אלא שאחת מן האחיות היא קרובה לו ואסורה עליו איסור ערוה מצד אחר, וכגון שהיא חמותו או שהיתה כלתו — הרי זו פטורה מייבום, והאחרת, \u0003אחותה שהיא יבמתה\u0004 (גיסתה) — \u0003חולצת או מתייבמת.\u0004 ואין דינן כשתי אחיות שנפלו כאחת לייבום שהרי אחת מהן כלל לא נפלה לפניו — משום איסור ערוה.","ומסבירים: \u0003איסור מצוה\u0004 הוא \u0003שניות מדברי סופרים,\u0004 שחכמים גזרו איסור נישואין לגבי כמה נשים שאינן קרובות עד כדי שתהיינה אסורות מן התורה, ובכל זאת אסרו אותן כקרובות. \u0003איסור קדושה\u0004 מהו — \u0003אלמנה לכהן גדול, גרושה\u0004 או \u0003חלוצה לכהן הדיוט, ממזרת\u0004 או \u0003נתינה\u0004 (בת מבנות הגבעונים) \u0003לישראל, ו\u0004כן \u0003בת ישראל לנתין וממזר.\u0004","שואלים: \u0003כלל\u0004 זה שאמרו ביבמה — \u0003לאתויי מאי\u0004 \u0005[להביא,\u0006 להוסיף, \u0005את מה]?\u0006 שהרי לכאורה כבר נמנו ונתפרטו בפרק ראשון כל המקרים של איסור ערוה. \u0003אמר רפרם בר פפא: לאתויי\u0004 \u0005[להביא,\u0006 להוסיף\u0005]\u0006 \u0003צרת אילונית.\u0004 כלומר, לא רק אילונית עצמה אינה מתייבמת (מטעם אחר, לפי שאינה ראויה ללדת ואין בייבומה משום הקמת שם לאחיו), אלא גם צרתה פטורה, \u0003וכדרב אסי\u0004 שאסר צרת אילונית, משום שהאילונית אסורה עליו כאשת אח (שהרי לא הותרה בייבום) ולכן צרתה היא צרת ערוה.","\u0003ואיכא דאמרי\u0004 \u0005[ויש שאומרים]\u0006 את דברי רפרם בר פפא אלה באופן אחר לגמרי: שנינו במשנה כי \u0003כל שאיסורה איסור ערוה\u0004 לא חולצת ולא מתייבמת, ונדייק: דווקא זו \u0003הוא דאסירא\u0004 \u0005[היא שאסורה]\u0006 \u0003צרתה, הא\u0004 \u0005[הרי]\u0006 אם \u0003לא\u0004 היה \u0003איסורה איסור ערוה\u0004 אלא נאסרה מטעם אחר — \u0003צרתה לא אסירא\u0004 \u0005[אסורה],\u0006 ו\u0003למעוטי מאי\u0004 \u0005[למעט\u0006 את \u0005מה]\u0006 בא הדבר — \u0003אמר רפרם: למעוטי\u0004 \u0005[למעט]\u0006 \u0003צרת אילונית, ו\u0004אם כן הרי זה ש\u0003לא כ\u0004שיטת \u0003רב אסי.\u0004","נאמר במשנה כי \u0003אחותה שהיא יבמתה\u0004 חולצת או מתייבמת. ומבררים: \u0003אחותה דמאן\u0004 \u0005[של מי]?\u0006 \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 אחותה של זו שהיא אסורה עליו \u0003איסור מצוה,\u0004 אולם \u0003כיון דמדאורייתא רמיא קמיה\u0004 \u0005[שמן התורה\u0006 היא \u0005מוטלת לפניו]\u0006 לייבום, שאין איסור מן התורה לייבם אותה שאיננה ערוה, ולפי התורה שתי האחיות נופלות לייבום כאחת, ושתיהן זקוקות לו לייבום, ונמצא ש\u0003פגע באחות זקוקתו,\u0004 וכבר אמרנו שאת אחות זקוקתו איננו יכול לייבם! \u0003אלא,\u0004 יש לומר שהכוונה היא \u0003אחותה\u0004 של זו שאסורה עליו \u0003איסור ערוה\u0004 וכיון שאת הערוה לא יכול הוא לייבם, אין אחותה נחשבת לאחות זקוקתו, ויכול ליבמה.","שנינו במשנה כי \u0003\"איסור מצוה\"\u0004 הכוונה ל\u0003שניות.\u0004 ושואלים: \u0003אמאי קרי ליה\u0004 \u0005[מדוע קורא לו]\u0006 \u0003\"איסור מצוה\",\u0004 מה הטעם ללשון זו? \u0003אמר אביי:\u0004 הכוונה היא משום ש\u0003מצוה לשמוע דברי חכמים,\u0004 ואלה אינן אסורות אלא מדברי חכמים.","שנינו במשנה כי \u0003\"איסור קדושה\"\u0004 הוא \u0003אלמנה לכהן גדול גרושה וחלוצה לכהן הדיוט.\u0004 ושואלים: \u0003ואמאי קרי להו\u0004 \u0005[ומדוע קורא להם]\u0006 \u0003\"איסור קדושה\" — דכתיב\u0004 \u0005[שנאמר]\u0006 בענין זה: \u0003\"קדשים יהיו לאלהיהם\u0004 ולא יחללו שם אלהיהם כי את אישי ה' לחם אלהיהם הם מקריבים והיו קודש. אשה זונה וחללה לא יקחו ואשה גרושה מאישה לא יקחו כי קדוש הוא לאלהיו\u0003\"\u0004 (ויקרא כא, ו-ז).","\u0003תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005]:\u0006 \u0003ר' יהודה מחליף\u0004 את המונחים: \u0003\"איסור מצוה\"\u0004 הוא \u0003אלמנה לכהן גדול,\u0004 וכן \u0003גרושה\u0004 או \u0003חלוצה לכהן הדיוט. ואמאי קרי ליה\u0004 \u0005[ומדוע קורא לו]\u0006 \u0003\"איסור מצוה\" — דכתיב\u0004 \u0005[שנאמר]\u0006 בסוף ספר ויקרא בסיכום כל הדברים האמורים בו \u0003\"אלה המצות\"\u0004 (שם כז, לד).","ו\u0003\"איסור קדושה\"\u0004 לדעתו אלה \u0003שניות\u0004 האסורות \u0003מדברי סופרים, ואמאי קרי ליה\u0004 \u0005[ומדוע קורא לזה]\u0006 \u0003\"איסור קדושה\"? אמר אביי:\u0004 שכן \u0003כל המקיים דברי חכמים נקרא קדוש. אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבא:\u0004 לשון זו אינה מדוייקת, משום שלפי זה יצא ש\u0003כל שאינו מקיים דברי חכמים — קדוש הוא דלא מיקרי\u0004 \u0005[שאינו נקרא],\u0006 \u0003רשע נמי לא מיקרי\u0004 \u0005[גם כן איננו נקרא],\u0006 והרי אנו יודעים שהעובר על דברי חכמים נקרא רשע! \u0003אלא אמר רבא:\u0004 הטעם שקוראים לזה \"איסור קדושה\" הוא משום ש\"קדושה\" משמעה הפרשה והבדלה, ולענין זה \u0003קדש עצמך\u0004 והיזהר גם \u0003ב\u0004דבר שמן התורה הוא \u0003מותר לך,\u0004 כדי שלא תבוא להיכשל בסופו של דבר בערוה מן התורה.","שנינו במשנה בין השאר ש\u0003אלמנה לכהן גדול\u0004 שהיא לשיטת המשנה \"איסור קדושה\", חולצת ולא מתייבמת. ומעירים: \u0003קפסיק ותני\u0004 \u0005[פסק ושנה]\u0006 בהכללה, שאלמנה לכהן גדול אינה מתייבמת, \u0003לא שנא\u0004 \u0005[אינו שונה]\u0006 אם היתה אלמנה \u0003מן הנשואין ולא שנא\u0004 \u0005[ואינו שונה]\u0006 אם היתה אלמנה \u0003מן האירוסין\u0004 בלבד.","ומעתה, \u0003בשלמא\u0004 \u0005[נניח]\u0006 כשהיא אלמנה \u0003מן הנשואין,\u0004 הרי אסורה היא על הכהן הגדול גם משום מצות \u0003עשה\u0004 של \"והוא אשה בבתוליה יקח\" (שם כא, יג), \u0003ו\u0004מצות \u0003לא תעשה\u0004 של \"אלמנה וגרושה... לא יקח\" (שם יד) \u0003ואין עשה\u0004 של ייבום \u0003דוחה\u0004 את \u0003לא תעשה\u0004 של אלמנה \u0003ועשה\u0004 של בתולה. \u0003אלא,\u0004 אם היתה אלמנה \u0003מן האירוסין,\u0004 אם כן \u0003לא תעשה גרידא\u0004 \u0005[בלבד]\u0006 \u0003הוא,\u0004 שעדיין בתולה היא, ומדוע לא נאמר כי \u0003יבא עשה\u0004 של ייבום \u0003וידחה\u0004 את \u0003לא תעשה\u0004 של אלמנה!","\u0003אמר רב גידל אמר רב, אמר קרא\u0004 \u0005[הכתוב]:\u0006 \u0003\"ועלתה יבמתו השערה\"\u0004 (דברים כה, ז), \u0003שאין תלמוד לומר,\u0004 שאין למדים דבר מן המלה \u0003\"יבמתו\",\u0004 שהרי בה מדובר, ו\u0003מה תלמוד לומר \"יבמתו\",\u0004 להדגיש: יבמתו שלו, ולומר כי \u0003יש לך\u0004 גם \u0003יבמה אחת שעולה לחליצה ואינה עולה לייבום,\u0004 שבה אין הדבר תלוי בהחלטתו כלל, \u0003ואיזו זו —\u0004 זו שהיא עליו \u0003חייבי לאוין.\u0004 שהנשים שאסור לשאתן, משום שיש מצות לא תעשה על כך, כולן חולצות ואין בהן ייבום.","ושואלים: \u0003ואימא\u0004 \u0005[ואמור]\u0006 שמדובר כאן גם ב\u0003חייבי כריתות,\u0004 שאף אלה, עם שאינם רשאים לייבם אותן, אבל הם צריכים לחלוץ להן! ומשיבים: \u0003אמר קרא\u0004 \u0005[הכתוב]:\u0006 \u0003\"ואם לא יחפץ האיש לקחת\u0004 את יבמתו\u0003\"\u0004 (שם), לומר: \u0003הא\u0004 \u0005[הרי]\u0006 אם \u0003חפץ — מייבם,\u0004 כלומר כאשר הדבר תלוי ברצונו. ולפיכך, \u0003כל העולה לייבום\u0004 כלומר שהיתה יכולה להגיע לידי ייבום — \u0003עולה\u0004 גם \u0003לחליצה, וכל שאין עולה לייבום\u0004 — גם \u0003אינו עולה לחליצה\u0004 ואין צריך כלל לחלוץ לה, וכיון שחייבי כריתות אינם יכולים לייבם בשום מקרה, אף אינם צריכים לחלוץ.","ושואלים: \u0003אי הכי\u0004 \u0005[אם כך]\u0006 \u0003חייבי לאוין נמי\u0004 \u0005[גם כן]\u0006 נאמר שאין צריך לחלוץ להן כיון שאינו יכול לייבמן! ומשיבים: \u0003הא רבי רחמנא\u0004 \u0005[הרי רבתה התורה]\u0006 \u0003\"יבמתו\"\u0004 לומר שיש יבמה כזו שעולה לחליצה בלבד ולא לייבום. ושואלים: \u0003ומה ראית\u0004 לומר שהריבוי בא לחייבי לאווים ולא לחייבי כריתות?"],["\u0003מסתברא\u0004 \u0005[מסתבר]\u0006 לומר כך, כי \u0003חייבי לאוין תפסי בהו\u0004 \u0005[תופסים בהם]\u0006 \u0003קדושין,\u0004 שאם מקדש אדם אשה שאסורה עליו באיסור לא תעשה בלבד, למרות שעבר עבירה — הקידושין תופסים ואינו יכול לפוטרה בלא גט, ולכן גם זקוקה לחליצה, ואילו \u0003חייבי כריתות לא תפסי בהו\u0004 \u0005[אין תופסים בהם]\u0006 \u0003קדושין\u0004 כלל ולכן הופקעו לגמרי מדין ייבום וחליצה.","\u0003מתיב\u0004 \u0005[מקשה]\u0006 \u0003רבא\u0004 על דברי רב: שנינו, \u0003איסור מצוה ואיסור קדושה,\u0004 אם \u0003בא עליה או חלץ לה — נפטרה צרתה,\u0004 אף שאסור לו לבא עליה. \u0003ואי סלקא דעתך\u0004 \u0005[ואם עולה על דעתך]\u0006 לומר כפי שאמר רב ש\u0003חייבי לאוין מדאורייתא\u0004 \u0005[מ\u0006דין \u0005תורה]\u0006 \u0003לחליצה רמיא\u0004 \u0005[\u0006היא \u0005מוטלת],\u0006 ו\u0003לייבום לא רמיא\u0004 \u0005[אינה מוטלת\u0006 לפניו\u0005],\u0006 אם כן, \u0003כי\u0004 \u0005[כאשר]\u0006 \u0003בא עליה — אמאי\u0004 \u0005[מדוע]\u0006 \u0003נפטרה צרתה?\u0004 שהרי לפי זה ביאתה איננה מצוה מן התורה, וממילא איננה יכולה לפטור!","\u0003הוא\u0004 עצמו, רבא, \u0003מותיב לה\u0004 \u0005[\u0006היה \u0005מקשה\u0006 \u0005אותה,\u0006 את הקושיה הזו\u0005]\u0006 \u0003והוא\u0004 עצמו \u0003מפרק לה\u0004 \u0005[פתר אותה]:\u0006 \u0003לצדדין קתני,\u0004 שמה שנאמר בברייתא איננו עוסק באותם מקרים, אלא יש בו צדדים שונים. \u0003בא עליה\u0004 — כוונתו על \u0003איסור מצוה,\u0004 שאם בא על יבמה שאסורה עליו רק משום איסור מצוה, כלומר, מדברי סופרים בלבד, כיון שמן התורה היה עליו גם לייבם אותה, לכן, אם בא עליה, אף שעבר על דברי חכמים, מכל מקום המצוה מן התורה נתקיימה בכך, ולכן נפטרה צרתה. ומה שנאמר \u0003חלץ לה\u0004 — הוא על זו שאסורה \u0003איסור קדושה,\u0004 שמן התורה בחייבי לאוין אין חובת ייבום עליו, רק חובת חליצה.","ומכל מקום \u0003מתיב\u0004 \u0005[מקשה]\u0006 \u0003רבא\u0004 ממה ששנינו בתוספתא: \u0003פצוע דכא\u0004 (מי שנפצעו האשכים שלו), או \u0003כרות שפכה\u0004 (מי שנכרת חלק מאבר המין שלו), \u0003סריס אדם\u0004 (מי שסורס בידי אדם ואיננו סריס מיום היוולדו או מחמת מחלה), או \u0003הזקן,\u0004 שכל אלה אינם יכולים להוליד — אחיהם, \u0003או חולצין או מייבמין,\u0004 ועצם מצות הייבום חלה עליהם ולגביהם. \u0003כיצד?\u0004 אם נישאו אלה ואחר כך \u0003מתו\u0004 בלא בנים, \u0003ולהם אחים ולהם נשים, ועמדו אחין ועשו מאמר בנשותיהן\u0004 של האחים שמתו, או \u0003נתנו\u0004 להן \u0003גט,\u0004 או \u0003חלצו\u0004 להן — \u0003מה שעשו עשו.\u0004 כלומר, המעשה שעשו יש לו תוקף, ושוב אינם יכולים לכונסן, לא הם עצמם ולא אחיהם. \u0003ואם בעלו\u0004 את הנשים של אלה שלא יכלו להוליד — \u0003קנו\u0004 האחים את הנשים בבעילה זו כדין ייבום,","וכן להיפך, אם \u0003מתו אחים\u0004 (שהיו אנשים המסוגלים להוליד), בלא בנים \u0003ועמדו הם,\u0004 אותם שאינם יכולים להוליד, \u0003ועשו מאמר בנשותיהן\u0004 של האחים הללו, או \u0003נתנו\u0004 להן \u0003גט או שחלצו — מה שעשו עשו,\u0004 שיש לכך תוקף. \u0003ואם בעלו\u0004 אלה את הנשים — \u0003קנו\u0004 בבעילה זו, \u0003ו\u0004אולם \u0003אסור\u0004 להם \u0003לקיימן\u0004 ולחיות עמן, \u0003משום שנאמר: \"לא יבא פצוע דכה\u0004 וכרות שפכה בקהל ה'\u0003\"\u0004 (דברים כג, ב), שאסורים לשאת אשה מישראל. ומעתה נשאל: \u0003ואי סלקא דעתך\u0004 \u0005[ואם עולה על דעתך]\u0006 לומר כדברי רב, ש\u0003חייבי לאוין מדאורייתא\u0004 \u0005[מן התורה]\u0006 \u0003לחליצה רמיא\u0004 \u0005[\u0006היא \u0005מוטלת,\u0006 עומדת\u0005],\u0006 \u0003לייבום לא רמיא\u0004 \u0005[אינה מוטלת,\u0006 עומדת\u0005],\u0006 אם כן, \u0003אם בעלו — אמאי\u0004 \u0005[מדוע]\u0006 \u0003קנו?\u0004 שהרי אין בבעילתם צד מצוה!","\u0003אלא\u0004 יש לדחות מה שאמר רב, ולכן \u0003אמר רבא:\u0004 חייבי לאוין אכן עומדות לייבום ולכן אם בעלו, קנו, ומה שהוקשה לך באלמנה מן האירוסין שנפלה לפני כהן גדול שיבוא עשה וידחה את לא תעשה ותתייבם, ומדוע איננו מייבם — יש לומר ש\u0003אלמנה מן האירוסין נמי\u0004 \u0005[גם כן]\u0006 \u0003עשה ולא תעשה הוא.\u0004 והיכן נאמרה מצות עשה של קדושה לענין כל איסורי הכהונה — \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"קדשים יהיו לאלהיהם\"\u0004 (ויקרא כא, ו), הרי שבאיסורי הכהונה יש לא רק משום לא תעשה בלבד, אלא גם מצות עשה, וכאמור, אין עשה דוחה לא תעשה ועשה.","ושואלים: אמנם, דבר זה פותר את השאלה לגבי איסורי הכהנים, אולם \u0003ממזרת ונתינה\u0004 שאסורות איסור קדושה לישראל — \u0003מאי איכא למימר\u0004 \u0005[מה יש לומר]\u0006 בהן? והרי גם הן אינן מתייבמות למרות שיש עשה של ייבום שהיה צריך לדחות את הלאו שבהן! ומשיבים: \u0003כתיב\u0004 \u0005[נאמר]\u0006 על כל המצוות \u0003\"והתקדשתם\u0004 והייתם קדושים\u0003\"\u0004 (שם יא, מד), משמע שנוסף ללאו יש גם מצות עשה של קדושה.","ומקשים: \u0003אי הכי\u0004 \u0005[אם כך]\u0006 \u0003כל התורה כולה נמי\u0004 \u0005[גם כן]\u0006 כל מצוות לא תעשה שבתורה \u0003עשה ולא תעשה הוא, דכתיב\u0004 \u0005[ש\u0006הרי \u0005נאמר]\u0006 \u0003\"והתקדשתם\"\u0004 (שם)! \u0003אלא אמר רבא,\u0004 יש לדחות טעם זה, והטעם הוא: מעיקר הדין באמת יש כאן מצות ייבום, אלא \u0003גזירה אלמנה מן האירוסין אטו\u0004 \u0005[משום]\u0006 \u0003אלמנה מן הנשואין.\u0004","ושואלים: \u0003ממזרת ונתינה מאי איכא למימר\u0004 \u0005[מה יש לומר],\u0006 שהרי כאן אין מקום לגזירה משום אשה אחרת! ומשיבים: שם יש לומר שגזרו \u0003גזירה\u0004 לאסור ביאת ממזרת \u0003במקום מצוה, אטו\u0004 \u0005[משום]\u0006 \u0003שלא במקום מצוה,\u0004 שלא יבואו לומר שממזרת מותרת, שהרי פלוני ייבם ממזרת.","ושואלים: \u0003אלא מעתה\u0004 שאנחנו אוסרים את הייבום שמא תתחלף באשה אחרת, \u0003אשת אחיו מאביו לא תתייבם\u0004 למרות שהתורה התירה זאת, ונאמר שתחלוץ תמיד, \u0003גזירה משום אשת אחיו מאמו,\u0004 שאשת אחיו מאמו אסורה משום אשת אח ואין לה היתר כלל! ומשיבים: \u0003ייבום בנחלה תלא רחמנא\u0004 \u0005[תלתה התורה]\u0006 ודבר זה \u0003מידע ידיע\u0004 \u0005[ידוע]\u0006 שהוא רק בקרובים מן האב ולא יטעו איפוא בכך.","ומקשים עוד: \u0003אשה שאין לה בנים,\u0004 זו שמן הדין חל עליה מצות ייבום \u0003לא תתייבם, גזירה משום אשה\u0004 (אשת אח) \u0003שיש לה בנים!\u0004 ומשיבים: \u0003בבנים תלא רחמנא\u0004 \u0005[תלתה התורה]\u0006 ודבר זה \u0003מידע ידיע\u0004 \u0005[ידוע]\u0006 לרבים שמטרת הייבום הוא להקים שם לאחיו, ואין ייבום אלא כשאין בנים, ולא יבואו לטעות.","ומקשים עוד: \u0003אשת אחיו שהיה בעולמו לא תתייבם, גזירה משום אשת אחיו שלא היה בעולמו!\u0004 ומשיבים: \u0003בישיבה\u0004 יחד של האחים, \u0003תלא רחמנא\u0004 \u0005[תלתה\u0006 זאת \u0005התורה]\u0006 ודבר זה \u0003מידע ידיע\u0004 \u0005[ידוע]\u0006 משום שהוא מפורש בכתוב.","ומקשים עוד: \u0003כל הנשים לא תתייבמנה, גזירה משום אילונית,\u0004 שכיון שאיילונית איננה מתייבמת, נגזור איפוא שלא לייבם גם נשים אחרות! ומשיבים: האיילונית \u0003לא שכיחא\u0004 \u0005[אינה מצויה]\u0006 ואין גוזרים גזירה משום דבר שאינו מצוי. ושואלים: אם כן, הלא \u0003ממזרת ונתינה נמי לא שכיחא\u0004 \u0005[גם כן אינה מצויה],\u0006 ואף אם יתירו בממזרת במקום מצוה (בייבום), אין לחשוש שבשל כך יבואו להתיר אף שלא במקום מצווה, כיון שאין הדבר מצוי כל כך!","\u0003אלא אמר רבא\u0004 יש לדחות את התירוץ הקודם ולומר טעם אחר: \u0003גזירה ביאה ראשונה אטו\u0004 \u0005[משום]\u0006 \u0003ביאה שניה.\u0004 שאמנם בפעם הראשונה הבא על היבמה ודאי יש בכך משום מצות עשה, ומצות עשה זו כשלעצמה היתה דוחה את לא תעשה, אולם לאחר מכן בטילה מצות העשה שבדבר, שכן המצוה עצמה התקיימה עם הביאה הראשונה, ומאז היא נחשבת כאשה רגילה, ואסור לו לבוא עליה, שאין כאן עוד מצות עשה, אבל מצות לא תעשה לא בטילה. ולכן משום איסור הביאה השניה גזרו גם שלא יבוא עליה ביאה ראשונה. ולעצם חובת הייבום יש תיקון בחליצה.","ומעירים, \u0003תניא נמי הכי\u0004 \u0005[שנויה\u0006 ברייתא \u0005גם כן כך]\u0006 שרומזת לפתרון זה: \u0003אם\u0004 היבמים שאסור להם באיסור לאו לשאת את היבמות \u0003בעלו\u0004 אותן — \u0003קנו בביאה ראשונה, ואסור לקיימן בביאה שניה.\u0004","\u0003הדר\u0004 \u0005[חזר]\u0006 ו\u0003אמר רבא ואיתימא\u0004 \u0005[ויש אומרים]\u0006 שאמר זאת \u0003רב אשי: לאו מילתא היא דאמרי\u0004 \u0005[אין הוא דבר\u0006 של ממש מה \u0005שאמרתי]\u0006 טעם זה של גזירה על ביאה ראשונה משום ביאה שניה, אלא הטעם הוא יותר פשוט, ש\u0003אמר ריש לקיש\u0004 לגבי אותו ענין: \u0003כל מקום שאתה מוצא עשה ולא תעשה\u0004 לגבי אותו ענין, שמצד אחד יש מצות עשה לעשותו, ויש גם מצות לא תעשה, האוסרת לעשותו, \u0003אם אתה יכול\u0004 למצוא דין המאפשר \u0003לקיים\u0004 את \u0003שניהם\u0004 יחד ולא לעבור על איסור — \u0003מוטב, ואם לאו,\u0004 שאין אפשרות לקיים שניהם, \u0003יבא עשה וידחה את לא תעשה. הכא נמי\u0004 \u0005[כאן גם כן],\u0006 בדין של ייבום, הרי \u0003אפשר בחליצה,\u0004 שבכך הוא \u0003מקיים\u0004 בה \u0003עשה\u0004 של ייבום \u0003ו\u0004לא עובר על \u0003לא תעשה\u0004 של האיסור לשאת נשים אלה.","\u0003מיתיבי\u0004 \u0005[מקשים]\u0006 גם על דברי רבא האחרונים הללו, ממה ששנינו בברייתא: \u0003ואם בעלו — קנו,\u0004 משמע, שגם במקום שאפשר לקיים המצוה על ידי חליצה, אם בכל זאת ייבם דחה העשה את לא תעשה, שהרי אומרים שנתקיימה בפועל (\"קנו\") מצות ייבום. ומסכמים: אכן \u0003תיובתא\u0004 \u0005[קושיה חזקה]\u0006 היא ונדחו דברי רבא אלה, ויש לקבל את תירוצו הקודם, שנאסר הדבר משום גזירה.","באותו ענין עצמו \u0003איתמר\u0004 \u0005[נאמר]\u0006 שנחלקו אמוראים בשאלה של \u0003ביאת כהן גדול באלמנה\u0004 שהיתה יבמתו: \u0003ר' יוחנן ור' אלעזר, חד\u0004 \u0005[אחד\u0006 מהם\u0005]\u0006 \u0003אמר:\u0004 ביאה זו \u0003אינה פוטרת צרתה,\u0004 כיון שביאה זו אינה ראויה, \u0003וחד\u0004 \u0005[ואחד\u0006 מהם\u0005]\u0006 \u0003אמר: פוטרת צרתה,\u0004 שאף שאסור היה לו לעשות זאת לכתחילה, מכל מקום יש למעשה תוקף של ייבום גמור, וממילא נפטרה על ידו הצרה."],["\u0003באלמנה מן הנשואין — כולי עלמא לא פליגי דלא פטרה\u0004 \u0005[הכל אינם חלוקים שאינה פוטרת],\u0006 כיון ש\u0003אין עשה דוחה\u0004 את \u0003לא תעשה ועשה\u0004, ולא הועילה ביאתה כלום, ולכך אין בה כדי לפסול את צרתה. \u0003כי פליגי\u0004 \u0005[כאשר נחלקו],\u0006 הרי זה \u0003באלמנה מן הארוסין; מאן דאמר\u0004 \u0005[מי שאומר]\u0006 שביאתה \u0003פוטרת\u0004 את צרתה, סובר: \u0003אתי\u0004 \u0005[באה]\u0006 מצוה \u0003עשה\u0004 של ייבום \u0003ודחי\u0004 \u0005[ודוחה]\u0006 \u0003את לא תעשה\u0004 של אלמנה. \u0003ומאן דאמר\u0004 \u0005[ומי שאומר]\u0006 שביאתה \u0003אינה פוטרת,\u0004 לדעתו \u0003לא אתי\u0004 \u0005[באה]\u0006 מצות \u0003עשה ודחי\u0004 \u0005[ודוחה]\u0006 \u0003את לא תעשה, כיון\u0004 ש\u0003אפשר בחליצה.\u0004","\u0003מיתיבי\u0004 \u0005[מקשים]\u0006 על שיטת האומר שאינה פוטרת, ממה ששנינו בברייתא: \u0003ואם בעלו — קנו,\u0004 משמע שמצות הייבום חלה ויש לה תוקף אף שאסור מלכתחילה לעשותה, ואם כן תפטור גם את צרתה! ומסכמים: אכן \u0003תיובתא\u0004 \u0005[קושיה חמורה]\u0006 היא, ונדחו הדברים.","ושואלים: \u0003לימא תיהוי נמי תיובתא\u0004 \u0005[\u0006האם \u0005נאמר\u0006 ש\u0005תהא\u0006 זו \u0005גם כן קושיה]\u0006 ודחיה לכלל שקבע \u0003ריש לקיש,\u0004 שכל מקום שאתה מוצא עשה ולא תעשה, אם אתה יכול לקיים שניהם — מוטב, ואם לא — יבוא עשה וידחה את לא תעשה?! ומשיבים: \u0003אמר לך\u0004 \u0005[\u0006יכול היה \u0005לומר לך]\u0006 \u0003ריש לקיש: כי אמינא אנא\u0004 \u0005[כאשר אומר אני]\u0006 שבמקום שאפשר לקיים את עשה ולא תעשה מקיימים את שניהם ואין דוחים — הרי זה רק \u0003היכא דמקיימי\u0004 \u0005[במקום שמקיימים]\u0006 \u0003מצוה\u0004 כתיקונה, \u0003אבל הכא\u0004 \u0005[כאן],\u0006 \u0003חליצה במקום\u0004 שצריך היה להיות \u0003ייבום — לאו מצוה היא\u0004 כל כך כמו ייבום.","\u0003אמר רבא: רמז ל\u0004איסור \u0003שניות מן התורה מנין — שנאמר\u0004 בסוף פרשת העריות: \u0003\"כי את כל התועבת האל עשו אנשי הארץ\"\u0004 (ויקרא יח, כז), \u0003\"האל\"\u0004 מתפרש כאן במובן: \u0003\"קשות\",\u0004 העבירות החמורות, \u0003מכלל\u0004 הדברים אתה למד \u0003דאיכא\u0004 \u0005[שיש]\u0006 גם עבירות מסוג \u0003\"רכות\", ומאי נינהו\u0004 \u0005[ומה הן]\u0006 הרכות — \u0003שניות.\u0004","ושואלים: \u0003ומאי משמע\u0004 \u0005[ומה המשמעות],\u0006 כיצד מובן שלשון \u0003\"האל\" לישנא\u0004 \u0005[לשון]\u0006 המורה על דבר \u0003קשה הוא — דכתיב\u0004 \u0005[שנאמר]\u0006 \u0003\"ואת אילי הארץ לקח\"\u0004 (יחזקאל יז, יג), כלומר, החזקים והתקיפים.","ומציעים: \u0003לימא פליגא\u0004 \u0005[\u0006האם \u0005לומר\u0006 שאימרה זו \u0005חלוקה]\u0006 על דברי \u0003ר' לוי,\u0004 ש\u0003אמר ר' לוי: קשה עונשין של מדות\u0004 שאדם מרמה בהן, \u0003יותר מעונשין של עריות, שזה\u0004 בעריות \u0003נאמר בהן\u0004 רק \u0003\"אל\", וזה\u0004 המידות \u0003נאמר בהן \"אלה\"\u0004 (\"כי תועבת ה' אלוהיך כל עושה אלה כל עושה עול\". דברים כה, טז), משמע ש\"אלה\" הוא הלשון הקשה! ומשיבים: אין זו קושיה, \u0003\"אל\" קשה, ו\"אלה\" קשה מ\"אל\".\u0004","ושואלים: ל\u0003גבי\u0004 \u0005[אצל]\u0006 \u0003עריות נמי הא כתיב\u0004 \u0005[גם כן הרי נאמר]\u0006 \u0003\"אלה\"\u0004 (\"כי כל אשר יעשה מכל התועבות האלה ונכרתו הנפשות העושות\". ויקרא יח, כט)! ומשיבים: \u0003ההוא,\u0004 הביטוי \"האלה\" האמור בדיני עריות, לא להדגיש את חומרתן בא, אלא כדי לצמצם ולהדגיש: על אלה ולא על אחרות, \u0003למעוטי\u0004 \u0005[למעט]\u0006 את מי שמרמה ב\u0003מדות מ\u0004עונש \u0003כרת.\u0004","ושואלים: \u0003אלא,\u0004 אם כן, שאין בהן עונש חמור זה \u0003מאי חומרייהו\u0004 \u0005[מה חומרתן]\u0006 של מידות? ומשיבים: \u0003הני\u0004 \u0005[אלה,\u0006 עריות\u0005],\u0006 הבא עליהם \u0003אפשר\u0004 שיחזור \u0003בתשובה,\u0004 אולם \u0003הני\u0004 \u0005[אלה]\u0006 שמרמה את הרבים במידות — \u0003לא אפשר בתשובה,\u0004 שהרי אינו יודע למי יחזיר.","\u0003רב יהודה אמר\u0004 רמז לשניות \u0003מהכא\u0004 \u0005[מכאן],\u0006 ממה שנאמר בשלמה המלך: \u0003\"ואזן וחקר תקן משלים הרבה\"\u0004 (קהלת יב, ט), \u0003ואמר עולא אמר ר' אלעזר: קודם שבא שלמה היתה תורה דומה לכפיפה\u0004 (סל) \u0003שאין לה אזנים\u0004 (ידיות), \u0003עד שבא שלמה ועשה לה אזנים\u0004 (\"אזן\"). וכוונתו, שהוסיף שלמה המלך ותיקן כמה תקנות כדי שיהיו עזר וגדר לדברי התורה עצמם.","\u0003ר' אושעיא אמר מהכא\u0004 \u0005[מכאן]:\u0006 \u0003\"פרעהו אל תעבר בו שטה מעליו ועבר\"\u0004 (משלי ד, טו), כלומר, שצריך להתרחק ולא לעבור בקירבת מקום שיש בו דבר איסור.","\u0003אמר רב אשי: משל\u0004 לדברי \u0003ר' אושעיא למה הדבר דומה — לאדם המשמר פרדס,\u0004 אם הוא \u0003משמרו מבחוץ — כולו משתמר.\u0004 ואם \u0003משמרו מבפנים\u0004 — מה \u0003שלפניו\u0004 במקום שרואה — \u0003משתמר,\u0004 אבל מה \u0003שלאחריו\u0004 — \u0003אינו משתמר.\u0004 ומעירים: \u0003והא\u0004 \u0005[וזו]\u0006 שאמר \u0003רב אשי בדותא\u0004 \u0005[בדיה]\u0006 \u0003היא,\u0004 איננו נכון, ש המשל מכוון. כי \u0003התם\u0004 \u0005[שם]\u0006 במשל, מה \u0003שלפניו מיהא\u0004 \u0005[לפחות]\u0006 \u0003משתמר, הכא, אי לאו\u0004 \u0005[כאן, אם לא]\u0006 איסור ה\u0003שניות, פגע\u0004 \u0005[\u0006היה \u0005פוגע]\u0006 \u0003בערוה גופה\u0004 \u0005[עצמה],\u0006 והשמירה הזו \"מבחוץ\" היא הכרחית ולא רק שמירה מעולה יותר.","\u0003רב כהנא אמר\u0004 רמז לשניות \u0003מהכא\u0004 \u0005[מכאן],\u0006 שנאמר: \u0003\"ושמרתם את משמרתי\u0004 לבלתי עשות מחוקות התועבות\u0003\"\u0004 (ויקרא יח, ל) האמור בסוף דיני עריות. ופירושו: \u0003עשו משמרת\u0004 (שמירה) נוספת \u0003למשמרתי.\u0004","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי לרב יוסף:\u0004 אם מכאן למדים, \u0003הא דאורייתא\u0004 \u0005[זו, מן התורה]\u0006 \u0003היא\u0004 שיש להוסיף משמרת לתורה, ומדוע אנו אומרים שהשניות הן מדברי סופרים? והשיב לו: עצם הדרישה להוסיף משמרת — \u0003דאורייתא\u0004 \u0005[מן התורה],\u0006 \u0003ופירשו רבנן\u0004 (חכמים) כיצד לעשות משמרת זו. והקשה לו: אם כן, הלא \u0003כל התורה נמי\u0004 \u0005[גם כן]\u0006 \u0003פירשו רבנן\u0004 (חכמים)! \u0003אלא\u0004 כך יש לומר: איסור שניות כולו \u0003מדרבנן\u0004 \u0005[מדברי סופרים],\u0006 \u0003וקרא אסמכתא בעלמא\u0004 \u0005[והכתוב\u0006 הוא רק \u0005סמך בלבד]\u0006 ולא מצוה גמורה.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]\u0006 בברייתא: \u0003מה הם שניות\u0004 שאסרו: \u0003אם אמו, ואם אביו, ואשת אבי אביו, ואשת אבי אמו, ואשת אחי האב מן האם\u0004 (שאביו ודודו הם אחים רק מצד האם בלבד), \u0003ואשת אחי האם מן האב, וכלת בנו, וכלת בתו. ומותר אדם באשת חמיו\u0004 אם איננה אם אשתו, \u0003ובאשת חורגו\u0004 אשת בנו החורג, אם מת בן זה או גירש אותה. \u0003ואסור בבת חורגו\u0004 (בנו החורג). \u0003וחורגו\u0004 (בנו החורג) \u0003מותר באשתו ובתו\u0004 שלו.","ומשום גזירות אלה בחורגים מתהווים מצבים תמוהים לכאורה, כגון: \u0003ואשת חורגו אומרת לו,\u0004 לאבי בעלה, \u0003אני מותרת לך, ובתי אסורה לך,\u0004 שהרי היא בת חורגו.","על הנאמר בברייתא תוהים: האם \u0003בת חורגו\u0004 היא מהשניות שהן אסורות מדברי סופרים הלא \u0003דאורייתא\u0004 \u0005[מן התורה]\u0006 \u0003היא\u0004 אסורה, שהרי בת בנו החורג היא בת בן אשתו, ובמפורש נאסרה, \u0003דכתיב\u0004 \u0005[ש\u0006כן \u0005נאמר]:\u0006 \u0003\"את בת בנה ואת בת בתה\u0004 לא תקח\u0003\"\u0004 (ויקרא יח, יז)! ומשיבים: \u0003משום דקבעי למיתני סיפא\u0004 \u0005[משום שרצה לשנות\u0006 ב\u0005סופה]\u0006 של ברייתא זו: \u0003אשת חורגו אומרת לו: אני מותרת לך, ובתי אסורה לך, ואף על גב\u0004 \u0005[ואף על פי]\u0006 ש\u0003\"בתי אסורה לך\" מדאורייתא\u0004 \u0005[מן התורה],\u0006 בכל זאת \u0003בדידי\u0004 \u0005[בי\u0006 עצמי\u0005]\u0006 \u0003לא גזור ביה רבנן\u0004 \u0005[גזרו חכמים],\u0006 לכן \u0003תנא רישא נמי\u0004 \u0005[שנה\u0006 ב\u0005ראשה גם כן]\u0006 \u0003בת חורגו,\u0004 אף על פי שאיננה מן השניות.","ומקשים: \u0003אי הכי\u0004 \u0005[אם כך],\u0006 שרצה לשנות דבר שיש בו חידוש כגון זה, לגבי \u0003אשת חמיו נמי תימא\u0004 \u0005[גם כן תאמר,\u0006 תשנה\u0005]:\u0006 \u0003אני מותרת לך ובתי אסורה לך, דהויא\u0004 \u0005[שהרי היא]\u0006 \u0003אחות אשתו!\u0004 ומשיבים: \u0003הא פסיקא ליה\u0004 \u0005[\u0006דבר \u0005זה פסוק,\u0006 מוחלט, \u0005לו],\u0006 כלומר, לעולם אשת חורגו מותרת ובת חורגו אסורה, אבל \u0003הא\u0004 \u0005[זה]\u0006 שבת אשת חמיו תהיה אסורה — \u0003לא פסיקא ליה\u0004 \u0005[אינו פסוק לו]\u0006 אין דינו קבוע תמיד, שהרי אם תמות אשתו תהיה אחותה מותרת, ולכן ציין אותה במפורש.","\u0003אמר רב,\u0004 שקיבל במסורת כי \u0003ארבע נשים יש להן הפסק.\u0004 כלומר, בארבע נשים שנאסרו משום שניות, אין האיסור הולך ונמשך גם לדורות אחרים, שלמעלה או שלמטה מהן, אלא רק באלה שנמנו במפורש. \u0003נקיט\u0004 \u0005[החזיק]\u0006 \u0003רב בידיה תלת\u0004 \u0005[בידו שלוש]\u0006 מאלה. כלומר, בשלוש מאותן ארבע היה בטוח. והן: \u0003אשת אחי האם מן האב\u0004 שהיא לבדה אסורה, אבל אשת אחי אם אמו מותרת, \u0003ואשת אחי האב מן האם,\u0004 שהיא עצמה שניה ואסורה, אבל אשת אחיו אבי אביו מן האם, מותרת, \u0003וכלתו. וזעירי מוסיף אף אשת אבי אמו. אמר רב נחמן בר יצחק: וסימניך\u0004 \u0005[וסימנך]\u0006 שתזכור מי אמר מה: \u0003דעילאי\u0004 \u0005[שלמעלה,\u0006 הראשונות\u0005],\u0006 הם של \u0003רב\u0004 כי זעירי מוסיף עוד דור אחד, אשת אבי אמו, שרב לא מנה.","ושואלים: \u0003ורב, מאי טעמא לא חשיב ליה\u0004 \u0005[מה טעם לא מנה אותה]\u0006 בין אלה שיש להן הפסק? ומשיבים: לדעתו \u0003מיחלפא ליה\u0004 \u0005[מתחלפת היא],\u0006 שאפשר לטעות ולהחליפה \u0003באשת אבי אביו,\u0004 שאין לה הפסק ואיסור שבה נמשך לדורות אחרים, ולכן לא התירוה.","ושואלים: \u0003וזעירי\u0004 מדוע איננו חושש לכך? ומסבירים: \u0003להתם שכיח ואזיל\u0004 \u0005[לשם\u0006 לבית משפחת אבי אביו הוא \u0005מצוי והולך]\u0006 ולכן גזרו איסור זה שלא יבוא להתגרות בערוה, ואולם \u0003להכא לא שכיח ואזיל\u0004 \u0005[לכאן,\u0006 למשפחת אמו, \u0005אין\u0006 זה \u0005מצוי שילך]\u0006 ולכן הם לא חששו לכך.","בין הנשים שמנה רב כשניות, מצויה גם \u0003כלתו,\u0004"],["\u0003דאורייתא\u0004 \u0005[מן התורה]\u0006 \u0003היא, דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"ערות כלתך לא תגלה\"!\u0004 (ויקרא יח, טו) ומתקנים: \u0003אימא\u0004 \u0005[אמור]\u0006 \u0003כלת בנו.\u0004 ותוהים: \u0003וכלת בנו יש לה הפסק? והא תניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]:\u0006 \u0003כלתו — ערוה\u0004 מן התורה, \u0003כלת בנו — שניה, וכן אתה אומר בבנו, ובן בנו, עד סוף כל הדורות.\u0004 כלומר, שהנשים של כל אחד מבני בניו אסורות לו משום שניות! \u0003אלא אימא\u0004 \u0005[אמור]\u0006 ותקן כך: \u0003כלת בתו.\u0004","ש\u0003אמר רב חסדא: הא מילתא מגברא רבה שמיע לי\u0004 \u0005[דבר זה, מאדם גדול שמעתי],\u0006 \u0003ומנו\u0004 \u0005[ומי הוא]\u0006 אדם גדול זה — \u0003ר' אמי,\u0004 וכך אמר: \u0003לא אסרו כלה אלא מפני כלה.\u0004 ודבר זה שמע רב חסדא בנערותו ולא הבין את טעמו. \u0003ואמרו לי כלדאי\u0004 \u0005[החוזים בכוכבים]:\u0006 \u0003מלפנא הוית\u0004 \u0005[מורה תהיה].\u0006","\u0003אמינא\u0004 \u0005[אמרתי]\u0006 בלבי: \u0003אי גברא רבה הוינא\u0004 \u0005[אם אדם גדול אהיה],\u0006 מורה הוראה לרבים — מן הסתם \u0003אסברא\u0004 \u0005[אסבור,\u0006 אבין\u0005]\u0006 את הדבר הזה \u0003מדעתי, אי מקרי דרדקי הוינא\u0004 \u0005[אם מלמד תינוקות אהיה] —\u0006 \u0003אשיילה מרבנן דאתו לבי כנישתא\u0004 \u0005[אשאל אותה מחכמים הבאים לבית הכנסת]\u0006 ואדע מה פירוש דברי ר' אמי. \u0003השתא סברתה\u0004 \u0005[עכשיו סברתי,\u0006 הבנתי\u0005]\u0006 את המאמר הזה \u0003מדעתי,\u0004 וזו היתה כוונתו של ר' אמי: \u0003לא אסרו כלת בתו אלא משום כלת בנו.\u0004 כיון שעשויים אנשים להחליף ולטעות בין כלות אלה, המצויות לעתים יחד אצל הסב, אבי המשפחה. וכיון שרק משום גזירה היא — כלת בתו נאסרה, אבל לא אסרו את הדורות שלאחר מכן.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי לרבא: אסברה לך\u0004 \u0005[אסביר לך]\u0006 כיצד קורה הדבר שמחליפים בין כלות אלה, \u0003כגון כלתה דבי\u0004 \u0005[הכלות של בית]\u0006 \u0003בר ציתאי\u0004 ששם היו בני הבנים ובני הבנות של אותה משפחה גרים יחד, ואפשר היה להחליף בין הכלות. \u0003רב פפא אמר: כגון כלתה דבי\u0004 \u0005[הכלות של בית]\u0006 \u0003רב פפא בר אבא. רב אשי אמר: כגון כלתה דבי\u0004 \u0005[הכלות של בית]\u0006 \u0003מרי בר איסק,\u0004 שכל אחד הביא דוגמא ממשפחה כזו שהיתה בימיו.","\u0003איבעיא להו\u0004 \u0005[נשאלה להם,\u0006 ללומדים\u0005]\u0006 שאלה זו: \u0003אשת אחי האם מן האם, מהו?\u0004 וצדדי השאלה: \u0003אשת אחי האב מן האם, ואשת אחי האם מן האב, דאיכא\u0004 \u0005[שיש]\u0006 בהן על כל פנים \u0003צד אב, הוא\u0004 ש\u0003גזרו\u0004 בהן \u0003רבנן\u0004 (חכמים) איסור משום אשת אחי אביו מן האב, \u0003אבל היכא דליכא\u0004 \u0005[היכן שאין]\u0006 \u0003צד אב\u0004 כלל \u0003לא גזרו בהו רבנן\u0004 \u0005[בהן חכמים],\u0006 \u0003או דלמא\u0004 \u0005[שמא]\u0006 \u0003לא שנא\u0004 \u0005[אינו שונה]?\u0006","\u0003אמר רב ספרא: היא גופה\u0004 \u0005[עצמה],\u0006 אשת אחי האם מן האב, איסורה הוא משום \u0003גזירה, ואנן ניקום\u0004 \u0005[ואנו נעמוד]\u0006 \u0003ונגזור גזירה לגזירה?! אמר רבא: אטו כולהו לאו\u0004 \u0005[וכי\u0006 כל השניות \u0005כולן לא]\u0006 \u0003גזירה לגזירה נינהו\u0004 הן? הרי \u0003אמו\u0004 היא \u0003ערוה\u0004 מן התורה ולכן גזרו שתהא \u0003אם אמו — שניה,\u0004 ואסורה. \u0003וגזרו על אם אביו משום אם אמו. וטעמא מאי\u0004 \u0005[והטעם מהו]?\u0006 \u0003כולהו \"דבי אימא רבתי\" קרו ליה\u0004 \u0005[\u0006ל\u0005כולן \"בית אמא גדולה\",\u0006 סבתא, \u0005קוראים להן]\u0006 ואנשים עלולים לטעות בהן.","וכך \u0003אשת אביו\u0004 — היא עצמה \u0003ערוה\u0004 מן התורה, \u0003אשת אבי אביו — שניה,\u0004 מדברי סופרים. \u0003וגזרו על אשת אבי אמו משום אשת אבי אביו. וטעמא מאי\u0004 \u0005[ומהו הטעם]?\u0006 — \u0003כולהו \"דבי אבא רבה\" קרו ליה\u0004 \u0005[לכולן \"בית אב גדול\"\u0006 בית הסב \u0005קוראים להן].\u0006","וכן \u0003אשת אחי האב מן האב\u0004 דודתו האמורה בתורה — \u0003ערוה, אשת אחי האב מן האם — שניה, וגזרו על אשת אחי האם מן האב משום אשת אחי האב מן האם, וטעמא מאי\u0004 \u0005[ומהו הטעם]?\u0006 \u0003משום דכולהו \"דבי דודי\" קרי להו\u0004 \u0005[שכולן\u0006 משפחת \u0005\"בית הדוד\" קוראים להן]\u0006 ונימוק זה של גזירה לגזירה אינו תופס, איפוא, בענין זה.","ואם כן \u0003מאי\u0004 \u0005[מה]\u0006 הדין בזה? ומציעים: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע],\u0006 \u0003דכי אתא\u0004 \u0005[שכאשר בא]\u0006 \u0003רב יהודה בר שילא\u0004 מארץ ישראל לבבל, \u0003אמר: אמרי במערבא\u0004 \u0005[אומרים במערב,\u0006 בארץ ישראל\u0005]\u0006 כלל זה: \u0003כל שבנקבה\u0004 קירבה כזו היא \u0003ערוה,\u0004 אם היה זה \u0003בזכר — גזרו על אשתו משום שניה.\u0004","\u0003ואמר רבא: וכללא\u0004 \u0005[ו\u0006כי \u0005כלל\u0006 אמיתי\u0005]\u0006 \u0003הוא\u0004 זה? הלא \u0003חמותו ערוה\u0004 היא, ואילו \u0003אשת חמיו מותרת.\u0004 וכן \u0003בת חמותו ערוה\u0004 (שהיא אחות אשתו), ואילו \u0003אשת בן חמותו מותרת. בת חמיו ערוה,\u0004 ואילו \u0003אשת בן חמיו מותרת. חורגתו\u0004 (בתו החורגת, בת אשתו) \u0003ערוה,\u0004 ואילו \u0003אשת חורגו מותרת. בת חורגתו\u0004 (נכדת אשתו) \u0003ערוה,\u0004 ואילו \u0003אשת בן חורגו מותרת!\u0004","וממשיכים: אם כן, \u0003והא\u0004 \u0005[וזו]\u0006 שאמר \u0003רב יהודה בר שילא לאיתויי מאי\u0004 \u0005[להביא את מה]?\u0006 כיון שהכלל איננו נכון בכל מקרה, מכל מקום ודאי בא ללמוד ממנו הלכה אחת לפחות, \u0003לאו\u0004 \u0005[האם לא]\u0006 \u0003לאיתויי\u0004 \u0005[להביא]\u0006 את \u0003אשת אחי האם מן האם,\u0004 ש\u0003כל שבנקבה ערוה\u0004 (שהרי אחות אמו אסורה עליו) — \u0003בזכר\u0004 (אחי אמא) \u0003גזרו\u0004 על \u0003אשתו משום שניה.\u0004","ושואלים: \u0003מאי שנא הני\u0004 \u0005[\u0006ב\u0005מה שונות אלה],\u0006 אשת חמיו ואשת בן חמותו שהן מותרות \u0003ומאי שנא הא\u0004 \u0005[ו\u0006ב\u0005מה שונה זו]\u0006 אשת אחי האם שהיא אסורה? ומשיבים: \u0003הא בחד קידושין מקרב\u0004 \u0005[זו\u0006 אשת אחי האם \u0005ב\u0006קשר \u0005קידושין אחד מתקרב]\u0006 \u0003לה,\u0004 שהרי אחי אמו קרוב אליו קירבת דם, וכאשר מקדש אשה נחשבת היא כשניה ונעשית כקרובתו, \u0003הני, עד דאיכא תרי קידושין לא מקרב להו\u0004 \u0005[\u0006וכל \u0005אלה\u0006 האחרות שהתרנו, \u0005עד שיש שני\u0006 קשרי \u0005קידושין אינו מתקרב להן],\u0006 כגון אשת חמיו, שיש צורך בקשר נשואין אחד שלו עם אשתו כדי שיהא זה חמיו, וחמיו צריך גם הוא לקדש אשה כדי שתיעשה קרובה לו.","\u0003שלח ליה רב משרשיא מ\u0004המקום \u0003תוסנייא לרב פפי: ילמדנו רבינו, אשת אחי אבי האב, ואחות אבי האב, מהו,\u0004 האם אסורות הן משום שניות? וצדדי השאלה: כיון שדור אחד \u0003מדלמטה ערוה\u0004 היא, שהרי אשת אחי האב ואחות האב אסורות מן התורה — \u0003למעלה\u0004 דור אחד יותר \u0003נמי\u0004 \u0005[גם כן]\u0006 \u0003גזרו ביה\u0004 \u0005[בו]\u0006 חכמים, \u0003או דלמא\u0004 \u0005[שמא],\u0006 \u0003הא אתפליג דרתא\u0004 \u0005[הרי\u0006 כבר \u0005נתחלקו הדורות]\u0006 ואין אלו נחשבות עוד כקרובות שיש בהן איסור.","ומציעים: \u0003תא שמע\u0004 \u0005[בא\u0006 ו\u0005שמע]\u0006 ראיה מאותה ברייתא ששנינו \u0003\"מה הן שניות\", ולא קחשיב להו בהדייהו\u0004 \u0005[ואינו מונה את אלה אתן]!\u0006","ודוחים: \u0003תנא ושייר\u0004 \u0005[שנה ושייר],\u0006 לא מנה שם את כל השניות. ושואלים: \u0003מאי\u0004 \u0005[מה]\u0006 \u0003שייר\u0004 עוד שתוכל לומר \u0003דהאי\u0004 \u0005[ש\u0006את \u0005זו]\u0006 גם \u0003שייר?\u0004 ומשיבים: \u0003שייר\u0004 עוד \u0003שניות\u0004 שמנו \u0003דבי\u0004 \u0005[בבית\u0006 מדרשו\u0005]\u0006 של \u0003ר' חייא\u0004 שיבוארו להלן.","למעשה סיפרו כי \u0003אמימר אכשר\u0004 \u0005[הכשיר]\u0006 והתיר \u0003באשת אחי אבי אביו ובאחות אבי אביו. אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב הלל לרב אשי: לדידי חזיא לי\u0004 \u0005[אני\u0006 עצמי \u0005ראיתי]\u0006 רשימה של \u0003שניות\u0004 שעשה \u0003מר בריה\u0004 \u0005[בנו]\u0006 של \u0003רבנא, וכתיבן שיתסרי לאיסורא\u0004 \u0005[וכתובות\u0006 בה \u0005שש עשרה\u0006 נשים \u0005לאיסור].\u0006 \u0003מאי לאו\u0004 \u0005[האם לא]\u0006 נמנו ברשימה זו \u0003תמני דמתניתא\u0004 \u0005[שמונה של הברייתא]\u0006 ששנינו, \u0003ושית\u0004 \u0005[ושש]\u0006 שנאמרו \u0003דבי\u0004 \u0005[בבית\u0006 מדרשו\u0005]\u0006 של \u0003ר' חייא, והנך תרתי\u0004 \u0005[ואלו השתים]\u0006 שהיה לנו ספק בהן, \u0003הא שיתסרי\u0004 \u0005[\u0006ו\u0005הרי שש עשרה].\u0006","הקשה לו רב אשי: \u0003ולטעמיך שיבסרי הויין\u0004 \u0005[ולטעמך,\u0006 לשיטתך, שאתה מונה גם אלה \u0005שבע עשרה הן],\u0006 \u0003דהא איכא\u0004 \u0005[שהרי יש]\u0006 עוד אחת — אם כן \u0003אשת אחי האם מן האם, דפשטינן לאיסורא\u0004 \u0005[שפתרנו\u0006 את הבעיה בה \u0005לאיסור]\u0006 במאמר הקודם. ואם כן שבע עשרה הן! ודוחים: \u0003הא לא קשיא\u0004 \u0005[זה אינו קשה],\u0006"],["\u0003הנך תרתי דדמיין להדדי\u0004 \u0005[אלה\u0006 ה\u0005שתים,\u0006 אשת אחי אבי האב ואחות אבי האב, \u0005שדומות זו לזו]\u0006 \u0003כחדא חשיב להו\u0004 \u0005[כאחת מונה\u0006 הוא \u0005אותן],\u0006 \u0003והא שיתסרי\u0004 \u0005[והרי שש עשרה].\u0006 והוסיף: \u0003והא\u0004 \u0005[והרי]\u0006 \u0003מכל מקום לדידי חזיין לן דכתיבן לאיסורא\u0004 \u0005[אני\u0006 עצמי \u0005ראיתי אותן\u0006 ש\u0005הן כתובות לאיסור]!\u0006 \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003וליטעמיך\u0004 \u0005[ולטעמך,\u0006 לשיטתך\u0005],\u0006 \u0003אי הוה כתיב להיתירא, מי הוות סמכת עלייהו\u0004 \u0005[אם היה כתוב\u0006 ברשימה ההיא \u0005להתיר, האם היית סומך עליהן]?\u0006 ש\u0003מר בריה\u0004 \u0005[בנו]\u0006 של \u0003רבנא מי חתים עלייהו\u0004 \u0005[האם חתום עליהן]?\u0006 שהרי היתה זו רק רשימה כתובה שייחסו לו. \u0003השתא נמי דכתיב לאיסורא\u0004 \u0005[עכשיו גם כן שכתוב לאיסור]\u0006 \u0003לאו\u0004 \u0005[לא]\u0006 \u0003מר בריה\u0004 \u0005[בנו]\u0006 של \u0003רבנא חתים עלייהו\u0004 \u0005[חתום עליהם]\u0006 ואין לסמוך על כך.","\u0003תני דבי\u0004 \u0005[שנה\u0006 החכם \u0005בבית\u0006 מדרשו\u0005]\u0006 של \u0003ר' חייא:\u0004 דור \u0003שלישי שבבנו ושבבתו,\u0004 כלומר, בת בן בנו, ובת בת בנו, וכן בנכדי בתו, \u0003ו\u0004דור שלישי \u0003שבבן אשתו ושבבת אשתו\u0004 — הרי זו אסורה משום \u0003שניה\u0004, וכן דור \u0003רביעי שבחמיו ושבחמותו\u0004 אם אמו של חמיו, ואם אמה של חמותו — הרי הן אסורות משום \u0003שניה.\u0004 שאיסור אשה ואמה חל מדברי סופרים גם על אם אם אמה, ארבעה דורות.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבינא לרב אשי: מאי שנא\u0004 \u0005[מה שונה]\u0006 בדרך מנייתו את הדורות \u0003למעלה\u0004 (בחמיו וחמותו) \u0003דקחשיב לה\u0004 \u0005[ש\u0006הוא \u0005מונה אותה]\u0006 את \u0003אשתו\u0004 כאחד הדורות הללו (אשתו, אמה, אם אמה, אם אם אמה) \u0003ומאי שנא\u0004 \u0005[ו\u0006ב\u0005מה שונה]\u0006 \u0003למטה\u0004 לגבי דור שלישי בבנו ובתו \u0003דלא קחשיב לה\u0004 \u0005[שאיננו\u0006 \u0005מונה אותה]\u0006 את \u0003אשתו\u0004 בחשבון דורות אלה ומונה את הדורות חוץ ממנה, דור שני ושלישי. ומשיבים: \u0003למעלה, דאיסורא\u0004 \u0005[שהאיסור]\u0006 \u0003מכח אשתו קא אתי\u0004 \u0005[הוא שבא],\u0006 שהרי אינן אסורות משום קירבת הדם שלו אליהן, אלא מצד קירבת אשתו — לכן \u0003קחשיב לה\u0004 \u0005[מונה אותה],\u0006 ואילו \u0003למטה, דאיסורא לאו\u0004 \u0005[שהאיסור לא]\u0006 \u0003מכח אשתו קאתי\u0004 \u0005[הוא שבא]\u0006 — \u0003לא קחשיב לה\u0004 \u0005[אינו מונה אותה].\u0006","ומקשים: \u0003והא\u0004 \u0005[והרי]\u0006 \u0003בן אשתו ובת אשתו,\u0004 שגם שם \u0003איסורא\u0004 \u0005[האיסור]\u0006 \u0003מכח אשתו קאתי\u0004 \u0005[הוא שבא],\u0006 \u0003ולא חשיב לה\u0004 \u0005[ואינו מונה אותה]!\u0006 ומשיבים: \u0003איידי דתנא\u0004 \u0005[מתוך ששנה]\u0006 \u0003שלשה דורות למטה דידיה\u0004 \u0005[שלו]\u0006 של בנו ובתו \u0003ולא חשבה\u0004 \u0005[מנה אותה]\u0006 מהטעם שאמרנו, \u0003תנא נמי\u0004 \u0005[שנה גם כך]\u0006 \u0003שלשה דורות למטה דידה\u0004 \u0005[שלה]\u0006 \u0003ולא חשבה\u0004 \u0005[מנה אותה]\u0006 ביניהם כדי לשמור על סגנון אחיד בדברים.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב אשי לרב כהנא:\u0004 אותן \u0003שניות\u0004 שנשנו \u0003דבי\u0004 \u0005[בבית\u0006 מדרשו\u0005]\u0006 של \u0003ר' חייא,\u0004 האם \u0003יש להן הפסק או אין להם הפסק?\u0004 כלומר, האם הכוונה שנאסרו רק אלה, או, שנאסרו גם דורות נוספים למעלה ולמטה מהן?","ומשיבים: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע],\u0006 ראיה לכך ממה ש\u0003אמר רב: ארבע נשים יש להם הפסק, ותו לא\u0004 \u0005[ולא עוד],\u0006 משמע שלכל השאר אין הפסק. ודוחים: \u0003דלמא כי קאמר\u0004 \u0005[שמא כאשר אמר]\u0006 \u0003רב\u0004 — היה זה רק \u0003לההיא מתניתא\u0004 \u0005[לאותה ברייתא]\u0006 שאליה התייחס, ולא לכל השניות. ומציעים: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע],\u0006 ראיה מברייתא זו עצמה, שנאמר בה: \u0003שלישי\u0004 שבבנו \u0003ורביעי\u0004 שבחמיו, ונדייק: \u0003שלישי ורביעי — אין\u0004 \u0005[כן],\u0006 \u0003טפי\u0004 \u0005[יותר]\u0006 — \u0003לא!\u0004 ודוחים: \u0003דלמא\u0004 \u0005[שמא]\u0006 הכוונה היא \u0003משלישי ואילך, מרביעי ואילך.\u0004","בנושא קרוב \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבא לרב נחמן: חזי מר האי מרבנן דאתא ממערבא\u0004 \u0005[יראה אדוני אחד החכמים שבא מארץ ישראל]\u0006 \u0003ואמר: בעו במערבא\u0004 \u0005[שאלו\u0006 שאלה זו \u0005בארץ ישראל]\u0006 האם \u0003גזרו שניות בגרים או לא גזרו שניות בגרים?\u0004","\u0003אמר ליה\u0004 \u0005[לו]\u0006 רב נחמן: \u0003השתא\u0004 \u0005[עכשיו,\u0006 הרי\u0005]\u0006 \u0003ומה ערוה גופא\u0004 \u0005[עצמה]\u0006 \u0003אי לאו\u0004 \u0005[אם לא]\u0006 מפני הטעם \u0003שלא יאמרו\u0004 הגרים הללו בתמיהה שהם \u0003באין מקדושה חמורה לקדושה קלה,\u0004 שלכאורה מותרים הם כיהודים בדברים שנאסרו בהם בהיותם גוים, \u0003לא גזרו בהו רבנן\u0004 \u0005[בהם חכמים]\u0006 ומתירים לגר לשאת כל אשה מקרובות משפחתו שנתגיירו, משום שהגר שנתגייר נחשב כתינוק שנולד, וכל קשריו המשפחתיים הקודמים אינם נחשבים — \u0003שניות מיבעיא\u0004 \u0005[נצרכה]\u0006 לומר שלא גזרו בהן?! כיצד אפשר לומר שיגזרו בהן חכמים?","אגב כך \u0003אמר רב נחמן: גרים, הואיל ואתו לידן\u0004 \u0005[ובאו לידינו],\u0006 כלומר, כיון שעוסקים אנו בסוגיה זו של קירבת משפחה לגביהם, \u0003נימא בהו מלתא\u0004 \u0005[נאמר בהם דבר]\u0006 הלכה: \u0003אחין מן האם\u0004 שהם שניהם גרים — \u0003לא יעידו\u0004 יחד בבית דין, \u0003ואם העידו — עדותן עדות.\u0004 גרים שהם \u0003אחין מן האב — מעידין לכתחלה\u0004 משום שקירבה מצד האב איננה נחשבת כקירבה גמורה לגבי גויים. \u0003אמימר אמר: אפילו אחין מן האם נמי\u0004 \u0005[גם כן]\u0006 \u0003מעידין לכתחלה.\u0004","ואם תשאל \u0003ומאי שנא\u0004 \u0005[ו\u0006ב\u0005מה שונה]\u0006 הדבר \u0003מעריות,\u0004 שאוסרים לגר לשאת את אחותו בת אמו? יש להבדיל: \u0003ערוה לכל מסורה,\u0004 דיני עריות מסורים בידי הכל, שהרי כל אדם בוחר לעצמו אשה, ויש לחשוש שמא יבואו לבחור באותן נשים האסורות להם גם באותן שאינן גרות, ולא יבינו את ההבדל, מה שאין כן \u0003עדות,\u0004 ש\u0003לבית\u0004 ה\u0003דין\u0004 היא \u0003מסורה,\u0004 ובית הדין יודע להבחין בדברים ולא יבואו להחליף, כי לאמיתו של דבר \u0003גר שנתגייר — כקטן שנולד דמי\u0004 \u0005[נחשב]\u0006 וכל קשרי הקירבה הקודמים אינם נחשבים כלל.","\u0003מי שיש לו אח מכל מקום\u0004 מכל סוג שהוא — \u0003זוקק\u0004 האח הזה \u0003את אשת אחיו ליבום, ו\u0004אותו אח — \u0003אחיו הוא לכל דבר, חוץ ממי שיש לו אח\u0004 שנולד \u0003מן השפחה\u0004 או \u0003מן הגויה,\u0004 שאיננו נחשב כאח. וכן \u0003מי שיש לו בן מכל מקום\u0004 מכל סוג — אותו בן \u0003פוטר\u0004 את \u0003אשת אביו מן היבום\u0004 ומן החליצה, שהרי אין חיוב ייבום וחליצה אלא כאשר לא היו למת ילדים כלל. \u0003וחייב\u0004 אותו בן \u0003על מכתו ועל קללתו\u0004 של אביו, שאם היכהו או קיללו חייב מיתה, \u0003ובנו\u0004 הוא \u0003לכל דבר, חוץ ממי שיש לו בן מן השפחה\u0004 או \u0003מן הגויה,\u0004 מפני שאינו נחשב כבנו.","שואלים: מה ששנינו שאח \u0003מכל מקום\u0004 זוקק \u0003לאתויי מאי\u0004 \u0005[להביא,\u0006 להוסיף, \u0005את מה]?\u0006 \u0003אמר רב יהודה: לאתויי\u0004 \u0005[להביא,\u0006 להוסיף\u0005]\u0006 \u0003ממזר,\u0004 שאם יש לו אח ממזר גם הוא נחשב אחיו. ותוהים: \u0003פשיטא\u0004 \u0005[פשוט]\u0006 הלא \u0003אחיו הוא!\u0004 ומסבירים: \u0003מהו דתימא\u0004 \u0005[שתאמר],\u0006 \u0003לילף\u0004 \u0005[ללמוד]\u0006 \u0003אחוה אחוה מבני יעקב,\u0004 וכמו שלמדנו לעצם דין הייבום, ו\u0003מה להלן\u0004 בבני יעקב — \u0003כשרין ולא פסולין, אף כאן\u0004 לדיני ייבום נאמר שחייבים בכך רק \u0003כשרין ולא פסולים,\u0004 על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 שאחיו הוא לייבום.","ושואלים: \u0003ואימא הכי נמי\u0004 \u0005[ואמור כן\u0006 באמת \u0005גם כן]\u0006 שאח פסול לא יזקוק את אשת אחיו לייבום? ומשיבים: \u0003כיון\u0004 ש\u0003לענין יבום מיפטר נפטר\u0004 \u0005[פוטר]\u0006 הוא את האשה, שאם היה לבעלה בן, אפילו ממזר, פטורה היא מייבום,"],["\u0003מיזקק נמי זקיק\u0004 \u0005[זוקק\u0006 אותה \u0005גם כן]\u0006 לייבום, גם אם הוא ממזר.","שנינו במשנה כי \u0003ואחיו הוא לכל דבר.\u0004 ושואלים: \u0003למאי הלכתא\u0004 \u0005[למה,\u0006 לאיזו \u0005הלכה]\u0006 נשנה דבר זה? ומשיבים: \u0003ליורשו\u0004 שהם יורשים זה את זה, \u0003וליטמא לו,\u0004 שאם כהן הוא צריך להיטמא לאחיו הפסול שמת.","ושואלים: \u0003פשיטא\u0004 \u0005[פשוט]\u0006 הדבר הלא \u0003אחיו הוא!\u0004 ומשיבים: \u0003סלקא דעתך אמינא\u0004 \u0005[יעלה על דעתך לומר]:\u0006 \u0003הואיל וכתיב\u0004 \u0005[ונאמר]:\u0006 \u0003\"\u0004לנפש לא יטמא בעמיו. \u0003כי אם לשארו הקרוב אליו\"\u0004 (ויקרא כא, א-ב), \u0003ואמר מר\u0004 \u0005[החכם]:\u0006 \u0003\"שארו\" — זו אשתו, וכתיב\u0004 \u0005[ו\u0006לעומת זה \u0005נאמר]:\u0006 \u0003\"לא יטמא בעל בעמיו להחלו\"\u0004 (שם, ד), וכדי ליישב את הסתירה בפסוקים דרשו: \u0003יש בעל שמטמא\u0004 לאשתו, \u0003ויש בעל שאין מטמא, הא כיצד? — מטמא הוא לאשתו\u0004 ה\u0003כשרה ואין\u0004 הוא \u0003מטמא לאשתו\u0004 ה\u0003פסולה,\u0004 ולפי כלל זה","\u0003הכי נמי\u0004 \u0005[כך גם כן]\u0006 אפשר היה לומר בדומה לכך: \u0003מטמא הוא לאח כשר ואין\u0004 הוא \u0003מטמא לאח פסול\u0004 — על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 שגם לאחיו הפסול מיטמא. ושואלים: \u0003ואימא הכי נמי\u0004 \u0005[ואמור כך גם כן]\u0006 שבאמת אינו מיטמא לו לאח פסול כמו שאינו מיטמא לאשתו הפסולה? ומשיבים: יש לחלק, \u0003התם לאפוקי קיימא\u0004 \u0005[שם\u0006 אשה פסולה \u0005להוציא\u0006 היא \u0005עומדת],\u0006 שכיון שהיא פסולה, מדין תורה צריך לגרש אותה, ולכן אינו מיטמא לה, אולם \u0003הכא\u0004 \u0005[כאן]\u0006 \u0003אחיו הוא\u0004 מכל מקום, בין שהוא כשר, בין שהוא פסול.","שנינו במשנה: \u0003חוץ ממי שיש לו אח מן השפחה ומן הגויה,\u0004 שאינו נחשב כאח. ושואלים: \u0003מאי טעמא\u0004 \u0005[מה הטעם]?\u0006 ומשיבים: \u0003אמר קרא\u0004 \u0005[הכתוב]\u0006 בעבד עברי הנושא שפחה: \u0003\"האשה וילדיה תהיה לאדניה\"\u0004 (שמות כא, ד), משמע שאין בנה של השפחה מתייחס אחר אביו, אלא אחר אמו, והוא עבד כמותה.","שנינו במשנה: \u0003מי שיש לו בן מכל מקום\u0004 — אותו בן \u0003פוטר\u0004 את אשת אביו מן הייבום ומן החליצה. ושואלים: \u0003\"מכל מקום\" לאתויי מאי\u0004 \u0005[להביא,\u0006 להוסיף, את \u0005מה]?\u0006 \u0003אמר רב יהודה: לאתויי\u0004 \u0005[להביא,\u0006 להוסיף\u0005]\u0006 ילד \u0003ממזר,\u0004 שאף הוא פוטר את אשת אביו. \u0003מאי טעמא\u0004 \u0005[מה הטעם]\u0006 של הדבר — ש\u0003אמר קרא\u0004 \u0005[הכתוב]\u0006 בענין ייבום: \u0003\"ובן אין לו\"\u0004 (דברים כה, ה) ודורשים: \"אין לו\" משמעו — \u0003עיין עליו.\u0004 כלומר, חפש ובדוק בכל אופן שיהיה אם אין לו כלל ילד. ואם יש לו בן כלשהו — הרי הוא קרוי בנו.","שנינו במשנה שאותו בן ממזר \u0003חייב על מכתו\u0004 ועל קללתו, אם מכה או מקלל את אביו. ושואלים: \u0003אמאי\u0004 \u0005[מדוע]\u0006 יהיה חייב? \u0003קרי\u0004 \u0005[קרא]\u0006 \u0003כאן\u0004 את הכתוב \u0003\"ונשיא בעמך לא תאור\"\u0004 (שמות כב, כז), שדרשו שאיסור זה הוא רק \u0003בעושה מעשה עמך,\u0004 אבל מי שאינו נוהג בכשרות ואינו עושה מעשה עם ישראל, אין איסור לא תעשה על קללתו. והרי ממזר הוא מי שנולד לאב שבא על אשה האסורה עליו משום ערוה, ואף זה רשע הוא ולא נחייבנו בשל קללתו!","ומשיבים: \u0003כדאמר\u0004 \u0005[כפי\u0006 \u0005שאמר]\u0006 \u0003רב פנחס משמיה\u0004 \u0005[משמו]\u0006 של \u0003רב פפא\u0004 לענין אחר: שמדובר \u0003בעושה תשובה, הכא נמי\u0004 \u0005[כאן גם כן]\u0006 מדובר \u0003כשעשה תשובה\u0004 אחרי שהוליד את הממזר, ועכשיו אדם כשר הוא ולכן חייב בנו הממזר על קללתו.","ומקשים: \u0003והאי בר\u0004 \u0005[וזה\u0006 שהוליד ממזר \u0005בן]\u0006 \u0003תשובה הוא,\u0004 וכי יכול הוא לעשות תשובה? \u0003והתנן\u0004 \u0005[והרי שנינו\u0006 במשנה\u0005]:\u0006 \u0003שמעון בן מנסיא אומר: איזהו \"מעות לא יוכל לתקן\"\u0004 (קהלת א, טו) — \u0003זה הבא על הערוה והוליד ממנה ממזר,\u0004 משמע שאין אצלו אפשרות להגיע לידי תשובה גמורה! ומשיבים: \u0003השתא מיהא\u0004 \u0005[עכשיו לפחות]\u0006 \u0003\"עושה מעשה עמך\" הוא,\u0004 שאף שתשובתו איננה יכולה לתקן לגמרי את העבירה שעשה, מכל מקום עכשיו — אדם כשר הוא ואסור לבזותו.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003הבא\u0004 בשגגה \u0003על אחותו, והיא בת אשת אביו\u0004 שאחות זו נולדה מאשת אביו הנשואה לו כדין — \u0003חייב\u0004 להביא שני קרבנות חטאת: גם \u0003משום אחותו, ו\u0004גם \u0003משום בת אשת אביו. ר' יוסי בן יהודה אומר: אינו חייב אלא משום אחותו בלבד, ולא מפני\u0004 איסור של \u0003בת אשת אביו.\u0004","ושואלים: \u0003מאי טעמייהו דרבנן\u0004 \u0005[מה טעמם של חכמים]?\u0006 — \u0003אמרי\u0004 \u0005[אומרים]\u0006 הם: \u0003מכדי כתיב\u0004 \u0005[הלא נאמר]:\u0006 \u0003\"ערות אחותך בת אביך או בת אמך\"\u0004 (ויקרא יח, ט), ואם כן מה שנאמר עוד: \u0003\"ערות בת אשת אביך מולדת אביך אחותך היא\"\u0004 (שם יא) \u0003למה לי?\u0004 הלא משמעותם זהה! \u0003שמע מינה\u0004 \u0005[למד מכאן]\u0006 שבא הכתוב הנוסף \u0003לחייבו\u0004 גם \u0003משום אחותו, ו\u0004גם \u0003משום בת אשת אביו.\u0004","\u0003ור' יוסי בר' יהודה\u0004 אומר, \u0003אמר קרא: \"אחותך היא\",\u0004 לצמצם ולהדגיש: \u0003משום אחותו אתה מחייבו, ואי\u0004 \u0005[ואין]\u0006 \u0003אתה מחייבו\u0004 עוד \u0003משום בת אשת אביו.\u0004","ושואלים: \u0003ורבנן\u0004 \u0005[וחכמים],\u0006 \u0003האי\u0004 \u0005[\u0006פסוק \u0005זה]\u0006 \u0003\"אחותך היא\" מאי עבדי ליה\u0004 \u0005[מה\u0006 הם \u0005עושים בו]?\u0006 ומסבירים: \u0003מיבעי להו\u0004 \u0005[צריכים הם\u0006 אותו\u0005]\u0006 \u0003לחייבו על אחותו\u0004 שהיא גם \u0003בת אביו ו\u0004גם \u0003בת אמו, לומר\u0004 וללמוד מתוך כך \u0003שאין מזהירין מן הדין.\u0004 כלומר, אין ללמוד וליצור איסור חדש בתורה של לא תעשה על ידי לימוד קל וחומר. שהרי לכאורה אם על אחותו בת אביו חייב, ועל בת אמו חייב — כל שכן שחייב על זו שהיא גם בת אביו וגם בת אמו כאחד. ולכן נאמר הדבר במפורש ללמדנו שאין להוסיף על האיסורים מקל וחומר.","\u0003ור' יוסי בר' יהודה\u0004 אומר: \u0003אם כן,\u0004 שלשם כך נכתב הדבר, \u0003לכתוב רחמנא\u0004 \u0005[שתכתוב התורה]\u0006 \u0003\"אחותך\"\u0004 בלבד, \u0003\"היא\" למה לי?\u0004 אלא מלה זו באה לצמצם ולומר: \u0003משום אחותך אתה מחייבו, ואי\u0004 \u0005[ואין]\u0006 \u0003אתה מחייבו משום בת אשת אביו.\u0004","\u0003ורבנן,\u0004 מה הם משיבים על כך? \u0003אף על גב דכתיב\u0004 \u0005[אף על פי שנאמר]\u0006 \u0003\"אחותך\",\u0004 מכל מקום \u0003איצטריך למכתב\u0004 \u0005[הוצרך לכתוב]\u0006 \u0003\"היא\", שלא תאמר\u0004 כי \u0003בעלמא\u0004 \u0005[בכלל]\u0006 \u0003מזהירין מן הדין,\u0004 אלא","\u0003וכי תימא\u0004 \u0005[ואם תאמר]\u0006 \u0003\"אחותך\" דכתב רחמנא\u0004 \u0005[שכתבה התורה]\u0006 \u0003למה לי\u0004 אם אפשר ללמוד בקל וחומר? אין מכאן הוכחה, כי הייתי אומר: אפילו \u0003מילתא דאתיא\u0004 \u0005[דבר שבא,\u0006 שיכולנו ללמוד בעצמנו\u0005]\u0006 \u0003בקל וחומר, טרח וכתב לה קרא\u0004 \u0005[אותו הכתוב],\u0006 וכיון שכך — אין ללמוד מכאן כלל לכל התורה, על כן \u0003כתב רחמנא\u0004 \u0005[כתבה התורה]\u0006 \u0003\"היא\"\u0004 ללמדנו שהוא הדין לגבי כל האיסורים.","\u0003ור' יוסי בר' יהודה\u0004 אומר: \u0003אם כן,\u0004 שלצורך זה בא הפסוק — \u0003ליכתביה רחמנא\u0004 \u0005[שתכתבנו התורה]\u0006 את \u0003\"אחותך היא\" באידך קרא\u0004 \u0005[בפסוק האחר]\u0006 שנאמר בו \"ערות אחותך בת אביך או בת אמך\" (ויקרא יח, ט) ולא בפסוק השני המדבר בבת אשת אביו.","ושואלים: \u0003ור' יוסי בר' יהודה; האי\u0004 \u0005[\u0006הכתוב \u0005הזה]\u0006 המדבר ב\u0003בת אשת אביך, מאי עביד ליה\u0004 \u0005[מה עושה\u0006 הוא \u0005בו]?\u0006 שהרי לדעתו הוא כתוב מיותר, שאין למדים ממנו דבר! ומשיבים: \u0003מיבעי ליה\u0004 \u0005[נצרך\u0006 הוא \u0005לו]\u0006 לעצם ההלכה, ללמדנו: \"בת אשת אביך\", פירושו, \u0003מי שיש לו\u0004 צד \u0003אישות לאביך בה,\u0004 כלומר, שיכולה היתה להיות אשת אביו, גם אם אינה אשתו, \u0003פרט לאחותו משפחה וגויה, שאין אישות לאביך בה,\u0004 שאין קידושין תופסים בה.","ושואלים: \u0003ואימא\u0004 \u0005[ואמור]:\u0006 \"בת אשת אביך\" בא ללמד שצריכה להיות דווקא בת מאשה הנשואה לאביו \u0003פרט לאחותו מאנוסה,\u0004 שאם נולדה לאביו בת שלא מנשואין איננה נחשבת לאחותו? ומשיבים: \u0003ההיא לא מצית אמרת\u0004 \u0005[\u0006דבר \u0005זה אין אתה יכול לומר]\u0006 \u0003מ\u0004ן הטעם שאמר \u0003רבא,\u0004","\u0003דרבא רמי\u0004 \u0005[השליך,\u0006 הראה סתירה\u0005]:\u0006 \u0003כתיב\u0004 \u0005[נאמר]\u0006 בכתוב אחד \u0003\"ערות בת בנך או בת בתך לא תגלה\"\u0004 (שם יח, י), ומכאן אפשר היה ללמוד: \u0003הא\u0004 \u0005[הרי]\u0006 \u0003בת בנה דידה\u0004 \u0005[שלה]\u0006 של אשתך, \u0003או בת בתה דידה\u0004 \u0005[שלה]\u0006 \u0003שרי\u0004 \u0005[מותרת],\u0006 \u0003ו\u0004לעומת זאת \u0003כתיב\u0004 \u0005[נאמר]\u0006 במקום אחר \u0003\"ערות אשה ובתה לא תגלה את בת בנה ואת בת בתה\u0004 לא תקח\u0003\"\u0004 (שם יז), \u0003הא\u0004 \u0005[הרי]\u0006 \u0003כיצד\u0004 מיישבים זאת?","\u0003כאן\u0004 בפסוק המתיר הרי זה מדובר \u0003באונסין,\u0004 שאם אנס אשה מותר לו לשאת את בתה (אם איננה בתו שלו), ו\u0003כאן\u0004 בפסוק האוסר הרי זה מדובר \u0003בנשואין,\u0004 שאם נשא אשה — אסור לשאת את בתה בכל מקרה וכן באחותו — שבין זו שמן הנשואה ובין זו שמן האנוסה — אסורה."],["\u0003ואימא\u0004 \u0005[ואמור]\u0006 שבא הכתוב \"בת אשת אביך\" ללמד \u0003פרט לחייבי לאוין,\u0004 שאם נשא אביו אשה שאסור לו באיסור לא תעשה לשאתה, כגון ממזרת, לא תיחשב זו כאשתו ולא תהיה לו אחותו ממנה כאחות! \u0003אמר רב פפא: חייבי לאוין תפשי בהו\u0004 \u0005[תופסים בהם]\u0006 \u0003קדושין\u0004 למרות שיש בכך איסור, ולכן אפשר לקרוא לה אשת אביך.","וראיה לדבר, ממה \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"כי תהיין לאיש שתי נשים האחת אהובה והאחת שנואה\"\u0004 (דברים כא, טו), ויש להבין: \u0003וכי יש אהובה לפני המקום ויש שנואה לפני המקום,\u0004 שהכתוב קורא לה אהובה ושנואה סתם, ולא אומר אהובה לבעלה ושנואה לבעלה? \u0003אלא\u0004 הכוונה היא: \u0003\"אהובה\" — אהובה בנישואיה,\u0004 שהיו נישואיה כשרים, ו\u0003\"שנואה\"\u0004 הכוונה: \u0003שנואה בנישואיה, ואמר רחמנא\u0004 \u0005[ואמרה התורה]\u0006 על שתיהן \u0003\"כי תהיין\",\u0004 משמע שיש בהן הוויה, כלומר: קשר נישואין.","ושואלים: \u0003ואימא\u0004 \u0005[ואמור] —\u0006 \u0003פרט לחייבי כריתות,\u0004 בא הכתוב ללמד, שאם בא אביו על ערוה שחייב עליה כרת — מאחר ובאשה זו אין לאב הוויית אישות, שהרי אין קידושין תופסים בה, שמא אחות הנולדת מאשה כזו לא תיאסר עליו משום בת אשת אביו? \u0003אמר רבא, אמר קרא\u0004 \u0005[הכתוב]:\u0006 \u0003\"ערות אחותך בת אביך או בת אמך מולדת בית או מולדת חוץ\"\u0004 (ויקרא יח, ט), כלומר, \u0003בין\u0004 מאשה \u0003שאומרים לו לאביך \"קיים\"\u0004 (השאר אותה בבית), \u0003בין שאומרים לו לאביך \"הוצא\"\u0004 מפני שהיא ערוה עליך, \u0003ואמר רחמנא\u0004 \u0005[ואמרה התורה]\u0006 \u0003\"אחותך היא\"\u0004 (שם יא), כלומר, אף זו שהיתה ערוה על אביך, בתה נקראת \"אחותך\".","ושואלים: \u0003אימא\u0004 \u0005[ואמור]\u0006 \u0003בין שאומר לו אביך \"קיים\" בין שאומר לו אביך \"הוצא\", ואמר רחמנא\u0004 \u0005[ואמרה התורה]\u0006 \u0003\"אחותך היא\",\u0004 וכוונתו \u0003לרבות אחותו משפחה וגויה!\u0004 ודוחים: \u0003אמר קרא\u0004 \u0005[הכתוב]:\u0006 \u0003\"בת אשת אביך\"\u0004 (שם), כלומר, \u0003מי שיש לו אישות\u0004 (קשר נישואין) \u0003לאביך בה, פרט לאחותו משפחה וגויה\u0004 שאין לו לאביך אישות באמה.","ושואלים: כיון שהכתוב באיסור אחותו מרבה וממעט, \u0003ומה ראית\u0004 להכניס ולכלול בו בת חייבי כריתות ולהוציא בת שפחה וגויה? ומשיבים: \u0003מסתברא\u0004 \u0005[מסתבר]\u0006 \u0003חייבי כריתות הוה ליה\u0004 \u0005[היה לו]\u0006 \u0003לרבות, שכן תפסי\u0004 \u0005[תופסים]\u0006 \u0003בהן קדושין לעלמא\u0004 \u0005[בכלל],\u0006 שאף על פי שלאביו אסורה אשה זאת, מכל מקום מותרת היא לאחרים.","ודוחים: \u0003אדרבה\u0004 (להיפך), \u0003שפחה וגויה הוה ליה\u0004 \u0005[היה לו]\u0006 \u0003לרבות, דאי מגיירה\u0004 \u0005[שאם\u0006 היא \u0005מתגיירת]\u0006 \u0003לדידיה נמי תפסי\u0004 \u0005[לו עצמו גם כן יתפסו]\u0006 \u0003בה קדושין!\u0004 ומשיבים: \u0003לכי מגיירה\u0004 \u0005[כאשר\u0006 היא \u0005מתגיירת] —\u0006 \u0003גופא אחרינא\u0004 \u0005[גוף אחר]\u0006 \u0003היא,\u0004 כלומר, שוב איננה נחשבת כאותה אשה, אלא כאדם אחר, ובהיותה גויה — אין בה קשר אישות ולכן בא הכתוב והוציאה.","ושואלים: \u0003ורבנן\u0004 \u0005[וחכמים]\u0006 הלומדים ענין אחר מהפסוק \"ערות אשת אביך\" — הלכה זו \u0003למעוטי\u0004 \u0005[למעט]\u0006 אחותו מ\u0003שפחה וגויה מנא להו\u0004 \u0005[מניין להם]?\u0006 ומשיבים: \u0003נפקא להו\u0004 \u0005[יוצא,\u0006 נלמד \u0005להם]\u0006 הדבר \u0003מ\u0004מה שנאמר בשפחה כנענית הנשואה לעבד עברי: \u0003\"האשה וילדיה תהיה לאדניה\"\u0004 (שמות כא, ד), ולמדים מכאן שבני השפחה אינם מתייחסים כלל אל אביהם היהודי אלא אל אמם השפחה.","ושואלים: \u0003ור' יוסי בר' יהודה\u0004 מדוע אין גם הוא לומד מכאן? ומשיבים: \u0003חד\u0004 \u0005[\u0006פסוק \u0005אחד]\u0006 (\"האשה וילדיה\") נצרך ללמדנו \u0003בשפחה, וחד\u0004 \u0005[ו\u0006פסוק \u0005אחד]\u0006 צריך ללמדנו לענין \u0003גויה.\u0004 ומעירים, \u0003וצריכי\u0004 \u0005[וצריכים]\u0006 שני פסוקים לשם כך, \u0003דאי אשמעינן\u0004 \u0005[שאם היה משמיע לנו]\u0006 רק ב\u0003שפחה,\u0004 הייתי אומר: \u0003משום\u0004 ש\u0003אין לה חייס\u0004 \u0005[יחוס],\u0006 שמהתורה נראה שלגבי בני השפחה אין כל יחוס משפחת אב, \u0003אבל גויה דאית\u0004 \u0005[שיש]\u0006 \u0003לה חייס\u0004 \u0005[יחוס] —\u0006 \u0003אימא\u0004 \u0005[אמור]\u0006 ש\u0003לא,\u0004 ולכן היה צריך לומר שגם בת הגויה איננה נחשבת לבתו.","ולהיפך: \u0003ואי אשמעינן\u0004 \u0005[ואם היה משמיענו]\u0006 רק ב\u0003גויה,\u0004 הייתי אומר \u0003משום דלא שייכא\u0004 \u0005[שאיננה שייכת]\u0006 כלל \u0003במצות,\u0004 ולכן אין לילדיה קשר לישראל, \u0003אבל שפחה דשייכא\u0004 \u0005[ששייכת]\u0006 \u0003במצות,\u0004 שהרי השפחה, כמו העבד, מצווה על קיום כל מצוות לא תעשה ומצוות עשה שאין הזמן גורם לחיובם, \u0003אימא\u0004 \u0005[אמור]\u0006 ש\u0003לא,\u0004 וילדיה ייחשבו כבני אביהם היהודי, על כן \u0003צריכא\u0004 \u0005[נצרכה]\u0006 גם הוכחה נוספת זו.","ושואלים: \u0003ורבנן, אשכחן\u0004 \u0005[וחכמים, מצאנו]\u0006 כבר הוכחה, על פי שיטתם ב\u0003שפחה,\u0004 שילדיה אינם נחשבים כבני אביהם היהודי, אבל בנים שנולדו לישראל מ\u0003גויה מנא להו\u0004 \u0005[מניין להם]\u0006 שאינם נחשבים יהודים? \u0003וכי תימא נילף\u0004 \u0005[ואם תאמר\u0006 כי \u0005נלמד]\u0006 זאת \u0003משפחה\u0004 — הלא כפי שהוכחנו \u0003הנהו מצרך צריכי\u0004 \u0005[\u0006שני הדברים \u0005הללו צריכים]\u0006 שייאמרו שניהם, ואי אפשר ללמדם זה מזה!","ומשיבים: \u0003אמר ר' יוחנן משום\u0004 \u0005[בשם]\u0006 \u0003ר' שמעון בן יוחי:\u0004 הוכחה לדבר זה ממה ש\u0003אמר קרא\u0004 \u0005[הכתוב]:\u0006 \u0003\"\u0004ולא תתחתן בם בתך לא תתן לבנו ובתו לא תקח לבנך. \u0003כי יסיר את בנך מאחרי\"\u0004 (דברים ז, ג-ד), ללמד: \u0003בנך\u0004 הבא \u0003מישראלית — קרוי בנך, ואין בנך הבא מן הגויה קרוי בנך, אלא בנה.\u0004 וכיון שלא חשש הכתוב לילדים הנולדים מן הגויה, משמע שאין בן הגויה מתייחס כלל אחר אביו הישראלי.","\u0003אמר רבינא: שמע מינה\u0004 \u0005[למד מכאן]\u0006 ש\u0003בן בתך הבא מן הגוי קרוי\u0004 בכל זאת \u0003בנך.\u0004 ושואלים: \u0003לימא קסבר\u0004 \u0005[האם לומר\u0006 ש\u0005סבור]\u0006 \u0003רבינא\u0004 כי \u0003גוי ועבד הבא על בת ישראל הולד כשר?\u0004 ומשיבים: אין להוכיח מכאן הוכחה גמורה כי \u0003נהי\u0004 \u0005[אם אמנם]\u0006 ש\u0003ממזר לא הוי\u0004 \u0005[איננו]\u0006 — \u0003כשר נמי לא הוי\u0004 \u0005[גם כן איננו],\u0006 אלא \u0003ישראל פסול מיקרי\u0004 \u0005[נקרא]\u0006 ופסול לענין נישואין לכהונה.","ושואלים: לטעמו של ר' שמעון, הלא \u0003האי\u0004 \u0005[\u0006פסוק \u0005זה]\u0006 \u0003בשבעה אומות,\u0004 הכנעני והחתי וכו' \u0003כתיב\u0004 \u0005[נאמר],\u0006 ולא נאמר בעמים אחרים? ומשיבים, הרי נאמר שם בפסוק טעם לדבר: \u0003\"כי יסיר\" — לרבות כל המסירים.\u0004 כלומר, בא לרבות כל האומות שאף הן מסירות מאחרי ה'.","ושואלים: \u0003הניחא\u0004 \u0005[זה נוח]\u0006 \u0003לר' שמעון, דדריש טעמא דקרא\u0004 \u0005[שדורש\u0006 את \u0005טעם הכתוב],\u0006 כלומר, שהוא סבור שמאחר שיש לכתוב טעם מסויים, אפשר ללמוד ממנו כאילו היה הטעם מפורש, \u0003אלא לרבנן\u0004 \u0005[לחכמים],\u0006 שאינם דורשים טעם הכתוב, \u0003מנא להו\u0004 \u0005[מניין להם]\u0006 דין זה בשאר אומות? ומשיבים: \u0003מאן תנא דפליג עליה\u0004 \u0005[מי\u0006 הוא \u0005התנא שחולק עליו]\u0006 על \u0003ר' יוסי בר' יהודה — ר' שמעון היא,\u0004 ואם כן, לדעת ר' יוסי בר' יהודה המקור ללימוד זה הוא מן הכתוב \"בת אשת אביך\" והחולק עליו לענין דרשה זו הוא ר' שמעון, ור' שמעון, כפי שאמרנו, למד אותו ענין מכתוב אחר."],["\u0003מי שקידש אחת משתי אחיות ואין יודע אי זה מהן קידש,\u0004 והריהו אסור בשתיהן — \u0003נותן\u0004 מספק \u0003גט לזו, וגט לזו. מת\u0004 המקדש לפני שנתן גט, \u0003ולו אח אחד\u0004 — \u0003חולץ\u0004 האח \u0003לשתיהן,\u0004 אבל אינו מייבם, כיון שאינו יודע מיהי יבמתו ומיהי אחות יבמתו (האסורה עליו).","\u0003היו לו\u0004 למקדש \u0003שנים\u0004 (שני אחים), \u0003אחד\u0004 מהם \u0003חולץ\u0004 לאחת האחיות ואינו מייבם, שמא אחותה היא היבמה ונמצאת זו אחות זקוקתו, \u0003ואחד מייבם\u0004 לאחרת, אם ירצה. \u0003קדמו\u0004 (הזדרזו) שני האחים \u0003וכנסו\u0004 (ונשאו) את שתיהן בלא לשאול כיצד לעשות כהלכה — \u0003אין מוציאין מידם.\u0004 שהרי זו שהיתה יבמה — כבר נתייבמה, וממילא נפטרה אחותה מן הזיקה, ומותרת לאחיו.","וכן: \u0003שנים שקדשו שתי אחיות, זה אינו יודע אי זו קידש, וזה אינו יודע איזו קידש — זה נותן שני גיטין, וזה נותן שני גיטין. מתו\u0004 לפני שגירשו, אם היה \u0003לזה אח ולזה אח\u0004 — \u0003זה חולץ לשתיהן, וזה חולץ לשתיהן.\u0004","היה \u0003לזה\u0004 אח \u0003אחד, ולזה שנים — היחיד חולץ לשתיהן. והשנים — אחד חולץ, ואחד מייבם. קדמו\u0004 השנים \u0003וכנסו — אין מוציאין מידם.\u0004 היו \u0003לזה שנים ולזה שנים — אחיו של זה חולץ לאחת, ואחיו של זה חולץ לאחת, אחיו של זה\u0004 שחלץ \u0003מייבם חלוצתו של זה\u0004 של אחיו האחר, \u0003ואחיו של זה\u0004 השני שחלץ \u0003מייבם חלוצתו של זה.\u0004","\u0003קדמו שנים\u0004 שני אחים \u0003וחלצו — לא ייבמו השנים\u0004 האחרים (אחיו של האיש השני), שמא ייבם אחד את אחות זקוקתו, \u0003אלא אחד חולץ ואחד מייבם. קדמו וכנסו — אין מוציאין מידם.\u0004","\u0003שמע מינה\u0004 \u0005[למד מכאן]\u0006 ממשנתנו זו כי \u0003קדושין שאין מסורין לביאה,\u0004 כלומר, קידושין שאירע בהם סבך הלכתי כזה שלעולם אינם יכולים להגיע לידי ביאה, משום שכרוך בהם איסור המונע מלכנוס את האשה. ואף קידושין אלה שמדובר בהם במשנה הם בכלל זה, שהרי אינו יכול לשאת אף אחת משתי אחיות אלה, מפני שביחס לכל אחת מהן יש ספק שמא זו שכונס היא אחותה של זו שקידש, ואסורה עליו כל ימי חייה. ועם זאת נאמר במשנה שצריך לתת גט לשתיהן, משתמע איפוא מכאן כי קידושין אלה \u0003הוו\u0004 \u0005[הריהם]\u0006 \u0003קדושין,\u0004 ותופסים, אף כי בפועל אינו יכול לשאת אף אחת מהן. והרי זה בניגוד לשיטת רבא, שאמר שקידושין שאינם מסורים לביאה — אינם קידושין כלל!","ודוחים: \u0003הכא במאי עסקינן\u0004 \u0005[כאן במה אנו עוסקים] —\u0006 \u0003כשהוכרו\u0004 שתי האחיות מתחילה, שבשעת קידושין ידע איזו מהן הוא מקדש, ולכן, בשעת קידושין היו אלה קידושין המסורים לביאה, אלא \u0003ולבסוף נתערבו\u0004 שתי האחיות, ושוב אינו יודע איזו מהן קידש, ואם כן לא היה כאן מתחילה פגם בעצם הקידושין, אלא שנתעוררה אחר כך בעיה מעשית מחוסר ידיעת העובדות. ומעירים: \u0003דיקא נמי\u0004 \u0005[מדוייק גם כן]\u0006 שיש לפרש כך, מלשון המשנה, \u0003דקתני\u0004 \u0005[ששנה\u0006 בה\u0005]\u0006 \u0003\"ואינו יודע\u0004 איזו מהן קידש \u0003\"\u0004\u0003ולא קתני\u0004 \u0005[שנה]\u0006 \u0003\"ואינו ידוע\"\u0004 כלל, משמע שהדבר היה ידוע בזמן מסויים. ומוסיפים: אכן, \u0003שמע מינה\u0004 \u0005[למד מכאן].\u0006","ושואלים: אם כן, \u0003מאי קא משמע לן\u0004 \u0005[מה\u0006 חידוש \u0005השמיע לנו]\u0006 בקטע זה של המשנה שנותן לזו גט ולזו גט? ומשיבים: \u0003סיפא איצטריכא ליה\u0004 \u0005[סופה\u0006 של המשנה היתה \u0005צריכה לו],\u0006 ששנינו שם: \u0003מת ולו אח אחד — חולץ לשתיהן, היו לו שנים — אחד חולץ ואחד מייבם.\u0004 וזהו החידוש: \u0003דוקא מיחלץ והדר יבומי\u0004 \u0005[לחלוץ ואחר כך לייבם],\u0006 \u0003אבל יבומי ברישא\u0004 \u0005[לייבם בתחילה]\u0006 — \u0003לא,\u0004 ומדוע? — \u0003דקא פגע\u0004 \u0005[ש\u0006הרי הוא \u0005פוגע\u0006 ונתקל\u0005]\u0006 על ידי ייבום זה \u0003ב\u0004אשה שהיא \u0003אחות זקוקתו.\u0004 שהרי איננו יודע אם האשה הזו שמייבם איננה אחותה של זו שזקוקה לו באמת, ואחות זקוקתו אסורה לו. ואף על פי שייתכן שאותה אשה עצמה היא היבמה — מכל מקום הרי לא הוברר הענין.","שנינו במשנה \u0003שנים שקדשו שתי אחיות וכו'.\u0004 ושואלים: \u0003שמע מינה\u0004 \u0005[למד מכאן]\u0006 ש\u0003קדושין שאין מסורין לביאה הוו\u0004 \u0005[הריהם]\u0006 \u0003קדושין!\u0004 ודוחים: \u0003הכא נמי\u0004 \u0005[כאן גם כן]\u0006 מדובר \u0003כשהוכרו ולבסוף נתערבו.\u0004 ומעירים: \u0003דיקא נמי, דקתני\u0004 \u0005[מדוייק גם כן\u0006 כך, \u0005ששנה]\u0006 \u0003\"ואין יודע\",\u0004 משמע שהוא אינו יודע עכשיו את מי מהן קידש \u0003ולא קתני\u0004 \u0005[שנה]\u0006 \u0003\"ואין ידוע\".\u0004 ומסכמים: אכן, \u0003שמע מינה\u0004 \u0005[למד מכאן]\u0006 שכן הוא.","ושואלים: אם כן, \u0003ומאי קא משמע לן\u0004 \u0005[ומה\u0006 חידוש \u0005השמיע לנו]\u0006 בכך ששניהם נותנים גט? ומסבירים: \u0003סיפא איצטריכא ליה\u0004 \u0005[סופו\u0006 של אותו קטע \u0005הוצרך לו],\u0006 שנאמר בו: \u0003מתו, לזה\u0004 אח \u0003אחד ולזה שנים\u0004 — \u0003היחיד חולץ לשתיהן, והשנים\u0004 — \u0003אחד חולץ ואחד מייבם.\u0004","ושואלים: \u0003פשיטא\u0004 \u0005[פשוט]\u0006 \u0003היינו רישא\u0004 \u0005[\u0006הרי \u0005הוא\u0006 הדין שכתוב ב\u0005התחלה]\u0006 ומה החידוש במקרה נוסף זה? ומשיבים: \u0003מהו דתימא\u0004 \u0005[שתאמר]\u0006 \u0003ליגזור תרי אטו חד\u0004 \u0005[שנגזור\u0006 ב\u0005שני\u0006 אחים \u0005משום\u0006 האח \u0005האחד],\u0006 וכשם שאח אחד רשאי רק לחלוץ ולא לייבם, כך יהא הדין בשנים, על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 שכאן רשאי אחד מהם לייבם.","ומעירים: \u0003ודוקא מיחלץ והדר יבומי\u0004 \u0005[לחלוץ ואחר כך לייבם],\u0006 \u0003אבל יבומי ברישא\u0004 \u0005[לייבם בתחילה] —\u0006 \u0003לא,\u0004 שאסור שאחד ייבם ויניח לאחרים לחלוץ. ומדוע? — \u0003דקא פגע\u0004 \u0005[\u0006שמא הוא \u0005פוגע]\u0006 \u0003ביבמה לשוק.\u0004 שהרי ייתכן שהאשה הזו אינה יבמתו שלו, אלא יבמתו של אדם אחר, שכיון שאחיו של האחר עדיין לא חלץ לה — אסור ליבמה זו להינשא לאדם אחר.","שנינו במשנה: \u0003לזה שנים ולזה שנים וכו'.\u0004 ושואלים: \u0003הא תו\u0004 \u0005[\u0006הלכה \u0005זו עוד]\u0006 \u0003למה לי\u0004 הלא \u0003היינו הך\u0004 \u0005[היא היא\u0006 כהלכה הקודמת\u0005]!\u0006 ומשיבים: \u0003מהו דתימא\u0004 \u0005[שתאמר]\u0006 \u0003ליגזור דלמא מייבם\u0004 \u0005[נגזור שמא\u0006 יבוא \u0005לייבם]\u0006 \u0003בלא חליצה\u0004 של האחר כלל, על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 שאין אנחנו גוזרים, אלא כל אחד מזוג האחים יכול גם לייבם.","ושואלים: \u0003מאי שנא מהא דתנן\u0004 \u0005[\u0006ב\u0005מה שונה\u0006 הדבר \u0005מזו ששנינו\u0006 במשנה אחרת\u0005]:\u0006 היו \u0003ארבעה אחין,\u0004 והיו \u0003שנים מהן נשואין שתי אחיות, ומתו הנשואין את האחיות — הרי אלו\u0004 שתי האחיות \u0003חולצות ולא מתייבמות,\u0004 מפני שכל אחת מהן היא אחות זקוקתו של כל אחד מן האחים, ומדוע לא נאמר גם כאן שכל אחת מהן היא אחות זקוקתו?","ודוחים: \u0003הכי השתא\u0004 \u0005[כיצד אתה משווה]?!\u0006"],["\u0003התם\u0004 \u0005[שם]\u0006 באותו מקרה, \u0003אי\u0004 \u0005[אם]\u0006 נפרש \u0003למאן דאמר\u0004 \u0005[למי שאומר]\u0006 \u0003יש זיקה —\u0004 הלא \u0003יש\u0004 כאן \u0003זיקה,\u0004 שהרי ודאי היו האחיות הללו נשואות לאחים, וחייבות בייבום. \u0003ואי למאן דאמר\u0004 \u0005[ואם למי שאומר]\u0006 \u0003אסור לבטל מצות יבמין,\u0004 שאסור ליצור מצב שבו תתבטל מצות הייבום — אף כאן אפשר לומר ש\u0003אסור לבטל מצות יבמין\u0004 וזה הטעם שחולצות ולא מתייבמות. אבל \u0003הכא\u0004 \u0005[כאן]\u0006 במקרה שלנו, שיש ספק בדבר — \u0003כל חד וחד\u0004 \u0005[אחד ואחד\u0006 מהם\u0005]\u0006 \u0003אימור דידיה קא מתרמיא ליה\u0004 \u0005[אמור ש\u0006שלו \u0005מזדמנת לו]\u0006 ושמא נזדמן שהוא מייבם את מי שהיתה לאמיתו של דבר אשת אחיו.","שנינו במשנה שאם לאחר שחלצו שני אחיו של האחד \u0003קדמו\u0004 אחיו של השני \u0003וכנסו\u0004 בלא לשאול אם הדבר מותר להם — \u0003אין מוציאין\u0004 מידם. \u0003תני\u0004 \u0005[שנה]\u0006 החכם \u0003שילא\u0004 ברייתא זו: \u0003ואפילו\u0004 היו \u0003שניהם\u0004 שני האחים \u0003כהנים\u0004 שהחלוצה אסורה עליהם, מכל מקום, אם כנסו — אין מוציאים מידם, \u0003מאי טעמא\u0004 \u0005[\u0006ו\u0005מה הטעם]\u0006 לא אסרו עליהם הרי חלץ להם אחיו של האחר — כי \u0003חלוצה\u0004 כל איסורה לכהן רק \u0003דרבנן\u0004 \u0005[מדברי סופרים]\u0006 \u0003היא,\u0004 משום שהיא דומה לגרושה, \u0003וספק חלוצה לא גזרו בהו רבנן\u0004 \u0005[בהן חכמים]\u0006 שמפני הספק יצטרך להוציא אשה שכבר נשא. שהרי יתכן שאף על פי שחלצו לה, שמא לא יבמה, היבם האמיתי, הוא שחלץ לה, ולא היתה כאן חליצה.","ושואלים: \u0003ו\u0004האם \u0003חלוצה\u0004 לכהן \u0003דרבנן\u0004 \u0005[מדברי סופרים]\u0006 \u0003היא\u0004 שאסורה? \u0003והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005],\u0006 נאמר: \"אלמנה ו\u0003גרושה\u0004 וחללה זונה את אלה לא יקח\" (ויקרא כא, יד), \u0003אין לי אלא גרושה, חלוצה מנין? תלמוד לומר: \"ואשה\",\u0004 שמלה יתירה זו באה לרבות גם חלוצה, שהיא מעין גרושה ואף היא אסורה לכהן, והרי שהחלוצה אסורה מן התורה! ומשיבים: האיסור באמת \u0003מדרבנן\u0004 \u0005[מדברי סופרים]\u0006 \u0003הוא, וקרא אסמכתא בעלמא\u0004 \u0005[והכתוב\u0006 שהבאנו רק \u0005סמך בלבד]\u0006 \u0003הוא,\u0004 ואינו פירוש הכתוב ממש.","\u0003מצוה בגדול\u0004 שבאחים הנותרים \u0003לייבם, ואם קדם הקטן\u0004 וייבם — \u0003זכה.\u0004","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]\u0006 מדרש זה של המקרא, נאמר: \"והיה הבכור אשר תלד יקום על שם אחיו המת\" (דברים כה, ו), וכך דורשים: \u0003\"והיה הבכור\" — מיכן\u0004 (מכאן, מפסוק זה) למדנו \u0003שמצוה בגדול,\u0004 שהוא בכור האחים, \u0003לייבם\u0004 את אשת אחיו. \u0003\"אשר תלד\"\u0004 כוונתו: \u0003פרט\u0004 למקרה שאשת המת היתה \u0003אילונית, שאינה יולדת,\u0004 ואז אין מקום למצוה זו. \u0003\"יקום על שם אחיו\"\u0004 כוונתו: אותו אח שמייבם, הוא יקום על שם אחיו, ויירש אותו \u0003לנחלה.\u0004","וממשיך מדרש ההלכה לשאת ולתת בדבר: \u0003אתה אומר\u0004 שהכוונה היא \u0003לנחלה, או אינו אלא לשם,\u0004 כגון שאם המת היה נקרא \u0003יוסף — קורין אותו,\u0004 את הבן הנולד לאח המייבם מאשת המת, \u0003יוסף,\u0004 ואם היה נקרא \u0003יוחנן — קורין אותו יוחנן?\u0004 ופותרים ספק זה על ידי גזירה שווה: \u0003נאמר כאן \"יקום על שם אחיו\" ונאמר להלן \"על שם אחיהם יקראו בנחלתם\"\u0004 (בראשית מח, ו), \u0003מה \"שם\" האמור להלן,\u0004 בספר בראשית, כוונתו \u0003נחלה,\u0004 לומר שיורשים נחלה עם אחיהם, \u0003אף \"שם\" האמור כאן\u0004 — \u0003לנחלה.\u0004","נאמר שם בפרשת ייבום: \u0003\"ולא ימחה שמו\"\u0004 (דברים כה, ו), ולמדים מזה: \u0003פרט\u0004 אם היה המת \u0003סריס ששמו מחוי\u0004 ממילא, שהרי מן הנמנע שהיו לו ילדים.","\u0003אמר רבא: אף על גב\u0004 \u0005[אף על פי]\u0006 ש\u0003בכל התורה כולה אין מקרא יוצא מידי פשוטו,\u0004 וגם אם דורשים חכמים את המקראות, אין הדרשה עוקרת את פשוטו של המקרא — \u0003הכא אתאי\u0004 \u0005[כאן באה]\u0006 ה\u0003גזרה שוה\u0004 לענין \"יקום על שם אחיו\" \u0003אפיקתיה מפשטיה\u0004 \u0005[\u0006ו\u0005הוציאה\u0006 את הפסוק \u0005מפשוטו]\u0006 \u0003לגמרי,\u0004 לומר שאינו צריך לקרוא לבן הנולד על שם אחיו.","ושואלים: \u0003ואי לאו\u0004 \u0005[ואם לא\u0006 היתה\u0005]\u0006 \u0003גזרה שוה הוה אמינא\u0004 \u0005[הייתי אומר]\u0006 \u0003\"שם\" —\u0004 כוונתו \u0003שם ממש?\u0004 והרי הפסוק איננו מובן לפי פירוש זה הנראה לכאורה פשוט כל כך, כי \u0003למאן קמזהר רחמנא\u0004 \u0005[למי מזהירה התורה],\u0006 כלומר, אל מי פונה התורה בפסוק זה? אם \u0003ליבם\u0004 שיקרא לבנו על שם אחיו \u0003— \"יקום על שם אחיך\" מיבעי ליה\u0004 \u0005[צריך לו]\u0006 שיאמר, ו\u0003אי\u0004 \u0005[אם]\u0006 הכתוב פונה \u0003לבי דינא\u0004 \u0005[לבית הדין]\u0006 להורותו בכלל מה צריך לעשות — \u0003\"יקום על שם אחי אביו\" מיבעי ליה\u0004 \u0005[צריך\u0006 היה \u0005לו\u0006 לומר\u0005]!\u0006","ומסבירים: \u0003ודלמא הכי קאמר להו רחמנא\u0004 \u0005[ואולי\u0006 נפרש כי \u0005כך אמרה להם התורה]\u0006 \u0003לבית\u0004 ה\u0003דין: אמרו ליה\u0004 \u0005[לו]\u0006 \u0003ליבם\u0004 שהבן שיוולד לו \u0003יקום על שם אחיו,\u0004 ואם כן יכול המקרא להתפרש כפשוטו. \u0003אלא אתאי\u0004 \u0005[באה]\u0006 ה\u0003גזרה שוה אפיקתיה לגמרי\u0004 \u0005[\u0006ו\u0005הוציאה אותו]\u0006 \u0003לגמרי\u0004 מפשוטו.","לאחר שפירשנו את עצם הדין, שואלים באופנים שונים על פרטי הדין הזה: \u0003השתא דאמרת קרא\u0004 \u0005[עכשיו שאתה אומר\u0006 ש\u0005הפסוק]\u0006 \"והיה הבכור אשר תלד\" לגבי האח ה\u0003גדול כתיב\u0004 \u0005[\u0006הוא ש\u0005נאמר]\u0006 ולא בילד הנולד מן הייבום, יש מקום לשאול בכל זאת \u0003אימא\u0004 \u0005[אמור]\u0006 ש\u0003בכור\u0004 האחים \u0003לייבם\u0004 \u0005[\u0006הוא \u0005שייבם]\u0006 אבל אח שאינו בכור, אלא \u0003פשוט,\u0004 ש\u0003לא לייבם\u0004 \u0005[ייבם]!\u0006","ומשיבים: \u0003אם כן,\u0004 שמצות ייבום חלה רק על בכור, \u0003אשת אחיו שלא היה בעולמו, דמיעט רחמנא\u0004 \u0005[שמיעטה התורה]\u0006 באומרה \"כי ישבו אחים יחדיו\", וכאשר אינם יושבים האחים יחדיו — איננו חייב בייבום, \u0003למה לי?\u0004 שהרי אם רק הבכור מייבם — ממילא לא יכול להיות מקרה של אשת אחיו שלא היה בעולמו, שהרי הנולד אחר כך אינו יכול להיות בכור, שהרי אחיו המת היה גדול ממנו!","על קושיה זו \u0003פריך\u0004 \u0005[מקשה]\u0006 \u0003רב אחא: ואימא למעוטי בוכרא דאמא\u0004 \u0005[ואמור\u0006 שהפסוק בא \u0005למעט בכור מאם],\u0006 שהרי יתכן שיוולד למת אח, שיהא בכור לאמו ולא יהיה חייב בייבום! ודוחים: \u0003ההוא לא מצית אמרת\u0004 \u0005[\u0006דבר \u0005זה אינך יכול לומר]\u0006 ומדוע — כיון שאת מצוות ה\u0003יבום בנחלה תלה רחמנא\u0004 \u0005[תלתה התורה]\u0006 \u0003ונחלה\u0004 היא \u0003מן האב ולא מן האם,\u0004 לכן אין כלל לעלות על הדעת למעט מן הפסוק את הבכור מן האם.","אלא יש לשאול שאלה אחרת: \u0003ואימא\u0004 \u0005[ואמור]:\u0006 \u0003כי איכא\u0004 \u0005[כאשר יש]\u0006 \u0003בכור — תתקיים מצות יבום, כי ליכא\u0004 \u0005[כאשר אין]\u0006 \u0003בכור — לא תתקיים מצות יבום!\u0004 ומשיבים: \u0003אמר קרא\u0004 \u0005[הכתוב]:\u0006 \u0003\"ומת אחד מהם\"\u0004 (שם), שנאמר בלשון כללית, \u0003מי לא עסקינן דמית\u0004 \u0005[האם אין אנו עוסקים\u0006 גם במקרה \u0005שמת]\u0006 ה\u0003בכור, ואמר רחמנא\u0004 \u0005[ואמרה התורה]:\u0006 \u0003לייבם\u0004 \u0005[שייבם]\u0006 ה\u0003קטן.\u0004","ושואלים: \u0003ואימא\u0004 \u0005[ואמור]\u0006 \u0003דמית\u0004 \u0005[שמת]\u0006 ה\u0003קטן,\u0004 כלומר, לא בכור האחים, \u0003ו\u0004רק אז \u0003אמר רחמנא לייבם\u0004 \u0005[אמרה התורה שייבם]\u0006 ה\u0003בכור?\u0004 ומשיבים: \u0003הא מיעט רחמנא\u0004 \u0005[הרי\u0006 כבר \u0005מיעטה התורה]\u0006 \u0003אשת אחיו שלא היה בעולמו\u0004 וזה יכול להיות רק באח שאינו בכור.","ומקשים מצד אחר: \u0003ואימא\u0004 \u0005[ואמור\u0006 כך\u0005]:\u0006 \u0003כי ליכא\u0004 \u0005[כאשר אין]\u0006 אח שהוא \u0003בכור\u0004 ממש, אם \u0003קדם\u0004 ה\u0003קטן\u0004 וייבם — \u0003זכה. ואי איכא\u0004 \u0005[ואם יש]\u0006 \u0003בכור,\u0004 כיון שהמצוה היא על הבכור דווקא, אם \u0003קדם קטן — לא זכה!\u0004 ומשיבים: \u0003אמר קרא\u0004 \u0005[הכתוב]:\u0006 \u0003\"כי ישבו אחים יחדו\"\u0004 (שם ה), לומר: \u0003הוקשה\u0004 (הושוותה) \u0003ישיבת אחים זה לזה,\u0004 שכל האחים שווים לענין זה.","ומקשים עוד: \u0003ואימא\u0004 \u0005[ואמור]:\u0006 \u0003כי איכא\u0004 \u0005[כאשר יש]\u0006 \u0003בכור — ליהדר\u0004 \u0005[נחזר]\u0006 על האח ה\u0003גדול\u0004 שהוא ייבם תחילה כשלא רצו כולם לייבם, אבל \u0003כי ליכא\u0004 \u0005[כאשר אין]\u0006 \u0003בכור,\u0004 כגון שהבכור מת כבר — \u0003אין חוזרין אצל גדול,\u0004 שנאמר שהמצוה חלה מעיקרה על הבכור דווקא, ואם אין בכור — אין עוד הבדל איזה אח הוא המייבם! \u0003אלמה תני\u0004 \u0005[מדוע שנה]\u0006 איפוא \u0003אביי קשישא\u0004 \u0005[הזקן]\u0006 (שאיננו אביי המפורסם): \u0003מצוה בגדול\u0004 שבאחים \u0003לייבם, לא רצה\u0004 הגדול — \u0003הולכים אצל אחיו הקטן\u0004 ממנו, הגדול באחים הנותרים, \u0003לא רצה — חוזרים\u0004 שוב \u0003אצל גדול!\u0004 משמע שמחזרים אחר הגדול אפילו כשהבכור אינו רוצה לייבם?","ומשיבים: מן הכתוב אנו למדים שיש לדמות את האח הגדול \u0003כבכור, מה בכור — בכורתו גרמה לו\u0004 שיהיה ראשון שבהם, \u0003אף גדול — גדולתו גרמה לו.\u0004","ושואלים מצד אחר: \u0003ואימא\u0004 \u0005[ואמור]\u0006 \u0003כי\u0004 \u0005[כאשר]\u0006 \u0003בכור מייבם — לישקול\u0004 \u0005[שיקבל]\u0006 \u0003נחלה\u0004 של אחיו המת, אבל \u0003כי\u0004 \u0005[כאשר]\u0006 \u0003מייבם\u0004 אח \u0003פשוט,\u0004 שאינו בכור, ש\u0003לא לישקול\u0004 \u0005[יקח]\u0006 את ה\u0003נחלה\u0004 של אחיו המת! ומשיבים: \u0003אמר קרא\u0004 \u0005[הכתוב]:\u0006 \u0003\"יקום על שם אחיו\"\u0004 (שם ו) — \u0003והרי קם\u0004 כבר, ואם כן הנחלה שייכת למייבם, יהיה מי שיהיה.","ושואלים: אם כן, שלמעשה אין שום הבדל בין בכור לגדול, \u0003ואלא \"בכור\" דקרייה רחמנא\u0004 \u0005[שקראה אותו התורה]\u0006 לאח המייבם,"],["\u0003למאי הלכתא\u0004 \u0005[למה,\u0006 לאיזו \u0005הלכה]\u0006 נכתב כן, ולא נכתב במפורש \"גדול\"? — \u0003לגריעותא\u0004 \u0005[לגריעות],\u0006 כלומר לגרוע מדינו ולהשוותו לבכור: \u0003מה בכור אינו נוטל\u0004 פי שנים בירושה \u0003בראוי כבמוחזק,\u0004 שהבכור אינו מקבל פי שנים אלא רק מן הנכסים הנמצאים בחזקת אביהם בפועל, אבל לא בנכסים הראויים להגיע אליו מאוחר יותר, כגון פרעון חובות — \u0003אף האי\u0004 \u0005[זה]\u0006 היבם, \u0003אינו נוטל\u0004 בירושת אביו בנוסף לחלקו גם את חלק אחיו המת \u0003בראוי כבמוחזק,\u0004 שכל מה שלא היה ברשות אביו בעת מותו, אין ליבם בו גם את חלק אחיו.","\u0003הנטען,\u0004 מי שחשוד, שאנשים טוענים עליו, שבא \u0003על השפחה, ונשתחררה\u0004 אחר כך השפחה, \u0003או\u0004 נטען \u0003על הגויה ונתגיירה — הרי זה לא יכנוס\u0004 (ישא) אותה לאשה, מפני שבזה יגביר עוד את החשד. \u0003ואם\u0004 בכל זאת \u0003כנס — אין מוציאין מידו. הנטען על אשת איש והוציאוה\u0004 בית דין \u0003מתחת ידו\u0004 של בעלה בגללו, \u0003אף על פי שכנס\u0004 הנטען — \u0003יוציא.\u0004","שנינו במשנה שמי שנטען על הגויה ונתגיירה — לא ישאנה. ומדייקים: \u0003הא\u0004 \u0005[הרי],\u0006 מכאן נלמד ש\u0003גיורת מיהא הויא\u0004 \u0005[על כל פנים הריהי],\u0006 אף שכנראה נתגיירה רק כדי שזה ישא אותה לאשה ולא לשם יהדות. \u0003ורמינהי\u0004 \u0005[ומשליכים,\u0006 מראים סתירה\u0005]\u0006 מברייתא: \u0003אחד איש שנתגייר לשום\u0004 \u0005[לשם]\u0006 \u0003אשה, ואחד אשה שנתגיירה לשום איש, וכן מי שנתגייר לשום שולחן מלכים\u0004 שיוכל לשמש בתפקיד גבוה אם יתגייר, או \u0003לשום עבדי שלמה,\u0004 שאף עבדיו ומשרתיו הם חשובים, ונתגייר זה כדי להימנות עימם — כל אלה \u0003אינן גרים,\u0004 אלו \u0003דברי ר' נחמיה.\u0004","\u0003שהיה ר' נחמיה אומר: אחד גירי אריות\u0004 כגון הכותים, שנתגיירו מפני שפחדו מן האריות ששלח בהם ה', כמסופר במלכים ב' פרק יז, \u0003ואחד גירי חלומות\u0004 שהתגיירו בגלל חלום רע שחלמו, \u0003ואחד גירי מרדכי ואסתר\u0004 (כאמור: \"ורבים מעמי הארץ מתיהדים כי נפל פחד היהודים עליהם\". אסתר ח, יז) — כל אלה \u0003אינן גרים, עד שיתגיירו בזמן הזה.\u0004","ותחילה מבררים את הלשון: \u0003בזמן הזה סלקא דעתך\u0004 \u0005[עולה על דעתך]?!\u0006 כיצד יכולים גרי מרדכי להתגייר בזמן הזה? \u0003אלא אימא\u0004 \u0005[אמור]:\u0006 \u0003כבזמן הזה\u0004 כאשר ישראל בגלות ואין בגיור צד הנאה חומרית. ולפי שיטה זו, כיצד תיחשב זו שנתגיירה לשם איש, לגיורת?","ומשיבים: \u0003הא איתמר עלה\u0004 \u0005[הרי\u0006 כבר \u0005נאמר עליה]\u0006 על ברייתא זו, \u0003אמר רב יצחק בר שמואל בר מרתא משמיה\u0004 \u0005[משמו]\u0006 של \u0003רב: הלכה כדברי האומר כולם גרים הם.\u0004","ושואלים: \u0003אי הכי\u0004 \u0005[אם כן]\u0006 שאשה זו נחשבת לגיורת גמורה, \u0003לכתחלה נמי\u0004 \u0005[גם כן]\u0006 יכנוס אותה זה שהיה נטען עליה! ומשיבים: \u0003משום\u0004 מה שאמר \u0003רב אסי. ש\u0004\u0003אמר רב אסי,\u0004 על כגון זה אומרים: \u0003\"הסר ממך עקשות פה ולזות שפתים\u0004 הרחק ממך\u0003\"\u0004 (משלי ד, כד).","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003אין מקבלין גרים לימות המשיח. כיוצא בו לא קבלו גרים לא בימי דוד ולא בימי שלמה. אמר ר' (אליעזר) [אלעזר]: מאי קרא\u0004 \u0005[מהו הפסוק]\u0006 המרמז על כך — שנאמר: \u0003\"הן גור יגור אפס מאותי מי גר אתך עליך יפול\"\u0004 (ישעיהו נד, טו) כלומר, מי שגר עם ישראל בעניים ובגלותם שאין הקדוש ברוך הוא נגלה עליהם (=\"אפס מאותי\") — הוא יהיה אתם גם לעתיד לבוא, \u0003אבל אידך\u0004 \u0005[אחרים]\u0006 — \u0003לא.\u0004","שנינו במשנה ש\u0003הנטען על אשת איש\u0004 והוציאוה בגללו מבעלה — צריך לגרשה אם נשאה הוא. \u0003אמר רב: ובעדים,\u0004 כלומר, שהוציאוה מבעלה הראשון לא בשל חשד בלבד, אלא שהיו עדים שהעידו שזינתה.","\u0003אמר רב ששת: אמינא\u0004 \u0005[אומר אני]\u0006 \u0003כי ניים ושכיב\u0004 \u0005[כאשר נמנם ושכב]\u0006 \u0003רב, אמר להאי שמעתתא\u0004 \u0005[את ההלכה הזו],\u0006 שאינה נכונה. \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003הנטען על אשת איש והוציאוה\u0004 מבעלה \u0003על ידו\u0004 (בגללו), בגלל זה שנטען עליה, ואחר כך נישאה לאדם אחר \u0003ונתגרשה מתחת ידי אחר, אם כנס\u0004 מי שהיה חשוד — \u0003לא יוציא.\u0004","ונברר, \u0003היכי דמי\u0004 \u0005[כיצד בדיוק מדובר]:\u0006 \u0003אי דאיכא\u0004 \u0005[אם\u0006 המדובר \u0005שיש]\u0006 \u0003עדים\u0004 שבא עליה בזמן שהיתה אשת איש, אם כן \u0003כי אתא אחר ואפסקיה לקלא מאי הוי\u0004 \u0005[כאשר בא אחר והפסיק את הקול,\u0006 את השם הרע, \u0005מה יהיה]\u0006 על ידי כך? הרי ודאי אסורה היא לו. \u0003אלא לאו דליכא\u0004 \u0005[האם לא\u0006 מדובר שם \u0005שאין]\u0006 \u0003עדים, וטעמא\u0004 \u0005[והטעם,\u0006 דווקא\u0005]\u0006 \u0003דאתא אחר ואפסקיה לקלא\u0004 \u0005[שבא אחר\u0006 ונשאה \u0005והפסיק את הקול],\u0006 \u0003הא לאו הכי, מפקינן\u0004 \u0005[הרי לולא כן, מוציאים אנו]\u0006 אותה ממנו!","ומשיבים: \u0003אמר לך\u0004 \u0005[\u0006יכול היה \u0005לומר לך]\u0006 \u0003רב: הוא הדין דאף על גב\u0004 \u0005[שאף על פי]\u0006 ש\u0003לא אתא\u0004 \u0005[בא]\u0006 \u0003אחר\u0004 ונשא אותה \u0003ואפסקיה לקלא\u0004 \u0005[והפסיק את הקול],\u0006 גם אז, \u0003אי איכא\u0004 \u0005[אם יש]\u0006 \u0003עדים\u0004 מתחילה — \u0003מפקינן\u0004 \u0005[מוציאים אנו],\u0006 \u0003אי ליכא\u0004 \u0005[אם אין]\u0006 \u0003עדים\u0004 — \u0003לא מפקינן\u0004 \u0005[אין אנו מוציאים],\u0006 \u0003והכי קאמר\u0004 \u0005[וכך אמר],\u0006 כך יש לפרש את הברייתא, שהחידוש שבה הוא: \u0003דאף על גב דאתא\u0004 \u0005[שאף על פי שבא]\u0006 אדם \u0003אחר\u0004 ונשאה \u0003ואפסקיה לקלא\u0004 \u0005[והפסיק את הקול],\u0006 בכל זאת \u0003לכתחלה לא יכנוס\u0004 משום החשד.","\u0003מיתיבי\u0004 \u0005[מקשים]\u0006 ממה ששנינו בברייתא אחרת, נאמר כי מי שטענו עליו שבא על אשת איש, ונתגרשה אותה אשה מבעלה, ואחר כך נשא אותה החשוד לאשה — מוציאים אותה מתחת ידו. ולזה מעירים: \u0003במה דברים אמורים — כשאין לה בנים, אבל יש לה בנים\u0004 מנישואין אלה — \u0003לא תצא\u0004 מן החשוד. שכן אם יוציאוה יבואו אנשים לחשוב שאכן נתברר החשד שזינתה ויתייחסו אל הבנים הללו כממזרים. \u0003ואם באו עדי טומאה\u0004 המעידים שבא על האשה בעודה נשואה לאחר, \u0003אפילו יש לה כמה בנים — תצא.\u0004 הרי שאשה בלא בנים מוציאים אותה מן הנטען אף בחשד בלבד!","ומשיבים: \u0003רב מוקי לה למתניתין\u0004 \u0005[מעמיד\u0006 מסביר \u0005אותה,\u0006 את \u0005משנתנו]\u0006 \u0003ביש לה בנים, ו\u0004רק אם \u0003יש לה\u0004 (עליה) \u0003עדים\u0004 שזינתה מוציאים אותה ממנו. ושואלים: \u0003ומאי דוחקיה\u0004 \u0005[ומה דוחקו]\u0006 של \u0003רב,\u0004 מה גרם לו לדחוק \u0003לאוקמי למתניתין\u0004 \u0005[להעמיד את משנתנו]\u0006 \u0003ביש לה בנים ויש לה עדים, וטעמא דאיכא\u0004 \u0005[והטעם,\u0006 דווקא, כ\u0005שיש]\u0006 \u0003עדים מפקינן\u0004 \u0005[אנו מוציאים],\u0006 \u0003ואי ליכא\u0004 \u0005[ואם אין]\u0006 \u0003עדים לא מפקינן\u0004 \u0005[אין אנו מוציאים],\u0006 \u0003לוקמה\u0004 \u0005[שיעמיד אותה]\u0006 את המשנה \u0003בשאין לה בנים, אף על גב דליכא\u0004 \u0005[אף על פי שאין]\u0006 עליה \u0003עדים?\u0004","\u0003אמר רבא: מתניתין קשיתיה\u0004 \u0005[המשנה\u0006 היתה \u0005קשה לו]\u0006 ומשום הקושי שנוצר תוך דיוק בלשונה של המשנה, היה חייב לפרש בדרך זאת. כי \u0003מאי איריא דתני\u0004 \u0005[מה שייך,\u0006 מדוע דווקא, \u0005ששנה\u0006 במשנה\u0005]\u0006 \u0003\"הוציאוה\u0004 מתחת ידו\u0003\"\u0004? \u0003ליתני\u0004 \u0005[שישנה]\u0006 \u0003\"הוציאה\",\u0004 כלומר, בעלה גירשה! \u0003אלא, כל \"הוציאוה\"\u0004 בלשון רבים כוונתו \u0003בבית דין,\u0004 שדייני בית דין פסקו שחייב להוציאה, \u0003ובית דין\u0004 רק \u0003בעדים הוא דמפקי\u0004 \u0005[שמוציאים]\u0006 אשה מבעלה, ולא על פי שמועה או חשד בלבד.","\u0003ואי בעית אימא\u0004 \u0005[ואם תרצה אמור]\u0006 תירוץ אחר, והוא: \u0003הני מתנייתא\u0004 \u0005[אלה הברייתות,\u0006 המשניות\u0005]\u0006 שהבאנו, שאף בלי עדים מוציאים אשה — כשיטת \u0003רבי היא. דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 אם ראה הבעל ש\u0003רוכל יוצא\u0004 מן הבית, \u0003ו\u0004כאשר נכנס הבעל מצא \u0003אשה\u0004 (אשתו) \u0003חוגרת בסינר,\u0004 כלומר לובשת בגד תחתון, \u0003אמר רבי: הואיל ומכוער הדבר,\u0004 שנראים הדברים שזינתה עמו — \u0003תצא.\u0004 וכן אם נכנס הבעל לאחר צאת הרוכל ומוצא \u0003רוק למעלה מן הכילה,\u0004 ומזה ניתן לחשוב ששכב מישהו במיטה וירק למעלה. אף שלא ראה בפועל מעשה מגונה, \u0003אמר רבי: הואיל ומכוער הדבר — תצא,\u0004"],["\u0003מנעלים הפוכים תחת המטה,\u0004 שהמנעלים מונחים כשחרטומם פונה לעבר המטה (רי\"ד), וזה סימן שאיש זר שנכנס לפי שעה הניחם שם, \u0003אמר רבי: הואיל ומכוער הדבר — תצא.\u0004 על קטע זה תוהים: \u0003מנעלים הפוכים? ליחזי דמאן נינהו\u0004 \u0005[שיראה של מי הם]\u0006 ויברר מי האיש ומה עשה! \u0003אלא: מקום מנעלים הפוכים תחת המטה,\u0004 שבחול שברצפה לא מצא אלא עקבות בלבד של מנעלים כאלה, ועל כך \u0003אמר רבי: הואיל ומכוער הדבר — תצא.\u0004","ומסכמים: \u0003והלכתא כוותיה\u0004 \u0005[והלכה כשיטתו]\u0006 של \u0003רב,\u0004 שאין להתייחס לקול בלא עדות עדים, \u0003והלכתא כוותיה\u0004 \u0005[והלכה כשיטתו]\u0006 של \u0003רבי.\u0004 ותוהים: \u0003קשיא הלכתא אהלכתא\u0004 \u0005[קשה\u0006 מ\u0005הלכה על הלכה],\u0006 שהרי שתי הלכות אלה סותרות לכאורה זו את זו. ומשיבים: \u0003לא קשיא\u0004 \u0005[אינו קשה],\u0006 \u0003הא\u0004 \u0005[זה] —\u0006 \u0003בקלא דפסיק\u0004 \u0005[בקול שפוסק],\u0006 שאז אין מוציאים אלא בעדים, \u0003הא\u0004 \u0005[זה] —\u0006 \u0003בקלא דלא פסיק\u0004 \u0005[בקול שאינו פוסק]\u0006 מוציאים אף בלא עדים. ומפרשים את המקרים: \u0003קלא דלא פסיק וליכא\u0004 \u0005[קול שאינו פוסק ואין]\u0006 \u0003עדים —\u0004 נוהגים \u0003כרבי,\u0004 ומוציא אותה. \u0003קלא דפסיק ואיכא\u0004 \u0005[קול שפוסק ויש]\u0006 \u0003עדים —\u0004 נוהגים \u0003כרב\u0004 שיוציא רק כשיש עדים.","\u0003ו\u0004מבררים: \u0003קלא דלא פסיק\u0004 \u0005[קול שאינו פוסק]\u0006 \u0003עד כמה\u0004 נחשב שאינו פוסק? \u0003אמר אביי: אמרה לי אם\u0004 (אומנתי): \u0003דומי דמתא יומא ופלגא\u0004 \u0005[שמועה,\u0006 קול, \u0005של עיר\u0006 הוא \u0005יום וחצי].\u0006 ומעירים: \u0003ולא אמרן\u0004 \u0005[אמרנו]\u0006 שזהו שיעורו, \u0003אלא\u0004 כש\u0003לא פסק\u0004 הקול \u0003ביני וביני\u0004 \u0005[בינתיים,\u0006 בתוך הזמן\u0005],\u0006 \u0003אבל\u0004 אם \u0003פסק\u0004 הקול \u0003ביני וביני\u0004 \u0005[בינתיים],\u0006 אפילו חזר אחר כך — \u0003הא\u0004 \u0005[הרי]\u0006 \u0003פסק\u0004 ואינו נחשב. \u0003ולא אמרן\u0004 \u0005[אמרנו]\u0006 בקול שנפסק \u0003אלא\u0004 כש\u0003לא פסק מחמת יראה,\u0004 שמתייראים מאדם זה שמדברים עליו, ולכן אין הדבר מתפרסם, \u0003אבל\u0004 אם \u0003פסק מחמת יראה — הרי מחמת יראה הוא\u0004 שפסק, ולא נחשב כקול שנפסק. \u0003ולא אמרן\u0004 \u0005[אמרנו]\u0006 שסומכים על קול \u0003אלא דליכא\u0004 \u0005[\u0006כ\u0005שאין]\u0006 \u0003אויבים\u0004 ידועים לאותו אדם שמרננים אחריו, \u0003אבל\u0004 אם \u0003איכא\u0004 \u0005[יש]\u0006 לו \u0003אויבים\u0004 — יש להניח כי \u0003אויבים הוא דאפקו ליה לקלא\u0004 \u0005[הם שהוציאו את הקול].\u0006","\u0003תנן התם\u0004 \u0005[שנינו שם,\u0006 במשנה\u0005]:\u0006 \u0003המוציא את אשתו משום\u0004 שיצא עליה \u0003שם רע — לא יחזיר\u0004 אותה שוב, אפילו התברר ששקר היה. וכן אם מוציא את אשתו \u0003משום נדר\u0004 שנדרה ואינו יכול לסובלה בגלל הנדר, ומגרש אותה — \u0003לא יחזיר\u0004 אפילו הותר הנדר. \u0003שלח ליה\u0004 \u0005[לו]\u0006 \u0003רבה בר\u0004 רב \u0003הונא לרבה בר רב נחמן: ילמדנו רבנו,\u0004 אם עבר ו\u0003כנס\u0004 אשה זו שאמרו חכמים שלא יחזיר, \u0003מהו שיוציא\u0004 את אשתו בעל כרחו?","\u0003אמר ליה\u0004 \u0005[לו]\u0006 רבה בר רב נחמן: \u0003תנינא\u0004 \u0005[שנינו]:\u0006 \u0003הנטען על אשת איש והוציאה מתחת ידו\u0004 כדין, \u0003אף על פי שכנס — יוציא. אמר ליה\u0004 \u0005[לו]\u0006 רבה בר רב הונא: \u0003מי דמי\u0004 \u0005[האם דומה]\u0006 הדבר לענייננו? \u0003התם\u0004 \u0005[שם]\u0006 במשנתנו נאמר \u0003\"הוציאוה\"\u0004, כלומר על פי בית דין, \u0003והכא\u0004 \u0005[וכאן]\u0006 אמרו \u0003\"הוציאה\"\u0004 הוא עצמו. ושמא אם החזירה — לא יוציאוה ממנו. ומסבירים: \u0003ורבה בר רב נחמן\u0004 שדימה את שתי המשניות סבור כי \u0003מתניתין נמי\u0004 \u0005[\u0006ב\u0005משנתנו גם כן]\u0006 \u0003\"הוציאה\" תנן\u0004 \u0005[שנינו]\u0006 ולא \"הוציאוה\".","ושואלים: \u0003ואכתי מי דמי\u0004 \u0005[ועדיין האם דומה]?\u0006 \u0003הכא\u0004 \u0005[כאן]\u0006 הרי מדובר שיחזירנה \u0003הבעל, והתם\u0004 \u0005[ושם]\u0006 מדובר ב\u0003בועל\u0004 שכנס, והדבר יותר מגונה, לכן יוציא! \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003שפיר דמי אהדדי\u0004 \u0005[יפה\u0006 הם \u0005דומים זה לזה]:\u0006 \u0003הכא אמור רבנן\u0004 \u0005[כאן אמרו חכמים]\u0006 \u0003לא יכנוס, ואם כנס יוציא — הכי נמי אמרי רבנן\u0004 \u0005[כך גם כן אמרו חכמים\u0006 בענייננו\u0005]\u0006 \u0003לא יחזיר, ואם כנס — יוציא.\u0004","ודוחים: \u0003ולא היא,\u0004 אין הדבר כן. כי \u0003התם\u0004 \u0005[שם]\u0006 כשהוא נושא את האשה שנחשד עליה, \u0003אלומי אלמיה לקלא\u0004 \u0005[\u0006הרי הוא \u0005מחזק את הקול\u0006 שיצא עליו\u0005],\u0006 ולפיכך יוציא, ואילו \u0003הכא אמרינן קם ביה בקלא וליתיה\u0004 \u0005[כאן אומרים אנו עמד\u0006 וברר \u0005בו בקול\u0006 זה \u0005ו\u0006מצא ש\u0005אינו\u0006 נכון\u0005].\u0006 ואם כן, אין ממקור זה תשובה לשאלה שנשאלה.","שליח \u0003המביא גט ממדינת הים, ואמר\u0004 כדרך ששליח הבא ממדינת הים צריך לומר כדי להכשיר את הגט: \u0003\"בפני נכתב ובפני נחתם\" — לא ישא את אשתו,\u0004 כלומר את הגרושה הזו, משום שנראה כאילו היה לו ענין בדבר, ומחשיד בכך את עדותו. וכן אם בא אדם והעיד על אדם פלוני ש\u0003מת,\u0004 או אפילו אמר על אדם פלוני \u0003\"\u0004אני \u0003הרגתיו\",\u0004 או \u0003\"\u0004אנו \u0003הרגנוהו\" — לא ישא את אשתו\u0004 של זה שמת לפי עדותו. \u0003ר' יהודה אומר:\u0004 אם אמר \u0003\"הרגתיו\" — לא תנשא אשתו\u0004 כלל, אפילו לא לאחר, שאי אפשר להאמין לעדותו, אבל אם אומר \u0003\"הרגנוהו\" — תנשא אשתו\u0004 לאחרים, אבל לא לו.","ומעירים: \u0003טעמא\u0004 \u0005[הטעם,\u0006 דווקא\u0005]\u0006 שמביא גט \u0003ממדינת הים — דעליה קסמכינן\u0004 \u0005[שעליו אנו סומכים]\u0006 ודיבורו ועדותו הם המקיימים את הגט, \u0003אבל\u0004 המביא גט \u0003מארץ ישראל, דלאו עליה קסמכינן\u0004 \u0005[שלא עליו סומכים אנו],\u0006 שהרי אינו צריך לומר דבר, ואנו סומכים על הגט עצמו — \u0003ישא את אשתו,\u0004 ואין חושדים בו,","ויש לשאול: \u0003והא\u0004 \u0005[והרי]\u0006 מי שהעיד שהבעל \u0003מת, דלאו עליה קסמכינן\u0004 \u0005[שלא עליו,\u0006 על העד בלבד, \u0005סומכים אנו],\u0006 ש\u0003אמר מר\u0004 \u0005[החכם]:\u0006 \u0003אשה דייקא ומינסבא\u0004 \u0005[מדקדקת ונשאת],\u0006 שעיקר הטעם שסומכים על עד אחד להתיר אשה מעיגונה, הוא מפני שאנו מניחים שאין האשה מסתמכת על עדות זו בלבד ובודקת ככל שהיא יכולה, ורק אז היא נישאת לאחר, \u0003וקתני\u0004 \u0005[ושנה]:\u0006 \u0003לא ישא את אשתו!\u0004","ומשיבים: אף על פי כן אינו דומה, כי \u0003התם\u0004 \u0005[שם]\u0006 כשמעיד העד שמת הבעל \u0003ליכא כתבא\u0004 \u0005[אין\u0006 שום \u0005כתב]\u0006 מוכיח על כך, ואילו \u0003הכא, איכא כתבא\u0004 \u0005[כאן, יש כתב]\u0006 של גט, והכתב מסייע לעדות. \u0003דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005]:\u0006 \u0003מה בין גט למיתה,\u0004 שסומכים בהבאת גט גם על אנשים שאין נאמנים להעיד בעדות אשה — \u0003שהכתב\u0004 שבידם, הגט, \u0003מוכיח\u0004.","שנינו במשנה: אם אמר העד \u0003\"מת\", \"הרגתיו\", \"הרגנוהו\" — לא ישא את אשתו.\u0004 ומדקדקים: \u0003הוא ניהו\u0004 \u0005[\u0006המעיד \u0005עצמו]\u0006 \u0003לא ישא את אשתו, הא\u0004 \u0005[הרי,\u0006 אבל\u0005]\u0006 \u0003לאחר תנשא\u0004 על סמך עדות זו.","ותוהים: \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003רב יוסף:\u0004 מי שהעיד \u0003\"פלוני רבעני\u0004 במשכב זכור \u0003לאונסי\"\u0004 — הרי \u0003הוא,\u0004 המעיד שנרבע, \u0003ו\u0004עוד עד \u0003אחר — מצטרפין\u0004 כשני עדים \u0003להרגו\u0004 את הרובע, משום משכב זכר, אבל אם העיד \u0003\"\u0004פלוני רבעני \u0003לרצוני\" —\u0004 הרי לדבריו \u0003רשע הוא,\u0004 שהרי לדבריו שניהם שותפים בעבירה, \u0003והתורה אמרה: \"אל תשת ידך עם רשע להיות עד חמס\"\u0004 (שמות כג, א). ואף כאן כיון שאומר על עצמו שהיה שותף להריגת בעלה והריהו רשע, הרי לדבריו הוא פסול לעדות, ואיך אם כן מקבלים את עדותו ומאמינים לו שהרג?","\u0003וכי תימא\u0004 \u0005[ואם תאמר]\u0006 כי \u0003שאני\u0004 \u0005[שונה]\u0006 \u0003עדות\u0004 על \u0003אשה\u0004 שמת בעלה \u0003דאקילו\u0004 \u0005[שהקילו]\u0006 \u0003בה רבנן\u0004 \u0005[חכמים]\u0006 בהרבה דברים, ושמא אף רשע זה נאמן בעדות אשה — \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003רב מנשה:\u0004"],["\u0003גזלן דדבריהם,\u0004 מי שנחשב כגזלן רק מדברי סופרים, כגון מפריחי יונים ומשחקים בקוביא — אף שפסול לשאר עדויות, \u0003כשר לעדות אשה\u0004 להעיד שמת בעלה, \u0003גזלן דדברי תורה — פסול\u0004 גם \u0003לעדות אשה. נימא\u0004 \u0005[\u0006האם \u0005נאמר]\u0006 כי \u0003רב מנשה\u0004 הוא ש\u0003אמר כר' יהודה,\u0004 שהרי גם ר' יהודה במשנתנו פסל לעדות אשה רשע גמור שהודה שהוא רוצח, אבל לא מי שהודה שהיה בחבורת הרוצחים!","ודוחים: \u0003אמר לך\u0004 \u0005[\u0006יכול היה \u0005לומר לך]\u0006 \u0003רב מנשה: אנא דאמרי\u0004 \u0005[אני,\u0006 מה \u0005שאמרתי],\u0006 הוא \u0003אפילו לרבנן\u0004 \u0005[ל\u0006שיטת \u0005חכמים],\u0006 ואף שחכמים לא התירו רשע מדברי תורה לעדות אשה, כשהעד עצמו אומר \"הרגתיו\" — נאמן, \u0003וטעמא דרבנן הכא\u0004 \u0005[וטעם\u0006 דברי \u0005חכמים כאן]\u0006 הוא \u0003כ\u0004דברי \u0003רבא,\u0004 ש\u0003אמר רבא\u0004 בניגוד לשיטת רב יוסף: שאף אם אמר \"פלוני רבעני לרצוני\" אינו נאמן על עצמו, כי \u0003אדם קרוב אצל עצמו\u0004 וכיון שכך אינו יכול להעיד על עצמו, כמו שאין קרוב אחר כשר להעיד עליו, \u0003ו\u0004לכן \u0003אין אדם משים\u0004 את \u0003עצמו רשע.\u0004 שאין עדותו על עצמו מתקבלת, משום שקרוב הוא. ולכן נאמן להרוג את הרובע, וכן ב\"הרגתיו\" נאמר להוציא את האשה.","ושואלים: \u0003לימא\u0004 \u0005[\u0006האם \u0005לומר]\u0006 לפי הסבר זה ש\u0003רב יוסף\u0004 הוא ש\u0003אמר כר' יהודה?\u0004 ודוחים: \u0003אמר לך\u0004 \u0005[\u0006יכול היה \u0005לומר לך]\u0006 \u0003רב יוסף: אנא דאמרי\u0004 \u0005[אני\u0006 מה \u0005שאמרתי]\u0006 \u0003אפילו לרבנן\u0004 \u0005[ל\u0006דעת \u0005חכמים]\u0006 אמרתי, \u0003ו\u0004לדעתי \u0003שאני\u0004 \u0005[שונה]\u0006 \u0003עדות אשה דאקילו\u0004 \u0005[שהקילו]\u0006 \u0003בה רבנן\u0004 \u0005[חכמים]\u0006 והתירו בה אף רשע גמור. \u0003ורב מנשה,\u0004 הפוסל רשע מדברי תורה אף לעדות אשה, הוא ש\u0003אמר כר' יהודה\u0004 המחלק אף בעדות אשה בין רשע מדברי תורה לרשע מדברי חכמים.","שנינו במשנה שמקבלים עדות מי שאמר \u0003\"הרגתיו\", \"הרגנוהו\".\u0004 ור' יהודה מחלק בין האומר \"הרגתיו\" שפסול לעדות והאומר \"הרגנוהו\" שכשר, ו\u0003תנשא\u0004 אשתו. ושואלים: \u0003מאי שנא\u0004 \u0005[\u0006ב\u0005מה שונה]\u0006 \u0003\"הרגתיו\" ומאי שנא\u0004 \u0005[ו\u0006ב\u0005מה שונה]\u0006 \u0003\"הרגנוהו\"?\u0004 הלא גם כשאומר \"הרגנוהו\" מודה הוא שהיה אחד הרוצחים! \u0003אמר רב יהודה:\u0004 לא שאמר \"הרגנוהו\" במובן שהוא עצמו השתתף בכך, אלא \u0003באומר: אני הייתי עם הורגיו\u0004 בחבורה אחת, אבל לא השתתפתי ברצח.","\u0003והתניא\u0004 \u0005[ו\u0006אכן \u0005כן שנינו\u0006 בברייתא\u0005]\u0006 המוכיחה שזו היא כוונת ר' יהודה: \u0003אמרו לו לר' יהודה, מעשה בליסטים\u0004 (שודד) \u0003אחד שיצא ליהרג ב\u0004עיר \u0003מגיזת קפוטקיא, ואמר להם \"לכו ואמרו לה לאשת שמעון בן כהן: אני הרגתי את בעלה בכניסתי ללוד\", ואמרי לה\u0004 \u0005[ו\u0006יש \u0005אומרים]\u0006 שאמר: \u0003\"בכניסתו ללוד\", והשיאו\u0004 על פי עדות זו \u0003את אשתו.\u0004 משמע שסומכים גם על עדותו של הרוצח עצמו! \u0003אמר להם\u0004 ר' יהודה: \u0003משם\u0004 מביאים אתם \u0003ראיה?!\u0004 שם מדובר \u0003באומר \"אני הייתי עם הורגיו\".\u0004 ותוהים: איך אפשר לפרש כך?","\u0003והא\u0004 \u0005[והרי]\u0006 \u0003\"לסטים\", קתני\u0004 \u0005[שנינו],\u0006 משמע שהוא עצמו היה שודד! ומשיבים: \u0003שנתפס על ידי לסטיות.\u0004 כלומר, נתפס באשמת שוד. ושואלים: \u0003והא\u0004 \u0005[והרי]\u0006 \u0003\"יצא\" ליהרג קתני\u0004 \u0005[שנה],\u0006 משמע שמצאו שבאמת היה רוצח! ומשיבים: היה זה \u0003בי דינא\u0004 \u0005[בית דין]\u0006 של \u0003גוים דלא דייקי וקטלי\u0004 \u0005[שאינם מדקדקים והורגים],\u0006 שכיון שמצאוהו בחבורת השודדים לא בדקו לדעת אם הוא עצמו היה רוצח. ולענייננו ראיה מכאן שר' יהודה מתיר לסמוך רק על עדותו של מי שאומר \"אני הייתי עם הורגיו\", שבכך אינו מרשיע את עצמו.","\u0003החכם\u0004 שבא לפניו דין בין בני הזוג, שנדרה האשה נדר, כגון שאסרה על עצמה את בעלה, ובאו בני הזוג לחכם להתיר את הנדר, ולא מצא פתח לנדר ו\u0003אסר את האשה ב\u0004גלל \u0003נדר\u0004 זה \u0003על בעלה,\u0004 ומשום כך התגרשה ממנו — \u0003הרי זה לא ישאנה\u0004 חכם זה, כדי שלא יחשדו בו שאסר אותה כדי שיוכל הוא לשאתה. אבל אשה ש\u0003מיאנה,\u0004 שהיתה קטנה, ואמרה שאיננה רוצה בבעל שהשיאוה לו אמה ואחיה \u0003או שחלצה בפניו,\u0004 בפני החכם — \u0003ישאנה, מפני שהוא,\u0004 החכם, משמש ב\u0003בית דין\u0004 של שלושה ואינו דן יחידי, ולכך לא יחשדו בו.","שנינו במשנה שהחכם שאסר את האשה בשל נדר, לא ישאנה. ומדייקים: \u0003הא\u0004 \u0005[הרי]\u0006 אם \u0003התירה\u0004 לבעלה ואחר כך נתאלמנה או נתגרשה — \u0003ישאנה.\u0004 ונברר, \u0003במאי עסקינן\u0004 \u0005[במה אנו עוסקים] —\u0006 \u0003אילימא בחד\u0004 \u0005[אם תאמר\u0006 שהיה הוא דיין \u0005אחד] —\u0006 \u0003חד מי מצי מתיר\u0004 \u0005[\u0006דיין \u0005אחד, האם יכול להתיר]\u0006 נדרים? \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003רב אמר ר' חייא בר אבין אמר רב עמרם: תנא\u0004 \u0005[שנה]\u0006 החכם בברייתא: \u0003התרת נדרים בשלשה!\u0004","\u0003ואלא\u0004 תאמר שפה מדובר לא בחכם יחיד, אלא \u0003ב\u0004אחד מתוך \u0003תלתא\u0004 \u0005[שלושה],\u0006 \u0003מי חשידי\u0004 \u0005[האם\u0006 \u0005חשודים]\u0006 שלושתם שכולם הטו את הדין? \u0003והתנן\u0004 \u0005[והרי שנינו\u0006 במשנה\u0005]:\u0006 \u0003מיאנה או שחלצה בפניו — ישאנה, מפני שהוא בית דין.\u0004 משמע שאם היה החכם רק אחד מחברי בית הדין — איננו חשוד!","ומשיבים: \u0003לעולם\u0004 תפרש שמדובר כאן \u0003בחד\u0004 \u0005[ב\u0006דיין \u0005אחד],\u0006 \u0003וכדאמר\u0004 \u0005[וכפי שאמר]\u0006 \u0003רב חסדא אמר ר' יוחנן:\u0004 שמתירים נדרים אף \u0003ביחיד מומחה\u0004 (חכם מובהק) ולא רק בשלושה, \u0003הכא נמי\u0004 \u0005[כאן גם כן]\u0006 מדובר \u0003ביחיד מומחה,\u0004 וכיון שהתיר ביחידי יש מקום לחושדו.","שנינו במשנה שאם \u0003מיאנה או שחלצה\u0004 האשה בפני חכם — יכול לשאתה מפני שהוא היה רק דיין אחד מבית הדין שעסק במיאון או בחליצה. ומדייקים: \u0003טעמא\u0004 \u0005[הטעם,\u0006 דווקא\u0005]\u0006 שהוא \u0003בית דין,\u0004 כלומר, אחד משלושה דיינים. ונדייק \u0003הא בתרי\u0004 \u0005[הרי\u0006 אם היו \u0005בשניים]\u0006 בלבד — \u0003לא,\u0004","ויש לשאול: \u0003מאי שנא מהא דתנן\u0004 \u0005[\u0006ב\u0005מה שונה\u0006 הדבר \u0005מזו ששנינו\u0006 בברייתא\u0005]:\u0006 \u0003עדים החתומים על שדה מקח, ועל גט אשה — לא חשו חכמים לדבר זה\u0004 לאסור עליהם לקנות את השדה או לשאת את האשה, כי אין חושדים בשניים שעשו קנוניה ונתכוונו לכך מתחילה? הרי שאף בשניים אין מקום לחשד! ומשיבים: אכן, באמת גם אם היו שניים, לא היו חשודים, אלא \u0003היא גופה קמשמע לן\u0004 \u0005[\u0006את ההלכה ה\u0005היא עצמה השמיע לנו]\u0006 שצריך שיהיה במיאון בית דין שלם, \u0003לאפוקי ממאן דאמר\u0004 \u0005[להוציא מ\u0006דברי \u0005מי שאומר]\u0006 כי \u0003מיאון\u0004 יכול להיעשות \u0003בפני שנים,\u0004 על כן \u0003קמשמע לן\u0004 \u0005[השמיע לנו]\u0006 ש\u0003מיאון\u0004 אינו נעשה אלא \u0003בשלשה\u0004 דיינים.","ביחס לאלה שאמרו עליהם במשנה שלא ישאו אשה זו, \u0003איבעיא להו\u0004 \u0005[נשאלה להם]\u0006 לחכמים: אם \u0003כנס\u0004 למרות האיסור, \u0003מהו שיוציא? רב כהנא אמר:\u0004 אם \u0003כנס — מוציא, רב אשי אמר: כנס — אינו מוציא. תני להו\u0004 \u0005[שנה להם]\u0006 \u0003רב זוטי דבי\u0004 \u0005[\u0006מ\u0005בית\u0006 מדרשו\u0005]\u0006 של \u0003רב פפי\u0004 לחכמים ברייתא \u0003כדברי האומר כנס אינו מוציא.\u0004","\u0003אמרו ליה רבנן\u0004 \u0005[לו חכמים]\u0006 \u0003לרב אשי:\u0004 הלכה זו שאמרת, שאם כנס אינו מוציא, האם \u0003גמרא\u0004 \u0005[מסורת]\u0006 היא בידך, \u0003או סברא\u0004 \u0005[סברה]\u0006 משלך היא? \u0003אמר להו\u0004 \u0005[להם]:\u0006 \u0003מתניתין\u0004 \u0005[משנתנו]\u0006 \u0003היא,\u0004 כלומר, אני למד דבר זה מדיוק לשון המשנה. ששנינו במשנה: \u0003הנטען\u0004 שבא על ה\u0003שפחה ונשתחררה\u0004 אחר כך, או שבא על ה\u0003גויה ונתגיירה\u0004 לאחר מכן — \u0003הרי זה לא יכנוס\u0004 אותן לאחר שהותרו, \u0003ואם כנס — אין מוציא. אלמא\u0004 \u0005[מכאן]\u0006"]]};
